# Files uploaded by people (images): shown as images, never run anything (ASVS 5.0 V3.2.1).
UPLOAD_CSP = "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"


# Rate limits: the same for every process of the server (WOD_WORKERS), counted in a small file next to the database
# (wod.security.SharedRateLimiter, v50.51).
wsec.configure_shared_limits(DB_PATH.with_name(DB_PATH.stem + '-limites.sqlite3'))
LOGIN_LIMIT = wsec.SharedRateLimiter('login', LOGIN_MAX_ATTEMPTS, LOGIN_WINDOW_SECONDS)
LOGIN_IP_LIMIT = wsec.SharedRateLimiter('login-ip', LOGIN_MAX_ATTEMPTS * 5, LOGIN_WINDOW_SECONDS)
LOGIN_ACCOUNT_LIMIT = wsec.SharedRateLimiter('login-cuenta', LOGIN_MAX_ATTEMPTS * 3, LOGIN_WINDOW_SECONDS)
_DUMMY_HASH = []
def dummy_password_hash():
    if not _DUMMY_HASH: _DUMMY_HASH.append(wsec.hash_password(secrets.token_urlsafe(16)))
    return _DUMMY_HASH[0]
PASSWORD_CHECK_LIMIT = wsec.SharedRateLimiter('contrasena-actual', 10, 900)


def current_password_ok(user_id, password, stored):
    """The «current password» asked to a signed-in person before a sensitive change: at most 10 wrong ones every 15
    minutes (v50.51, security review), so a session left open cannot be used to guess it."""
    key = f'pw:{user_id}'
    if PASSWORD_CHECK_LIMIT.blocked(key): raise PermissionError('Demasiados intentos con la contraseña. Espera unos minutos.')
    if verify_password(password, stored): return True
    PASSWORD_CHECK_LIMIT.hit(key); security_event('current_password_failed', None, user_id); return False


NOTICE_LIMIT = wsec.SharedRateLimiter('avisos', 60, 3600)
REGISTER_LIMIT = wsec.SharedRateLimiter('registro', wcfg.env_int('WOD_REGISTER_MAX_PER_HOUR', 10, 1), 3600)
FORGOT_LIMIT = wsec.SharedRateLimiter('recuperar', 5, 900)
TOTP_LIMIT = wsec.SharedRateLimiter('dos-pasos', 6, 900)
GEOCODE_LIMIT = wsec.SharedRateLimiter('geocodificar', 30, 60)
INFO_LIMIT = wsec.SharedRateLimiter('informacion', 10, 3600)
# ASVS 5.0 V2.4.1: bookings and requests per person and hour, unfinished payments holding spots, Log Book entries a day.
BOOKING_LIMIT = wsec.SharedRateLimiter('reservas', wcfg.env_int('WOD_BOOKING_MAX_PER_HOUR', 20, 1), 3600)
BOOKING_LIMIT_TEXT = 'Has hecho muchas reservas seguidas. Espera un poco o escribe al centro.'
PENDING_PAYMENTS_MAX = 3
LOGBOOK_LIMIT = wsec.SharedRateLimiter('logbook', 60, 86400)

PRIVATE_USER_FIELDS = ('password_hash', 'totp_secret', 'totp_pending_secret', 'email_verify_token', 'totp_recovery', 'totp_last_step', 'marketing_token')

def public_user(user):
    if not user:
        return None
    d = dict(user)
    for k in PRIVATE_USER_FIELDS: d.pop(k, None)
    return d

def login_rate_limited(key):
    return LOGIN_LIMIT.blocked(key)

def record_login_failure(key):
    LOGIN_LIMIT.hit(key)

def clear_login_failures(key):
    LOGIN_LIMIT.reset(key)


def known_network(db, user_id, ip):
    """True when this person signed in successfully from this network (the same IPv4 address, or IPv6 /64) in the last
    90 days. Someone guessing from elsewhere then cannot lock the owner out (ASVS 5.0 V6.3.1, malicious lockout)."""
    mark = wsec.ip_hash(wsec.ip_group(ip))
    since = (datetime.now(timezone.utc) - timedelta(days=90)).isoformat(timespec='seconds')
    rows = db.execute("SELECT details FROM audit_log WHERE user_id=? AND action='login' AND created_at>=? ORDER BY id DESC LIMIT 30", (user_id, since)).fetchall()
    return any(mark in (r['details'] or '') for r in rows)


def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


class _ClosingConnection(sqlite3.Connection):
    """`with connect() as db:` commits or rolls back AND gives the connection back to the pool (or closes it) at the end
    of the request."""
    _pooled = False

    def __exit__(self, exc_type, exc, tb):
        try:
            return super().__exit__(exc_type, exc, tb)
        finally:
            if not (self._pooled and _pool_release(self)): self.close()


# v50.51 (load test): connections are reused. Opening one makes SQLite read the whole schema (~360 objects), about 4 ms
# of CPU per request: a quarter to a half of the server's CPU. Each process (WOD_WORKERS forks) has its own pool.
_POOL = None
_POOL_PID = None


def _pool_release(db):
    if _POOL is None or _POOL_PID != os.getpid() or db.in_transaction: return False
    try:
        db.row_factory = wcif.row_factory
        db.execute('PRAGMA foreign_keys=ON')
        _POOL.put_nowait(db); return True
    except (queue.Full, sqlite3.Error):
        return False


def pool_drain():
    """Closes the pooled connections. Called before fork() (WOD_WORKERS): a SQLite connection must never pass to another
    process (closing it there releases the file locks: «disk I/O error»)."""
    global _POOL, _POOL_PID
    while _POOL is not None:
        try: _POOL.get_nowait().close()
        except queue.Empty: break
    _POOL = None; _POOL_PID = None


def connect():
    global _POOL, _POOL_PID
    if _POOL_PID != os.getpid():
        _POOL = queue.LifoQueue(wcfg.env_int('WOD_DB_POOL', 32, 1, 256)); _POOL_PID = os.getpid()
    try:
        return _POOL.get_nowait()
    except queue.Empty:
        pass
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(DB_PATH, factory=_ClosingConnection, check_same_thread=False)   # one request at a time (the pool)
    db._pooled = True
    # v50.47 (parte C): phones are stored encrypted; rows come back with them in clear for the server code only.
    db.row_factory = wcif.row_factory
    db.execute('PRAGMA foreign_keys=ON')
    db.execute('PRAGMA secure_delete=ON')   # freed space is zeroed: no old value stays readable in the file
    # WAL is persistent (set once in bootstrap); NORMAL sync is safe in WAL mode and much faster for writes.
    db.execute('PRAGMA synchronous=NORMAL')
    db.execute('PRAGMA busy_timeout=10000')
    # fold(): lower-case without accents, so «maria» finds «María».
    return wire_connection(db)


def wire_connection(db):
    """The SQL functions every connection to the database needs (the v50.47 triggers call wod_huella)."""
    db.create_function('fold', 1, fold_text, deterministic=True)
    db.create_function('wod_cifrar', 1, wcif.sql_encrypt)
    db.create_function('wod_huella', 1, wcif.sql_fingerprint)
    return db


_PYTHON_TEXTS = ('invalid literal', 'could not convert', 'cannot convert', 'not enough values', 'too many values', 'unpack',
                 'invalid isoformat', 'is not a valid', 'out of range', 'object has no', 'unhashable', 'must be', 'argument')


def public_error(exc):
    """The text of a ValueError for the visitor: ours are written for people; Python's are replaced (ASVS V16.5.1)."""
    text = str(exc)
    if not text or any(k in text for k in _PYTHON_TEXTS) or text[:1].islower():
        return 'Algún dato enviado no tiene el formato esperado.'
    return text


def denied(handler, db, exc):
    """A signed-in person asked for something they may not: kept in the activity log (ASVS V16.3.2)."""
    try:
        who = current_user(handler, db)
        if who: security_event('access_denied', handler, who['id'])
    except Exception:
        pass


def log_safe(text):
    """Control characters written as \\xNN, so a request cannot forge lines or colours in the logs (ASVS V16.4.1)."""
    return re.sub(r'[\x00-\x1f\x7f]', lambda m: '\\x%02x' % ord(m.group()), str(text))


def log_exception(handler, exc):
    """Unexpected errors go to stderr with the request line (without the query string: it may hold searches or
    coordinates) so they can be traced in production logs. Repeated errors raise an alert (see wod.ops)."""
    import traceback
    try: sys.stderr.write(log_safe(f"[{datetime.now(timezone.utc).isoformat(timespec='seconds')}] {handler.command} {urlparse(handler.path).path} -> {type(exc).__name__}: {exc}") + '\n' + ''.join(traceback.format_exception(exc)[-3:]))
    except Exception: pass
    try: ERROR_MONITOR.record(urlparse(handler.path).path, exc)
    except Exception: pass


class _NullWriter:
    def write(self, data): return len(data)
    def flush(self): pass


PUBLIC_ROOT_FILES = {'/sw.js':'application/javascript; charset=utf-8','/manifest.webmanifest':'application/manifest+json','/robots.txt':'text/plain; charset=utf-8'}
def fold_text(value):
    if value is None: return ''
    return ''.join(ch for ch in unicodedata.normalize('NFKD', str(value).lower()) if not unicodedata.combining(ch))


