def add_columns(db, table, cols):
    have = {r['name'] for r in db.execute(f'PRAGMA table_info({table})').fetchall()}
    for name, typ in cols:
        if name not in have: db.execute(f'ALTER TABLE {table} ADD COLUMN {name} {typ}')


_PACKS = {}


def lang_pack(lang):
    """Exact strings of a language pack (Spanish → language), cached; used for country and region names."""
    if lang not in _PACKS:
        try: _PACKS[lang] = json.loads((ROOT / 'public' / 'idiomas' / f'{lang}.json').read_text(encoding='utf-8')).get('exact', {})
        except (OSError, ValueError): _PACKS[lang] = {}
    return _PACKS[lang]


def point_extras():
    """Facts checked by WORLDIVES for some points (what you see, a practical tip), by point name, in 9 languages."""
    try: return json.loads((ROOT / 'app' / 'data' / 'point_extras.json').read_text(encoding='utf-8'))
    except (OSError, ValueError): return {}


def regenerate_point_texts(db, pid=None):
    """Writes the own description of the points not yet reviewed (or of one point) in the 9 languages.
    The first time, the previous text is kept in description_legacy. Reviewed points are left alone."""
    extras = point_extras(); n = 0
    q = 'SELECT * FROM dive_points WHERE ' + ('id=?' if pid else 'COALESCE(description_reviewed,0)=0')
    for p in db.execute(q, (pid,) if pid else ()).fetchall():
        p = dict(p); ex = extras.get(p['name'])
        texts = {}
        for lang in wpt.LANGS:
            texts[lang], missing = wpt.describe(p, lang, lang_pack(lang) if lang != 'es' else None, ex)
            if lang == 'es': miss_es = missing
        db.execute('UPDATE dive_points SET description_legacy=COALESCE(description_legacy,description), description=?, description_missing=?, description_generated=1 WHERE id=?',
                   (texts['es'], json.dumps(miss_es, ensure_ascii=False), p['id']))
        for lang, txt in texts.items():
            db.execute('INSERT INTO dive_point_texts(point_id,lang,description,updated_at) VALUES(?,?,?,?) ON CONFLICT(point_id,lang) DO UPDATE SET description=excluded.description, updated_at=excluded.updated_at',
                       (p['id'], lang, txt, now()))
        n += 1
    return n


def point_text(db, pid, lang):
    r = db.execute('SELECT description FROM dive_point_texts WHERE point_id=? AND lang=?', (pid, normalize_lang(lang))).fetchone()
    return r['description'] if r else None


DEMO_RIBBON_HTML = ('<div class="demo-ribbon" id="demo-ribbon" role="note"><strong>Versión de demostración</strong> '
                    '<span>Centros, personas y reservas inventados. Pagos de prueba; los correos no salen.</span></div>')
PRODUCTION_DOMAIN = 'worldivesdiscovery.com'   # v50.52: the real site; www and pruebas are subdomains of it


def demo_guard():
    """The test environment (WOD_DEMO_MODE=1, fixed test accounts) never runs as the real site."""
    if not wcfg.demo_mode(): return ''
    hosts = {PRODUCTION_DOMAIN} | {h.strip().lower() for h in os.environ.get('WOD_PRODUCTION_HOSTS', '').split(',') if h.strip()}
    host = (urlparse(wcfg.public_url()).hostname or '').lower().rstrip('.')
    # The domain and every subdomain (www, pruebas…): the test package never runs on the real server (v50.52).
    if wcfg.is_production() or any(host == h or host.endswith('.' + h) for h in hosts):
        return f'WOD_DEMO_MODE=1 no se permite en producción ni con la dirección pública {host or "de producción"}. El entorno de pruebas usa otra dirección (por ejemplo http://127.0.0.1:8100).'
    if any(os.environ.get(k, '').strip().startswith(('sk_live_', 'rk_live_')) for k in ('STRIPE_SECRET_KEY', 'STRIPE_RESTRICTED_KEY')):
        return 'El entorno de pruebas solo admite claves de Stripe en modo test (sk_test_…). Quita la clave real del .env de pruebas.'
    return ''


def reset_demo_database():
    """«Restaurar demo» (test environment only): rebuilds the demonstration data with dates relative to today and
    copies it over the running database. Never available outside WOD_DEMO_MODE (demo_guard keeps it off the real site)."""
    if not wcfg.demo_mode() or demo_guard(): raise PermissionError('Solo disponible en el entorno de pruebas.')
    import subprocess, tempfile
    tmp = Path(tempfile.mkdtemp(prefix='wod-demo-')) / 'demo.sqlite3'
    try:
        res = subprocess.run([sys.executable, str(ROOT / 'scripts' / 'crear_demo.py'), '--out', str(tmp)], capture_output=True, text=True, timeout=300)
        if res.returncode != 0 or not tmp.exists(): raise RuntimeError('No se ha podido crear la demo: ' + (res.stdout + res.stderr)[-400:])
        # The administrator accounts created by the owner in the test environment are kept (with their password).
        live = sqlite3.connect(DB_PATH, timeout=30); live.row_factory = sqlite3.Row
        try:
            cols = [r[1] for r in live.execute('PRAGMA table_info(users)')]
            admins = [dict(r) for r in live.execute("SELECT * FROM users WHERE role='admin'").fetchall()]
        finally: live.close()
        src = wire_connection(sqlite3.connect(tmp))
        try:
            new_cols = {r[1] for r in src.execute('PRAGMA table_info(users)')}
            for a in admins:
                if src.execute('SELECT 1 FROM users WHERE lower(email)=lower(?) OR lower(username)=lower(?)', (a['email'], a['username'])).fetchone(): continue
                keep = [c for c in cols if c in new_cols and c != 'id']
                uid = src.execute(f'INSERT INTO users({",".join(keep)}) VALUES({",".join("?" * len(keep))})', [a[c] for c in keep]).lastrowid
                src.execute('INSERT OR IGNORE INTO user_profiles(user_id,updated_at) VALUES(?,?)', (uid, now()))
            src.commit()
            dst = sqlite3.connect(DB_PATH, timeout=30)
            try: src.backup(dst)
            finally: dst.close()
        finally: src.close()
    finally:
        shutil.rmtree(tmp.parent, ignore_errors=True)


# v50.47 (parte C): diver phones (and the phones of professionals and of the centres' notices) are stored encrypted.
# table: [(column, fingerprint column or None)]
PHONE_COLUMNS = {
    'user_profiles': [('phone', 'phone_hash'), ('emergency_contact_phone', None)],
    'bookings': [('contact_phone', 'contact_phone_hash')],
    'info_requests': [('phone', None)],
    'center_claims': [('phone', None)],
    'messages': [('contact_phone', None)],
}
WHATSAPP_CONSENT_VERSION = '2026-10-12'


def install_phone_guards(db):
    """Triggers: a phone in clear is refused by the database itself; the fingerprint follows the phone."""
    for t, cols in PHONE_COLUMNS.items():
        have = {r['name'] for r in db.execute(f'PRAGMA table_info({t})')}
        for col, hcol in cols:
            if hcol and hcol not in have: db.execute(f'ALTER TABLE {t} ADD COLUMN {hcol} TEXT')
            for when, name in (('BEFORE INSERT', 'ins'), (f'BEFORE UPDATE OF {col}', 'upd')):
                db.execute(f'''CREATE TRIGGER IF NOT EXISTS wod_{t}_{col}_cifrado_{name} {when} ON {t}
                    WHEN NEW.{col} IS NOT NULL AND NEW.{col}<>'' AND substr(NEW.{col},1,5)<>'wdx1:' BEGIN
                    SELECT RAISE(ABORT, 'WOD: teléfono sin cifrar ({t}.{col})'); END''')
            if hcol:
                for when, name, cond in (('AFTER INSERT', 'ins', f'NEW.{col} IS NOT NULL'), (f'AFTER UPDATE OF {col}', 'upd', f'NEW.{col} IS NOT OLD.{col}')):
                    db.execute(f'''CREATE TRIGGER IF NOT EXISTS wod_{t}_{col}_huella_{name} {when} ON {t} WHEN {cond} BEGIN
                        UPDATE {t} SET {hcol}=wod_huella(NEW.{col}) WHERE rowid=NEW.rowid AND {hcol} IS NOT wod_huella(NEW.{col}); END''')
                db.execute(f'CREATE INDEX IF NOT EXISTS idx_{t}_{hcol} ON {t}({hcol}) WHERE {hcol} IS NOT NULL')


# v50.51: the presentation of a centre in the other languages of the web, written by the centre (Escaparate). The texts
# of `centers` (tagline, description) stay the main ones; a visitor whose language has its own text sees that one.
CENTER_TEXTS_SCHEMA = '''CREATE TABLE IF NOT EXISTS center_texts (center_id INTEGER NOT NULL REFERENCES centers(id) ON DELETE CASCADE, lang TEXT NOT NULL,
  tagline TEXT, description TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(center_id, lang))'''
CENTER_TEXT_LANGS = ('es', 'en', 'fr', 'de', 'it', 'pt', 'nl', 'pl', 'zh')


def center_texts(db, cid) -> dict:
    return {r['lang']: {'tagline': r['tagline'] or '', 'description': r['description'] or ''}
            for r in db.execute('SELECT lang,tagline,description FROM center_texts WHERE center_id=? ORDER BY lang', (cid,)).fetchall()}


def save_center_texts(db, cid, texts):
    """{lang: {tagline, description}} from the Escaparate: an empty language is removed."""
    if not isinstance(texts, dict): raise ValueError('Los textos por idioma no son válidos.')
    for lang in CENTER_TEXT_LANGS:
        t = texts.get(lang) if isinstance(texts.get(lang), dict) else {}
        tag, desc = clean_text(t.get('tagline'), 160) or '', clean_text(t.get('description'), 5000) or ''
        if tag or desc:
            db.execute('''INSERT INTO center_texts(center_id,lang,tagline,description,updated_at) VALUES(?,?,?,?,?)
                          ON CONFLICT(center_id,lang) DO UPDATE SET tagline=excluded.tagline,description=excluded.description,updated_at=excluded.updated_at''',
                       (cid, lang, tag, desc, now()))
        else:
            db.execute('DELETE FROM center_texts WHERE center_id=? AND lang=?', (cid, lang))


DIVE_AREAS_SCHEMA = '''CREATE TABLE IF NOT EXISTS dive_areas (id INTEGER PRIMARY KEY AUTOINCREMENT, country TEXT NOT NULL, name TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0, lat_min REAL NOT NULL, lat_max REAL NOT NULL, lon_min REAL NOT NULL, lon_max REAL NOT NULL,
  active INTEGER NOT NULL DEFAULT 1, UNIQUE(country, name))'''


def migrate_v50_53(db):
    """v50.53. Dive sites by distance (computed in the server inside a box of coordinates, with its index) and the areas
    of the launch country for visitors who do not share their location; service templates with their photo, and the
    photo of each service (its template's or its own). Nothing is deleted."""
    db.execute('CREATE INDEX IF NOT EXISTS idx_dive_points_geo ON dive_points(latitude, longitude)')
    db.execute(DIVE_AREAS_SCHEMA)
    db.execute(wtpl.SCHEMA)
    add_columns(db, 'provider_services', [('template_id', 'INTEGER'), ('photo_mode', "TEXT NOT NULL DEFAULT 'template'"), ('photo_base', 'TEXT'),
                                          ('photo_widths', 'TEXT'), ('photo_jpg', 'INTEGER'), ('photo_focal', 'TEXT'), ('photo_veil_light', 'REAL'),
                                          ('photo_veil_dark', 'REAL'), ('photo_status', 'TEXT'), ('photo_by', 'INTEGER'), ('photo_at', 'TEXT'),
                                          ('photo_rights_at', 'TEXT'), ('photo_note', 'TEXT')])
    add_columns(db, 'service_templates', [('template_id', 'INTEGER')])
    if migration_done(db, '50.53'): return
    # Once: what the administration may change afterwards (areas, templates, veil) and the link of the services that
    # already existed. A service created later «Sin plantilla» keeps that choice after a restart.
    for i, (name, la0, la1, lo0, lo1) in enumerate(wgeo.SPAIN_AREAS):
        db.execute('INSERT OR IGNORE INTO dive_areas(country,name,sort_order,lat_min,lat_max,lon_min,lon_max) VALUES(?,?,?,?,?,?,?)',
                   ('España', name, (i + 1) * 10, la0, la1, lo0, lo1))
    db.execute("INSERT OR IGNORE INTO site_settings(key,value) VALUES('home_country','España')")
    wtpl.seed(db, now())
    slugs = {r['slug']: r['id'] for r in db.execute('SELECT id,slug FROM service_catalog').fetchall()}
    linked = 0
    for r in db.execute('SELECT id,title,service_type FROM provider_services WHERE template_id IS NULL').fetchall():
        slug = wtpl.guess_slug(r['title'], r['service_type'])
        if slug in slugs:
            db.execute('UPDATE provider_services SET template_id=? WHERE id=?', (slugs[slug], r['id'])); linked += 1
    db.execute("INSERT OR IGNORE INTO site_settings(key,value) VALUES('card_veil','0.8')")
    db.execute('INSERT INTO schema_migrations(version,applied_at,notes) VALUES(?,?,?)',
               ('50.53', now(), f'Puntos por cercanía, zonas de España y plantillas de servicios con foto ({linked} servicios vinculados a su plantilla)'))


def migrate_v50_52(db):
    """v50.52. Two-step verification mandatory with online payments (ASVS 5.0 V6.3.3): the end of the grace period of
    each account holder that already had payments. Nothing is deleted."""
    add_columns(db, 'users', [('totp_deadline', 'TEXT')])


def migrate_v50_51(db):
    """v50.51. The example species images now come in two sizes (128 px for the round photo of the carousel and 640 px
    for the bubble): their rows say so. Uploaded photos keep the sizes they were stored with. Centres can present
    themselves in every language of the web (center_texts). Nothing is deleted."""
    db.execute("UPDATE species SET photo_widths='128,640' WHERE photo_base LIKE '/img/especies/%' AND COALESCE(photo_widths,'')<>'128,640'")
    db.execute(CENTER_TEXTS_SCHEMA)
    # Load test: the sign-in looks the person up by lower(email) or lower(username); upcoming departures by date.
    db.execute('CREATE INDEX IF NOT EXISTS idx_users_email_lower ON users(lower(email))')
    db.execute('CREATE INDEX IF NOT EXISTS idx_users_username_lower ON users(lower(username))')
    db.execute("CREATE INDEX IF NOT EXISTS idx_service_slots_open_date ON service_slots(slot_date, slot_time) WHERE status='open' AND spots_available>0")
    # ASVS 5.0 (V7.5.2): each session remembers its browser and a fingerprint of the address, so the person can see where
    # it is open and close the others.
    add_columns(db, 'sessions', [('user_agent', 'TEXT'), ('ip_hash', 'TEXT')])
    # ASVS 5.0 (V6.3.1): the networks a person signed in from are looked up by account (known_network).
    db.execute('CREATE INDEX IF NOT EXISTS idx_audit_user_action ON audit_log(user_id, action, id DESC)')
    # Security review (A02-1): the authenticator secrets of the two-step verification are stored encrypted.
    ucols = {r['name'] for r in db.execute('PRAGMA table_info(users)')}
    if wcif.configured():
        for col in ('totp_secret', 'totp_pending_secret'):
            if col not in ucols: continue
            for uid, val in db.execute(f"SELECT id,{col} FROM users WHERE {col} IS NOT NULL AND {col}<>''").fetchall():
                if not wcif.is_secret(val): db.execute(f'UPDATE users SET {col}=? WHERE id=?', (wcif.encrypt_secret(val), uid))
    if migration_done(db, '50.51'): return
    db.execute('INSERT INTO schema_migrations(version,applied_at,notes) VALUES(?,?,?)', ('50.51', now(), 'Carrusel de vida marina, auditoría y paquetes DEMO y PRODUCCIÓN'))


def migrate_v50_50(db):
    """v50.50 (vídeos enlazados y vida marina). Only adds tables and indexes (wod.vidamarina); nothing is deleted.
    The videos of the old «recorridos virtuales» that are YouTube or Vimeo links are copied to the new list of route
    videos, published. Everything else of the old tours (panoramas, Street View, uploaded files) stays in its table as
    it was and is listed in Administración → Vida marina y vídeos → «Recorridos antiguos»."""
    wmarina.install(db)
    if migration_done(db, '50.50'): return
    copied = 0
    for r in db.execute('SELECT * FROM virtual_experiences WHERE active=1 AND url IS NOT NULL').fetchall():
        link = wvideos.legacy_to_link(r['url'])
        if not link or db.execute('SELECT 1 FROM route_videos WHERE legacy_virtual_id=?', (r['id'],)).fetchone(): continue
        if db.execute("SELECT 1 FROM route_videos WHERE dive_point_id=? AND url=? AND active=1 AND status<>'rejected'", (r['dive_point_id'], link['url'])).fetchone(): continue
        kind = '360' if r['experience_type'] in ('video360', 'external360') else 'normal'
        db.execute('''INSERT INTO route_videos(dive_point_id,url,platform,platform_name,video_ref,kind,title,thumb_tries,sort_order,status,contributor_kind,
                      contributor_name,created_by_user_id,reviewed_at,legacy_virtual_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,0,?,'approved','admin',?,?,?,?,?,?)''',
                   (r['dive_point_id'], link['url'], link['platform'], wvideos.BY_KEY[link['platform']].name, link['ref'], kind, r['title'], r['id'],
                    clean_text(r['provider'], 100) or 'WORLDIVES DISCOVERY', r['created_by_user_id'], now(), r['id'], r['created_at'] or now(), '2000-01-01T00:00:00+00:00'))
        copied += 1
    db.execute('INSERT INTO schema_migrations(version,applied_at,notes) VALUES(?,?,?)', ('50.50', now(), f'Vídeos enlazados y vida marina ({copied} vídeos de recorridos antiguos copiados)'))


def migrate_v50_49(db):
    """v50.49 (app, tandas 2 a 4). Only adds tables and columns; nothing is deleted:
    - center_roles: the roles each centre creates and the permissions of each role (wod.roles);
    - provider_closures: centres and freelance professionals that closed their account (six months to come back);
    - app_devices and push_outbox: push notifications to the app (only with Firebase configured in the .env)."""
    db.execute(wroles.SCHEMA)
    db.execute(PROVIDER_CLOSURES_SCHEMA)
    db.execute('CREATE INDEX IF NOT EXISTS idx_provider_closures_ref ON provider_closures(provider_kind, provider_oid)')
    # Phones with the app installed (push, only when Firebase is configured) and the pushes waiting to go out.
    db.execute('''CREATE TABLE IF NOT EXISTS app_devices (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                  token TEXT NOT NULL UNIQUE, platform TEXT, app TEXT, created_at TEXT NOT NULL, last_seen_at TEXT, active INTEGER NOT NULL DEFAULT 1)''')
    db.execute('''CREATE TABLE IF NOT EXISTS push_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL REFERENCES app_devices(id) ON DELETE CASCADE,
                  title TEXT NOT NULL, body TEXT, route TEXT, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL,
                  sent_at TEXT, error TEXT)''')
    db.execute("CREATE INDEX IF NOT EXISTS idx_push_outbox_status ON push_outbox(status, id)")
    if migration_done(db, '50.49'): return
    db.execute('INSERT INTO schema_migrations(version,applied_at,notes) VALUES(?,?,?)', ('50.49', now(), 'App Centro PRO y Freelance PRO: perfiles del equipo por centro'))


def migrate_v50_47(db):
    """v50.47 (encargo «avisos masivos y aislamiento total entre centros»). Adds and transforms; nothing is deleted:
    - tenant schema (wod.inquilinos.install_schema): providers, provider_id NOT NULL + FK, consistency triggers, indexes;
    - a freelance is always its own tenant: the centre an administrator had «attached» to it is cleared (kept in the log);
    - phones encrypted (AES-GCM) with fingerprints for searches; triggers refuse phones in clear;
    - WhatsApp consent of the diver, WhatsApp account of each centre (credentials encrypted), notices (batches + outbox),
      settings of each tenant, random ids (uid) for bookings and departures, session context of the team."""
    first = not migration_done(db, '50.47')
    backup = None
    if first and db.execute('SELECT 1 FROM users LIMIT 1').fetchone(): backup = backup_database(db, 'v50_47') or ''
    report = winq.install_schema(db)
    if first:
        for u in db.execute("SELECT id, center_id FROM users WHERE role='freelance' AND center_id IS NOT NULL").fetchall():
            db.execute('UPDATE users SET center_id=NULL WHERE id=?', (u['id'],))
            audit(db, None, 'freelance_tenant_resolved', 'user', u['id'], {'centro_anterior': u['center_id'], 'motivo': 'un freelance es siempre su propio inquilino (v50.47)'})
    scols = {r['name'] for r in db.execute('PRAGMA table_info(sessions)')}
    if 'active_center_id' not in scols: db.execute('ALTER TABLE sessions ADD COLUMN active_center_id INTEGER')
    if 'meeting_point' not in {r['name'] for r in db.execute('PRAGMA table_info(service_slots)')}: db.execute('ALTER TABLE service_slots ADD COLUMN meeting_point TEXT')
    # Random ids for what leaves for the web in links and notices (B.4).
    for t in ('bookings', 'service_slots'):
        if 'uid' not in {r['name'] for r in db.execute(f'PRAGMA table_info({t})')}: db.execute(f'ALTER TABLE {t} ADD COLUMN uid TEXT')
        db.execute(f"UPDATE {t} SET uid=lower(hex(randomblob(16))) WHERE uid IS NULL")
        db.execute(f'CREATE UNIQUE INDEX IF NOT EXISTS ux_{t}_uid ON {t}(uid)')
        db.execute(f'''CREATE TRIGGER IF NOT EXISTS wod_{t}_uid AFTER INSERT ON {t} WHEN NEW.uid IS NULL BEGIN
            UPDATE {t} SET uid=lower(hex(randomblob(16))) WHERE id=NEW.id; END''')
    # Phones: encrypt what is in clear, then the guards.
    for t, cols in PHONE_COLUMNS.items():
        have = {r['name'] for r in db.execute(f'PRAGMA table_info({t})')}
        for col, hcol in cols:
            if hcol and hcol not in have: db.execute(f'ALTER TABLE {t} ADD COLUMN {hcol} TEXT'); have.add(hcol)
            for rid, val in db.execute(f"SELECT rowid, {col} FROM {t} WHERE {col} IS NOT NULL AND {col}<>'' AND substr({col},1,5)<>'wdx1:'").fetchall():
                db.execute(f'UPDATE {t} SET {col}=? WHERE rowid=?', (wcif.encrypt(str(val).strip()), rid))
            if hcol: db.execute(f'UPDATE {t} SET {hcol}=wod_huella({col}) WHERE {col} IS NOT NULL AND {hcol} IS NULL')
    install_phone_guards(db)
    # WhatsApp consent of the diver (withdrawable; every change also goes to consent_log with the text version).
    pcols = {r['name'] for r in db.execute('PRAGMA table_info(user_profiles)')}
    for col, typ in (('wa_consent', 'INTEGER NOT NULL DEFAULT 0'), ('wa_consent_at', 'TEXT'), ('wa_consent_version', 'TEXT'), ('wa_consent_lang', 'TEXT')):
        if col not in pcols: db.execute(f'ALTER TABLE user_profiles ADD COLUMN {col} {typ}')
    ccols = {r['name'] for r in db.execute('PRAGMA table_info(consent_log)')}
    for col in ('text_version', 'lang', 'source'):
        if col not in ccols: db.execute(f'ALTER TABLE consent_log ADD COLUMN {col} TEXT')
    db.executescript(NOTICES_SCHEMA)
    if first:
        move_tenant_files(db)
        quarantine = {k: v for k, v in report.items() if v}
        if quarantine: audit(db, None, 'tenant_quarantine', 'system', None, quarantine)
        db.execute('INSERT INTO schema_migrations(version,applied_at,backup_path,notes) VALUES(?,?,?,?)',
                   ('50.47', now(), str(backup) if backup else None, 'Aislamiento por centro (provider_id), teléfonos cifrados, WhatsApp por centro y avisos masivos'
                    + (f'; en cuarentena: {quarantine}' if quarantine else '')))


NOTICES_SCHEMA = '''
CREATE TABLE IF NOT EXISTS provider_settings (provider_id TEXT NOT NULL PRIMARY KEY REFERENCES providers(id),
  notice_policy TEXT NOT NULL DEFAULT 'choice' CHECK (notice_policy IN ('choice','refund')),
  reminder_enabled INTEGER NOT NULL DEFAULT 1, reminder_hour INTEGER NOT NULL DEFAULT 18 CHECK (reminder_hour BETWEEN 0 AND 23),
  reminder_bring TEXT, updated_at TEXT, updated_by INTEGER);
CREATE TABLE IF NOT EXISTS whatsapp_accounts (provider_id TEXT NOT NULL PRIMARY KEY REFERENCES providers(id),
  status TEXT NOT NULL DEFAULT 'connected' CHECK (status IN ('connected','reconnect')),
  waba_id TEXT NOT NULL, phone_number_id TEXT NOT NULL, display_number TEXT NOT NULL, token TEXT NOT NULL,
  pnid_hash TEXT NOT NULL UNIQUE, number_hash TEXT NOT NULL UNIQUE, waba_hash TEXT, verified_name TEXT, coexistence INTEGER NOT NULL DEFAULT 0,
  templates TEXT, connected_at TEXT NOT NULL, connected_by INTEGER, last_error TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notice_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, uid TEXT NOT NULL UNIQUE,
  provider_id TEXT NOT NULL REFERENCES providers(id), slot_id INTEGER NOT NULL REFERENCES service_slots(id),
  kind TEXT NOT NULL CHECK (kind IN ('slot_cancelled','slot_changed','reminder')), reason TEXT, note TEXT, policy TEXT,
  new_date TEXT, new_time TEXT, old_time TEXT, new_meeting TEXT, status TEXT NOT NULL DEFAULT 'scheduled'
  CHECK (status IN ('scheduled','undone','running','done','failed','blocked')), run_after TEXT NOT NULL,
  created_by INTEGER, ip_hash TEXT, counts TEXT, result TEXT, created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS ux_notice_batches_cancel ON notice_batches(slot_id) WHERE kind='slot_cancelled' AND status IN ('scheduled','running','done');
CREATE UNIQUE INDEX IF NOT EXISTS ux_notice_batches_reminder ON notice_batches(slot_id) WHERE kind='reminder' AND status<>'undone';
CREATE INDEX IF NOT EXISTS idx_notice_batches_tenant ON notice_batches(provider_id, created_at);
CREATE INDEX IF NOT EXISTS idx_notice_batches_due ON notice_batches(status, run_after);
CREATE TABLE IF NOT EXISTS notice_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, uid TEXT NOT NULL UNIQUE,
  batch_id INTEGER NOT NULL REFERENCES notice_batches(id), provider_id TEXT NOT NULL REFERENCES providers(id),
  slot_id INTEGER NOT NULL REFERENCES service_slots(id), booking_id INTEGER NOT NULL REFERENCES bookings(id), event TEXT NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('whatsapp','email','app')), template TEXT NOT NULL, lang TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sending','sent','delivered','read','failed','blocked','skipped','unknown')),
  recipient TEXT, recipient_name TEXT, origin TEXT, wamid TEXT, email_id INTEGER, message_id INTEGER, skip_reason TEXT,
  attempts INTEGER NOT NULL DEFAULT 0, next_try_at TEXT, last_error TEXT, sent_at TEXT, delivered_at TEXT, read_at TEXT,
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (booking_id, event, channel));
CREATE INDEX IF NOT EXISTS idx_notice_outbox_due ON notice_outbox(status, next_try_at);
CREATE INDEX IF NOT EXISTS idx_notice_outbox_batch ON notice_outbox(batch_id);
CREATE INDEX IF NOT EXISTS idx_notice_outbox_tenant ON notice_outbox(provider_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS ux_notice_outbox_wamid ON notice_outbox(wamid) WHERE wamid IS NOT NULL;
CREATE TABLE IF NOT EXISTS whatsapp_webhook_events (event_key TEXT PRIMARY KEY, received_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notice_refunds (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id INTEGER NOT NULL REFERENCES notice_batches(id),
  provider_id TEXT NOT NULL REFERENCES providers(id), booking_id INTEGER NOT NULL REFERENCES bookings(id), amount REAL NOT NULL, currency TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','working','done','failed','blocked')), result TEXT, attempts INTEGER NOT NULL DEFAULT 0,
  next_try_at TEXT, last_error TEXT, created_at TEXT NOT NULL, done_at TEXT, UNIQUE (batch_id, booking_id));
CREATE INDEX IF NOT EXISTS idx_notice_refunds_tenant ON notice_refunds(provider_id, status);
CREATE TRIGGER IF NOT EXISTS wod_notice_refunds_tenant BEFORE INSERT ON notice_refunds BEGIN
  SELECT RAISE(ABORT, 'WOD: devolución de una reserva de otro centro') WHERE (SELECT provider_id FROM bookings WHERE id=NEW.booking_id) IS NOT NEW.provider_id; END;
CREATE TRIGGER IF NOT EXISTS wod_notice_batches_tenant BEFORE INSERT ON notice_batches BEGIN
  SELECT RAISE(ABORT, 'WOD: aviso de una salida de otro centro') WHERE (SELECT provider_id FROM service_slots WHERE id=NEW.slot_id) IS NOT NEW.provider_id; END;
CREATE TRIGGER IF NOT EXISTS wod_notice_outbox_tenant BEFORE INSERT ON notice_outbox BEGIN
  SELECT RAISE(ABORT, 'WOD: aviso a una reserva de otro centro')
   WHERE (SELECT provider_id FROM bookings WHERE id=NEW.booking_id) IS NOT NEW.provider_id
      OR (SELECT provider_id FROM notice_batches WHERE id=NEW.batch_id) IS NOT NEW.provider_id
      OR (SELECT slot_id FROM notice_batches WHERE id=NEW.batch_id) IS NOT NEW.slot_id; END;
CREATE TRIGGER IF NOT EXISTS wod_notice_outbox_no_move BEFORE UPDATE OF provider_id,booking_id,slot_id,batch_id,channel ON notice_outbox BEGIN
  SELECT RAISE(ABORT, 'WOD: un aviso no cambia de centro ni de destinatario'); END;
'''


def tenant_dir(key):
    """Private folder of a tenant ('c:12' → storage/documents/centros/c-12). Files there have random names and are
    served only by the server after checking the session (B.7)."""
    if not re.fullmatch(r'[cf]:\d+', key or ''): raise NotFound('Centro no encontrado.')
    return 'documents/centros/' + key.replace(':', '-')


def move_tenant_files(db):
    """The insurance documents of centres and freelances move to the folder of their tenant (random name kept)."""
    for table, kind in (('centers', 'c'), ('users', 'f')):
        for r in db.execute(f"SELECT id, insurance_doc FROM {table} WHERE insurance_doc IS NOT NULL AND insurance_doc<>''").fetchall():
            if '/centros/' in r['insurance_doc']: continue
            src = document_file_path(r['insurance_doc'])
            if not src or not src.exists(): continue
            rel = tenant_dir(f"{kind}:{r['id']}") + '/' + secrets.token_hex(16) + src.suffix.lower()
            dst = document_file_path(rel); dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
            try: os.chmod(dst, 0o600)
            except OSError: pass
            db.execute(f'UPDATE {table} SET insurance_doc=? WHERE id=?', (rel, r['id']))
            try: src.unlink()
            except OSError: pass


def migrate_v50_46(db):
    """v50.46 (cambios del 12/10/2026): Russian is retired. Users who had it move to English, and so do the emails
    still waiting in the queue (history untouched). Point texts and legal versions in Russian are kept, not served.
    New: contact_messages (the form of the «Contacto» page)."""
    db.execute("""CREATE TABLE IF NOT EXISTS contact_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, topic TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL,
          message TEXT NOT NULL, booking_ref TEXT, lang TEXT, user_id INTEGER, ip_hash TEXT, status TEXT NOT NULL DEFAULT 'open', done_by INTEGER, done_at TEXT, created_at TEXT NOT NULL)""")
    db.execute("UPDATE user_profiles SET preferred_language='en' WHERE preferred_language='ru'")
    db.execute("UPDATE email_outbox SET lang='en' WHERE lang='ru' AND status IN ('queued','sending','retry')")
    if migration_done(db, '50.46'): return
    # The web is ordered by type: the images the site ships move from /assets/images/ and /assets/brand/ to /img/….
    # Every text column that still points to an old address is rewritten (a full copy is made first when there is
    # activity). Uploads (/assets/uploads/…) keep their address. Nothing is deleted.
    pairs = sorted(legacy_path_map().items(), key=lambda kv: -len(kv[0]))
    backup = None
    tables = [r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")]
    for t in tables:
        cols = [r[1] for r in db.execute(f'PRAGMA table_info("{t}")') if (r[2] or '').upper() in ('TEXT', '')]
        for col in cols:
            if not db.execute(f'SELECT 1 FROM "{t}" WHERE "{col}" LIKE ? LIMIT 1', ('%/assets/%',)).fetchone(): continue
            if backup is None and db.execute('SELECT 1 FROM users LIMIT 1').fetchone(): backup = backup_database(db, 'v50_46') or ''
            for rid, val in db.execute(f'SELECT rowid,"{col}" FROM "{t}" WHERE "{col}" LIKE ?', ('%/assets/%',)).fetchall():
                if not isinstance(val, str): continue
                out = val
                for old, new in pairs: out = out.replace(old, new)
                if out != val: db.execute(f'UPDATE "{t}" SET "{col}"=? WHERE rowid=?', (out, rid))
    db.execute('INSERT INTO schema_migrations(version,applied_at,backup_path,notes) VALUES(?,?,?,?)',
               ('50.46', now(), backup or None, 'Sin ruso (9 idiomas); imágenes de la web en /img/ y mensajes de contacto'))


def migrate_v50_45(db):
    """v50.45 (encargo 2b): the brand name is always WORLDIVES DISCOVERY / WORLDIVES. Only transforms texts of the
    initial catalogue that still used the old spelling; nothing is deleted."""
    if migration_done(db, '50.45'): return
    old = ('World' + ' Dives', 'World' + 'Dives')   # written in two parts so the brand check finds no old spelling
    for col in ('description', 'source_name'):
        db.execute(f"UPDATE dive_points SET {col}=replace(replace({col},?,'WORLDIVES'),?,'WORLDIVES') WHERE {col} LIKE ? OR {col} LIKE ?", (*old, f'%{old[0]}%', f'%{old[1]}%'))
    db.execute('INSERT INTO schema_migrations(version,applied_at,notes) VALUES(?,?,?)', ('50.45', now(), 'Nueva marca: nombre WORLDIVES en el catálogo'))


