def clean_promo_url(v):
    v=(clean_text(v,500) or '').strip()
    if not v: return ''
    if v.startswith('#/') or re.match(r'^https?://[^\s<>"]+$',v,re.I): return v
    if re.match(r'^[a-z0-9.-]+\.[a-z]{2,}(/[^\s<>"]*)?$',v,re.I): return 'https://'+v
    raise ValueError('El enlace debe empezar por https:// (o por #/ para una página de WORLDIVES).')


def _build_promos(db):
    rows=db.execute('SELECT id,kind,title,subtitle,label,url,image_path,starts_on,ends_on,sort_order FROM site_promos WHERE active=1 ORDER BY sort_order,id').fetchall()
    settings={r['key']:r['value'] for r in db.execute("SELECT key,value FROM site_settings WHERE key LIKE 'partners_%'").fetchall()}
    # Associated dive centers for the home band: those with their own logo first, then the ones with most activity.
    centers=[]
    for r in db.execute('''SELECT c.id,c.name,c.city,c.country,c.logo_url FROM centers c
                           LEFT JOIN (SELECT center_id, COUNT(*) n FROM provider_services WHERE active=1 GROUP BY center_id) sv ON sv.center_id=c.id
                           WHERE c.active=1 AND c.verification_status='verified' AND COALESCE(c.logo_consent,0)=1 AND COALESCE(c.logo_url,'')<>''
                           ORDER BY c.name LIMIT 200''').fetchall():
        d=dict(r); logo=(d.pop('logo_url') or '').strip()
        d['logo']=logo if logo and not re.match(r'^https?://[^/]+/?$',logo) else ''
        if d['logo']: centers.append(d)
    total=db.execute('SELECT COUNT(*) FROM centers c WHERE '+public_center_sql()).fetchone()[0]
    return {'items':[dict(r) for r in rows],'settings':settings,'centers':centers,'center_total':total}


def public_promos(db):
    today=_dt.date.today().isoformat(); snap=PROMOS.get(db); st=snap.get('settings') or {}
    # The band appears only with a minimum of associated centres (Administración → Promociones, 6 by default), in random order.
    try: min_c=max(1,int(st.get('partners_min_centers') or 6))
    except ValueError: min_c=6
    band=list(snap.get('centers') or []); random.shuffle(band)
    sponsored_ok=feature_switch(db,'sponsorship')
    out={'partners':[],'offers':[],'centers':band if len(band)>=min_c else [],'center_total':snap.get('center_total') or 0,'centers_min':min_c,'contact':{'email':st.get('partners_email') or '','text':st.get('partners_text') or ''}}
    for p in snap['items']:
        if (p['starts_on'] and p['starts_on']>today) or (p['ends_on'] and p['ends_on']<today): continue
        if p['kind']=='offer' and not p['image_path']: continue
        if not sponsored_ok: continue
        out['partners' if p['kind']=='partner' else 'offers'].append(dict(p,label=SPONSORED_LABEL))
    return out


def invalidate_after_post(path):
    flush_security_alerts()
    _invalidate_after_post(path)


def _invalidate_after_post(path):
    """Catalogue edits show up at once in this process (other worker processes refresh within a minute)."""
    for prefix,*names in SNAPSHOT_WRITE_PREFIXES:
        if path.startswith(prefix):
            for n in names: globals()[n].invalidate()


# ---------------------------------------------------------------------------------------------------------------------
# v50.53 · Plantillas de servicios (Administración) y fotos de las tarjetas de servicio (wod.plantillas, wod.imagenes).
# A service shows its own photo (when the centre uploaded one and it is ready), else its template's, else the neutral
# photo of «Imágenes de la web». The photo is resolved when the page is asked for: changing a template's photo changes it
# at once in every service that uses it. Uploads are checked here and resized in the background (CARD_WORKER).
# ---------------------------------------------------------------------------------------------------------------------
CARD_WORKER = wimg.Worker('tarjetas')
CARD_PHOTO_BYTES = 6 * 1024 * 1024
CARD_VEIL_DEFAULT = 0.8
CARD_DEFAULT_VEIL = {'light': 0.86, 'dark': 0.82}      # an image we have not measured: safe for any photo
SERVICE_NEUTRAL_KEY = 'servicio:neutra'
SERVICE_NEUTRAL_BASE = '/img/servicios/neutra'                # our own drawn deep-water background, in the card sizes
SERVICE_NEUTRAL_DEFAULT = SERVICE_NEUTRAL_BASE + '-960.webp'
PENDING_PHOTOS = STORAGE / 'fotos-pendientes'
CARD_FOLDERS = {'service': 'servicios', 'template': 'plantillas'}
CARD_SMALL_MESSAGE = wimg.CARD_SMALL_MESSAGE
SERVICE_PHOTO_SET = ("photo_mode='own',photo_base=?,photo_widths=?,photo_jpg=?,photo_focal=?,photo_veil_light=?,photo_veil_dark=?,"
                     "photo_status='ready',photo_by=?,photo_at=?,photo_note=NULL,updated_at=?")
TEMPLATE_PHOTO_SET = ("photo_base=?,photo_widths=?,photo_jpg=?,photo_focal=?,photo_veil_light=?,photo_veil_dark=?,photo_status='ready',"
                      "photo_by=?,photo_at=?,updated_at=?")
SERVICE_PHOTO_RAW = ('photo_base', 'photo_widths', 'photo_jpg', 'photo_veil_light', 'photo_veil_dark', 'photo_by', 'photo_rights_at')
SERVICE_PHOTO_CLEAR = ("photo_mode='template',photo_base=NULL,photo_widths=NULL,photo_jpg=NULL,photo_focal=NULL,photo_veil_light=NULL,"
                       "photo_veil_dark=NULL,photo_status=NULL,photo_rights_at=NULL")


def card_veil_setting(db):
    """The administration's veil (0.5–0.95) over the photo of every service card; each photo may need more for AA."""
    r = db.execute("SELECT value FROM site_settings WHERE key='card_veil'").fetchone()
    try: v = float(r['value']) if r else CARD_VEIL_DEFAULT
    except (TypeError, ValueError): v = CARD_VEIL_DEFAULT
    return round(min(0.95, max(0.5, v)), 2)


def local_image_path(url):
    u = str(url or '')
    if u.startswith('/assets/uploads/'):
        p = (PHOTOS / u[len('/assets/uploads/'):]).resolve()
        return p if p.is_relative_to(PHOTOS.resolve()) else None
    if u.startswith('/img/'):
        base = (ROOT / 'public').resolve(); p = (base / u.lstrip('/')).resolve()
        return p if p.is_relative_to(base) else None
    return None


_VEIL_CACHE = {}


def image_veil(url):
    """Minimum veil of an image that did not go through card_photo (the neutral photo, an experience's own photo):
    measured once per file and kept in memory."""
    path = local_image_path(url)
    if not path or not path.exists(): return dict(CARD_DEFAULT_VEIL)
    key = (str(path), path.stat().st_mtime)
    if key not in _VEIL_CACHE:
        try:
            from PIL import Image
            with Image.open(path) as im: _VEIL_CACHE[key] = wimg.veil_needed(im)
        except Exception:
            _VEIL_CACHE[key] = dict(CARD_DEFAULT_VEIL)
    return _VEIL_CACHE[key]


def plain_photo(url, source):
    return {'src': url, 'srcset': '', 'jpg': None, 'focal': '50,50', 'veil': image_veil(url), 'own': False, 'source': source} if url else None


def _build_service_catalog(db):
    rows = [dict(r) for r in db.execute('SELECT * FROM service_catalog ORDER BY sort_order,id').fetchall()]
    for r in rows:
        base = f"/assets/uploads/{CARD_FOLDERS['template']}/{r['photo_base']}" if r['photo_base'] else None
        r['photo'] = wtpl.photo_payload(base, r['photo_widths'], r['photo_jpg'], r['photo_focal'], r['photo_veil_light'], r['photo_veil_dark'], source='template')
    row = db.execute('SELECT image_url FROM site_media WHERE key=?', (SERVICE_NEUTRAL_KEY,)).fetchone()
    chosen = row['image_url'] if row and row['image_url'] and row['image_url'] != SERVICE_NEUTRAL_DEFAULT else None
    if chosen: neutral = plain_photo(chosen, 'neutral')
    else:
        veil = image_veil(SERVICE_NEUTRAL_DEFAULT)
        neutral = wtpl.photo_payload(SERVICE_NEUTRAL_BASE, '480,960,1440', 960, '50,50', veil['light'], veil['dark'], source='neutral')
    return {'rows': rows, 'by_id': {r['id']: r for r in rows}, 'by_slug': {r['slug']: r for r in rows}, 'neutral': neutral}


def service_card_photo(cat, row):
    """The photo of a service's card: its own (uploaded and ready), its template's, or the neutral one."""
    if row.get('photo_mode') == 'own' and row.get('photo_base') and row.get('photo_status') == 'ready':
        p = wtpl.photo_payload(f"/assets/uploads/{CARD_FOLDERS['service']}/{row['photo_base']}", row.get('photo_widths'), row.get('photo_jpg'),
                               row.get('photo_focal'), row.get('photo_veil_light'), row.get('photo_veil_dark'), own=True, source='own')
        if p: return p
    t = cat['by_id'].get(row.get('template_id'))
    if t and t['active'] and t['photo']: return t['photo']
    return cat['neutral']


def template_label(cat, template_id, lang):
    t = cat['by_id'].get(template_id)
    if not t: return None
    name, pending = wtpl.text_in(t['names'], lang)
    return {'id': t['id'], 'slug': t['slug'], 'name': name, 'pending_translation': pending}


def card_fields(db, row, lang='es'):
    """What the shared service card needs besides the service itself (photo and template), for any list."""
    cat = SERVICE_CATALOG.get(db); row = dict(row)
    return {'photo': service_card_photo(cat, row), 'template': template_label(cat, row.get('template_id'), lang),
            'photo_mode': row.get('photo_mode') or 'template', 'photo_status': (row.get('photo_status') or '').split(':', 1)[0] or None}


def experience_card_photo(db, e):
    """A trip or liveaboard: its own photo, else the template of its kind (Viaje / Vida a bordo), else the neutral one."""
    cat = SERVICE_CATALOG.get(db)
    if e.get('image_url') and str(e['image_url']).startswith(('/assets/uploads/', '/img/')): return plain_photo(e['image_url'], 'own')
    kind = fold_text(e.get('kind') or e.get('offer_kind') or '')
    t = cat['by_slug'].get('vida-a-bordo' if 'bordo' in kind else 'viaje')
    return (t['photo'] if t and t['active'] and t['photo'] else None) or cat['neutral']


def delete_card_files(kind, base):
    """Remove every size of a card photo from the disk (a photo that is no longer used)."""
    if not base or not re.fullmatch(r'[a-z0-9-]{4,90}', str(base)): return
    for f in (PHOTOS / CARD_FOLDERS[kind]).glob(f'{base}-*'):
        try: f.unlink()
        except OSError: pass


def check_card_upload(file_info):
    """A photo for a card: JPG, PNG or WEBP of at most 6 MB that opens as an image and passes the antivirus."""
    if not file_info: raise ValueError('Adjunta una foto.')
    content = file_info.get('content') or b''
    if not content: raise ValueError('La foto está vacía.')
    if len(content) > CARD_PHOTO_BYTES: raise ValueError('La foto pesa demasiado. Máximo 6 MB.')
    if wimg.sniff(content) not in ('.jpg', '.png', '.webp'): raise ValueError('Formato no admitido. Usa una foto JPG, PNG o WEBP.')
    try:
        from PIL import Image
        Image.MAX_IMAGE_PIXELS = wimg.MAX_PIXELS
        with Image.open(io.BytesIO(content)) as im:
            size = im.size; im.verify()
    except ImportError:
        size = None
    except Exception:
        raise ValueError('La foto está dañada o no se puede leer. Prueba con otra JPG, PNG o WEBP.')
    # Checked here (not only in the background job) so the centre gets the answer at once; either orientation.
    if size and (max(size) < 320 or min(size) < 180): raise ValueError(CARD_SMALL_MESSAGE)
    antivirus_check(content)
    return content


def queue_card_photo(db, kind, obj_id, content, focal, user_id):
    """Keep the upload in a private folder and resize it in the background; the row says «processing» meanwhile."""
    table = 'provider_services' if kind == 'service' else 'service_catalog'
    PENDING_PHOTOS.mkdir(parents=True, exist_ok=True)
    token = secrets.token_hex(12); tmp = PENDING_PHOTOS / f'{token}.bin'; tmp.write_bytes(content)
    try: os.chmod(tmp, 0o600)
    except OSError: pass
    db.execute(f'UPDATE {table} SET photo_status=? WHERE id=?', ('processing:' + token, obj_id)); db.commit()
    if not CARD_WORKER.submit(process_card_photo, kind, obj_id, token, wtpl.clean_focal(focal), user_id):
        tmp.unlink(missing_ok=True); db.execute(f'UPDATE {table} SET photo_status=NULL WHERE id=?', (obj_id,)); db.commit()
        raise ServiceBusy('Ahora mismo hay muchas fotos en cola. Prueba dentro de un momento.')


def process_card_photo(kind, obj_id, token, focal, user_id):
    """Background job: WebP sizes + JPG, no EXIF/GPS, fingerprint in the name, minimum veil for AA. A newer upload of
    the same card (another token) wins; the photo it replaces is deleted from the disk."""
    tmp = PENDING_PHOTOS / f'{token}.bin'; table = 'provider_services' if kind == 'service' else 'service_catalog'
    db = connect()
    try:
        row = db.execute(f'SELECT * FROM {table} WHERE id=?', (obj_id,)).fetchone()
        if not row or row['photo_status'] != 'processing:' + token or not tmp.exists(): return
        prefix = f's{obj_id}' if kind == 'service' else 't-' + re.sub(r'[^a-z0-9-]+', '-', row['slug'])[:40]
        try:
            res = wimg.card_photo(tmp.read_bytes(), PHOTOS / CARD_FOLDERS[kind], prefix)
        except ValueError as exc:
            db.execute(f'UPDATE {table} SET photo_status=? WHERE id=? AND photo_status=?', ('error:' + str(exc)[:200], obj_id, 'processing:' + token))
            db.commit(); return
        values = (res['base'], ','.join(str(w) for w in res['widths']), res['jpg'], focal, res['veil']['light'], res['veil']['dark'], user_id, now(), now())
        sets = SERVICE_PHOTO_SET if kind == 'service' else TEMPLATE_PHOTO_SET
        cur = db.execute(f'UPDATE {table} SET {sets} WHERE id=? AND photo_status=?', values + (obj_id, 'processing:' + token))
        db.commit()
        if cur.rowcount:
            if row['photo_base'] and row['photo_base'] != res['base']: delete_card_files(kind, row['photo_base'])
            if kind == 'template': SERVICE_CATALOG.invalidate()
        else:
            delete_card_files(kind, res['base'])
    finally:
        tmp.unlink(missing_ok=True); db.close()


def clear_service_photo(db, sid, note=None):
    """Back to the template's photo. Returns the base name of the own photo, to delete it from the disk after commit."""
    row = db.execute('SELECT photo_base FROM provider_services WHERE id=?', (sid,)).fetchone()
    db.execute(f'UPDATE provider_services SET {SERVICE_PHOTO_CLEAR},photo_note=?,updated_at=? WHERE id=?', (note, now(), sid))
    return row['photo_base'] if row else None


def admin_service_catalog(db):
    """«Administración → Plantillas de servicios»: every template with its texts in the 9 languages and how many
    services use it (and how many of them show its photo), plus the own photos of the centres to review."""
    use = {r['template_id']: (r['n'], r['tpl']) for r in db.execute(
        "SELECT template_id,COUNT(*) AS n,SUM(CASE WHEN COALESCE(photo_mode,'template')<>'own' THEN 1 ELSE 0 END) AS tpl "
        "FROM provider_services WHERE template_id IS NOT NULL GROUP BY template_id").fetchall()}
    cat = SERVICE_CATALOG.get(db); out = []
    for r in cat['rows']:
        d = {k: r[k] for k in ('id', 'slug', 'service_type', 'duration_minutes', 'max_participants', 'booking_mode', 'color', 'sort_order', 'active', 'photo_credit', 'photo_at')}
        d['names'] = json.loads(r['names'] or '{}'); d['descriptions'] = json.loads(r['descriptions'] or '{}')
        d['photo'] = r['photo']; d['photo_focal'] = r['photo_focal'] or '50,50'
        st = r['photo_status'] or ''
        d['photo_status'] = st.split(':', 1)[0] or None; d['photo_error'] = st.split(':', 1)[1] if st.startswith('error:') else None
        d['services'], d['services_with_photo'] = use.get(r['id'], (0, 0))
        d['missing_langs'] = [lang for lang in wtpl.LANGS if not d['names'].get(lang) or not d['descriptions'].get(lang)]
        out.append(d)
    own = db.execute(
        "SELECT s.id,s.title,s.photo_mode,s.photo_base,s.photo_widths,s.photo_jpg,s.photo_focal,s.photo_veil_light,s.photo_veil_dark,s.photo_at,s.photo_status,"
        "COALESCE(c.name,u.fullname) AS provider FROM provider_services s JOIN users u ON u.id=s.provider_user_id LEFT JOIN centers c ON c.id=s.center_id "
        "WHERE s.photo_mode='own' AND s.photo_base IS NOT NULL ORDER BY s.photo_at DESC LIMIT 200").fetchall()
    own_out = [{'id': r['id'], 'title': r['title'], 'provider': r['provider'], 'photo_at': r['photo_at'], 'photo': service_card_photo(cat, dict(r))} for r in own]
    return {'items': out, 'veil': card_veil_setting(db), 'neutral': cat['neutral'], 'own_photos': own_out, 'langs': list(wtpl.LANGS)}


def public_service_catalog(db, lang):
    """The templates a centre or freelance can start from, in the language of the page."""
    cat = SERVICE_CATALOG.get(db); out = []
    for r in cat['rows']:
        if not r['active']: continue
        name, pn = wtpl.text_in(r['names'], lang); desc, pd = wtpl.text_in(r['descriptions'], lang)
        out.append({'id': r['id'], 'slug': r['slug'], 'service_type': r['service_type'], 'name': name, 'description': desc, 'pending_translation': pn or pd,
                    'duration_minutes': r['duration_minutes'], 'max_participants': r['max_participants'], 'booking_mode': r['booking_mode'],
                    'color': r['color'], 'photo': r['photo'] or cat['neutral'], 'has_photo': bool(r['photo'])})
    return {'items': out, 'neutral': cat['neutral'], 'veil': card_veil_setting(db)}


def save_catalog_template(db, user, data):
    """Create or change a template (administration). Spanish name required; the rest of languages optional."""
    tid = int(data.get('id') or 0)
    names = wtpl.clean_texts(data.get('names'), 80); descs = wtpl.clean_texts(data.get('descriptions'), 600)
    if not names.get('es'): raise ValueError('Escribe al menos el nombre en castellano.')
    stype = clean_text(data.get('service_type'), 40) or 'inmersion'
    if stype not in SERVICE_TYPES: raise ValueError('Tipo de servicio no válido.')
    mode = data.get('booking_mode') if data.get('booking_mode') in ('auto', 'request', 'payment') else 'auto'
    duration = clean_int(data.get('duration_minutes'), 0, 60 * 24 * 60, 0, 'La duración no es válida.') or None
    places = clean_int(data.get('max_participants'), 0, 999, 0, 'El número de plazas no es válido.') or None
    color = clean_text(data.get('color'), 20) or None
    if color and not re.fullmatch(r'#[0-9a-fA-F]{6}', color): color = None
    order = clean_int(data.get('sort_order'), 0, 100000, 0, 'El orden no es válido.')
    active = 0 if data.get('active') in (0, '0', False, 'false') else 1
    vals = (stype, json.dumps(names, ensure_ascii=False), json.dumps(descs, ensure_ascii=False), duration, places, mode, color, order, active,
            clean_text(data.get('photo_credit'), 200), now(), user['id'])
    if tid:
        if not db.execute('SELECT 1 FROM service_catalog WHERE id=?', (tid,)).fetchone(): raise NotFound('Plantilla no encontrada.')
        db.execute('UPDATE service_catalog SET service_type=?,names=?,descriptions=?,duration_minutes=?,max_participants=?,booking_mode=?,color=?,sort_order=?,'
                   'active=?,photo_credit=?,updated_at=?,updated_by=? WHERE id=?', vals + (tid,))
    else:
        slug = re.sub(r'[^a-z0-9]+', '-', fold_text(names['es'])).strip('-')[:40] or 'plantilla'
        base, n = slug, 2
        while db.execute('SELECT 1 FROM service_catalog WHERE slug=?', (slug,)).fetchone(): slug = f'{base}-{n}'; n += 1
        tid = db.execute('INSERT INTO service_catalog(service_type,names,descriptions,duration_minutes,max_participants,booking_mode,color,sort_order,active,'
                         'photo_credit,updated_at,updated_by,slug,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)', vals + (slug, now())).lastrowid
    audit(db, user['id'], 'service_template_catalog_saved', 'service_catalog', tid)
    return tid


def valid_template_id(db, value):
    """A template a service may use (active), or None."""
    try: tid = int(value or 0)
    except (TypeError, ValueError): return None
    return tid if tid and db.execute('SELECT 1 FROM service_catalog WHERE id=? AND active=1', (tid,)).fetchone() else None


POINTS=Snapshot('points',_build_points)
DIRECTORY=Snapshot('directory',_build_directory)
DIVE_TYPES=Snapshot('dive-types',_build_dive_types)
TRAVEL=Snapshot('travel',_build_travel)
SITE_MEDIA=Snapshot('site-media',_build_site_media)
PROMOS=Snapshot('promos',_build_promos)
SERVICE_CATALOG=Snapshot('service-catalog',_build_service_catalog)


# ---------------------------------------------------------------------------
# Points (v50.35, Fase 3). The old «Monedero» (a balance in €) becomes WORLDIVES points: whole numbers that are
# earned (diving, logging dives, completing bookings) or granted by a centre, and are only exchanged for
# advantages that each centre defines and pays for. Points are not money: they cannot be bought, topped up,
# transferred between users, converted into money or used as a balance in Stripe.
# The ledger (points_ledger) is the single source of truth: balance = SUM(points).
# ---------------------------------------------------------------------------
POINTS_CODE_DAYS = wcfg.env_int('WOD_POINTS_CODE_DAYS', 180, 7, 730)
POINTS_GRANT_CLIENT_MONTH = wcfg.env_int('WOD_POINTS_GRANT_MAX_PER_CLIENT_MONTH', 100, 0, 100000)
POINTS_GRANT_CENTER_MONTH = wcfg.env_int('WOD_POINTS_GRANT_MAX_PER_CENTER_MONTH', 3000, 0, 10000000)
REWARD_TYPES = {'discount': 'Descuento del centro', 'activity': 'Inmersión o actividad', 'course_discount': 'Descuento en un curso',
                'insurance': 'Seguro de día pagado por el centro', 'gift': 'Regalo o ventaja del centro'}
LEGACY_REWARD_TYPES = {'dive_credit': 'activity', 'day_insurance': 'insurance'}
POINT_KINDS = ('earned', 'granted', 'redeemed', 'reversal', 'migrated', 'adjust')


def points_add(db, user_id, points, kind, description, ref_type=None, ref_id=None, center_id=None, actor=None):
    if kind not in POINT_KINDS: raise ValueError('Movimiento de puntos no válido.')
    points = int(points)
    if not points: return None
    return db.execute('''INSERT INTO points_ledger(user_id,points,kind,description,ref_type,ref_id,center_id,created_by,created_at)
                         VALUES(?,?,?,?,?,?,?,?,?)''', (user_id, points, kind, description, ref_type, ref_id, center_id, actor, now())).lastrowid


def points_balance(db, user_id):
    return int(db.execute('SELECT COALESCE(SUM(points),0) FROM points_ledger WHERE user_id=?', (user_id,)).fetchone()[0] or 0)


def points_earned(db, user_id):
    """Points ever earned (levels never go down when the diver exchanges points)."""
    return int(db.execute("SELECT COALESCE(SUM(points),0) FROM points_ledger WHERE user_id=? AND kind IN ('earned','granted','migrated') AND points>0", (user_id,)).fetchone()[0] or 0)


def reward_type_label(t):
    return REWARD_TYPES.get(LEGACY_REWARD_TYPES.get(t, t), REWARD_TYPES['gift'])


def run_points_jobs(db):
    """Maintenance: exchange codes not used before they expire give the points back to the diver."""
    for r in db.execute("SELECT rr.*, ro.title FROM reward_redemptions rr JOIN reward_offers ro ON ro.id=rr.offer_id WHERE rr.status='issued' AND rr.expires_at IS NOT NULL AND rr.expires_at<? LIMIT 200",
                        (now(),)).fetchall():
        if db.execute("UPDATE reward_redemptions SET status='expired' WHERE id=? AND status='issued'", (r['id'],)).rowcount == 1:
            points_add(db, r['user_id'], int(r['cost_points'] or 0), 'reversal', 'Código caducado sin usar: ' + r['title'], 'reward_redemption', r['id'])
            if r['offer_id']: db.execute('UPDATE reward_offers SET stock=stock+1 WHERE id=? AND stock IS NOT NULL', (r['offer_id'],))
        db.commit()


def redemption_row(r):
    d = dict(r)
    for k in ('cost_wallet',): d.pop(k, None)
    d['reward_type_label'] = reward_type_label(d.get('reward_type'))
    return d


def ensure_reward_event(db, user_id, event_key, title, description, points=0):
    """An achievement, awarded once per user and key. Its points go to the points ledger (Fase 3)."""
    row = db.execute('SELECT id FROM reward_events WHERE user_id=? AND event_key=?', (user_id, event_key)).fetchone()
    if row:
        return False
    eid = db.execute('INSERT INTO reward_events(user_id,event_key,title,description,points,wallet_amount,created_at) VALUES(?,?,?,?,?,0,?)',
                     (user_id, event_key, title, description, int(points or 0), now())).lastrowid
    db.execute('INSERT INTO rewards(user_id,title,description,points,completed,created_at) VALUES(?,?,?,?,1,?)',
               (user_id, title, description, int(points or 0), now()))
    points_add(db, user_id, int(points or 0), 'earned', title, 'reward_event', eid)
    return True


LOGBOOK_POINTS_PER_DAY = 4
LOGBOOK_POINTS_PER_ENTRY_DAY = 10


def logbook_reverse_points(db, user_id, entry_id):
    """Deleting a Log Book entry takes back the points it gave (the milestones already reached are kept)."""
    ev = db.execute('SELECT id, points FROM reward_events WHERE user_id=? AND event_key=?', (user_id, f'logbook:dive:{entry_id}')).fetchone()
    if not ev or not ev['points']: return
    if db.execute("SELECT 1 FROM points_ledger WHERE user_id=? AND kind='reversal' AND ref_type='reward_event' AND ref_id=?", (user_id, ev['id'])).fetchone(): return
    points_add(db, user_id, -int(ev['points']), 'reversal', 'Inmersión borrada del Log Book', 'reward_event', ev['id'])


def sync_user_rewards(db, user_id):
    """Automatically award lightweight rewards for actions the diver already performs."""
    profile = db.execute('SELECT * FROM user_profiles WHERE user_id=?', (user_id,)).fetchone()
    user = db.execute('SELECT * FROM users WHERE id=?', (user_id,)).fetchone()
    if not user:
        return
    # Profile completion is intentionally simple: no daily check-in or artificial engagement.
    if profile and profile['phone'] and profile['city'] and profile['certification_id']:
        ensure_reward_event(db, user_id, 'profile_complete', 'Perfil preparado',
                            'Has completado los datos esenciales de tu perfil de buceador.', 50)
    dives = db.execute('SELECT id, dive_date, created_at FROM logbook_entries WHERE user_id=? AND (dive_date IS NULL OR dive_date<=?) ORDER BY id', (user_id, _dt.date.today().isoformat())).fetchall()
    dive_count = len(dives)
    # Every real logbook entry gives a modest amount of progression; no monetary credit per dive. At most
    # LOGBOOK_POINTS_PER_DAY entries of the same day give points (nobody does more dives a day), and deleting an
    # entry takes its points back (logbook_reverse_points), so the Log Book cannot be used to farm points.
    # ASVS 5.0 V2.3.2: the date of the dive is chosen by the diver, so points also stop after
    # LOGBOOK_POINTS_PER_ENTRY_DAY entries added the same day (an old Log Book is copied over several days).
    per_day, per_entry_day = {}, {}
    for dive in dives:
        per_day[dive['dive_date']] = per_day.get(dive['dive_date'], 0) + 1
        added = (dive['created_at'] or '')[:10]
        per_entry_day[added] = per_entry_day.get(added, 0) + 1
        if per_day[dive['dive_date']] > LOGBOOK_POINTS_PER_DAY or per_entry_day[added] > LOGBOOK_POINTS_PER_ENTRY_DAY: continue
        ensure_reward_event(db, user_id, f'logbook:dive:{dive[0]}', 'Inmersión registrada',
                            'Has añadido una inmersión a tu Log Book.', 10)
    milestones = [
        (1, 'first_dive', 'Primera inmersión', 'Tu primera inmersión queda registrada en WORLDIVES.', 50, 0),
        (5, 'dives_5', '5 inmersiones', 'Cinco inmersiones registradas en tu Log Book.', 100, 0),
        (10, 'dives_10', '10 inmersiones', 'Diez inmersiones registradas.', 150, 0),
        (25, 'dives_25', '25 inmersiones', 'Has alcanzado 25 inmersiones.', 300, 0),
        (50, 'dives_50', '50 inmersiones', 'Has alcanzado 50 inmersiones.', 600, 0),
        (100, 'dives_100', '100 inmersiones', 'Has alcanzado 100 inmersiones.', 1200, 0),
    ]
    for target,key,title,desc,pts,_ in milestones:
        if dive_count >= target:
            ensure_reward_event(db, user_id, key, title, desc, pts)
    # Documents: only one modest bonus per useful document type.
    for doc_type, label in [('Titulación','Titulación guardada'), ('Seguro','Seguro guardado')]:
        if db.execute('SELECT 1 FROM user_documents WHERE user_id=? AND lower(document_type)=lower(?) LIMIT 1', (user_id, doc_type)).fetchone():
            ensure_reward_event(db, user_id, 'document:'+doc_type.lower(), label,
                                'Has preparado documentación útil para reservar con tranquilidad.', 25)
    # Completed reservations are valuable but not spammy.
    bookings = db.execute("SELECT id FROM bookings WHERE user_id=? AND status='completed' ORDER BY id", (user_id,)).fetchall()
    for b in bookings:
        ensure_reward_event(db, user_id, f'booking:completed:{b[0]}', 'Inmersión completada con un centro',
                            'Has completado una reserva de buceo.', 40)
    # Visiting a center through its QR is rewarded once per center.
    centers = db.execute('SELECT center_id FROM center_links WHERE user_id=? GROUP BY center_id', (user_id,)).fetchall()
    for c in centers:
        ensure_reward_event(db, user_id, f'center:visit:{c[0]}', 'Centro visitado',
                            'Has hecho check-in en un centro de buceo.', 20)


def reward_level(total_points):
    levels = [(0,'Explorador'),(250,'Buceador'),(750,'Explorador del mundo'),(1500,'Navegante'),(3000,'Embajador WORLDIVES'),(6000,'Leyenda')]
    current=levels[0]
    nxt=None
    for item in levels:
        if total_points >= item[0]: current=item
        elif nxt is None: nxt=item
    return {'name':current[1], 'threshold':current[0], 'next_threshold':nxt[0] if nxt else None, 'next_name':nxt[1] if nxt else None}


def reward_offer_row(row):
    d=dict(row)
    return d


# ---------------------------------------------------------------------------
# Online payments (v50.29): one place decides whether a centre can take card payments and
# one function confirms a payment, whoever reports it first (Stripe webhook, return page or sweeper).
# ---------------------------------------------------------------------------
def stripe_secret():
    # Demo deployments never take real payments (Fase 5.9): only a Stripe TEST key works there (the 4242 card of
    # README-PRUEBAS.md); without one every centre shows «pago en el centro». A live key stops the start (demo_guard).
    key = os.environ.get('STRIPE_SECRET_KEY','').strip()
    if wcfg.demo_mode() and not key.startswith(('sk_test_', 'rk_test_')): return ''
    return key


def stripe_module():
    """The Stripe library configured with the secret key. WOD_STRIPE_API_BASE points it to a local simulator in tests."""
    import stripe
    stripe.api_key = stripe_secret()
    base = os.environ.get('WOD_STRIPE_API_BASE', '').strip()
    if base: stripe.api_base = base
    return stripe


def center_payments_ready(center):
    """True when WORLDIVES can charge cards for this centre: platform keys + a finished Stripe Connect account."""
    if not center or not stripe_secret(): return False
    keys=center.keys() if hasattr(center,'keys') else center
    return bool(('stripe_account_id' in keys and center['stripe_account_id']) and int(center['stripe_charges_enabled'] or 0) and int(center['stripe_payouts_enabled'] or 0))


def _obj(o,k,default=None):
    try:
        if isinstance(o,dict): return o.get(k,default)
        if isinstance(o,sqlite3.Row): return o[k] if k in o.keys() else default
        return getattr(o,k,default)
    except Exception: return default


def finalize_paid_order(db, order, session, source):
    """Marks a payment order as paid after checking the amount, confirms its booking and keeps the spots.
    Idempotent: calling it twice changes nothing. Returns (ok, message)."""
    if order['status']=='paid': return True,'already'
    pay_status=_obj(session,'payment_status'); total=_obj(session,'amount_total'); cur=(_obj(session,'currency') or '').upper()
    expected=wmoney.to_minor(order['amount'],order['currency'])   # v50.45: JPY and other zero-decimal currencies are never × 100
    if pay_status not in ('paid','no_payment_required'): return False,'not_paid'
    if total is not None and int(total)!=expected or (cur and cur!=(order['currency'] or 'EUR').upper()):
        db.execute("UPDATE payment_orders SET status='review',updated_at=? WHERE id=?",(now(),order['id']))
        if order['booking_id']: db.execute("UPDATE bookings SET payment_status='review',updated_at=? WHERE id=? AND payment_status<>'paid'",(now(),order['booking_id']))
        audit(db,order['user_id'],'payment_amount_mismatch','payment_order',order['id'],{'expected':expected,'received':total,'currency':cur,'source':source})
        if order['booking_id']: notify_booking(db,order['booking_id'],'payment_review')
        return False,'mismatch'
    receipt=brand=last4=None
    pi=_obj(session,'payment_intent'); pi_id=pi if isinstance(pi,str) else _obj(pi,'id')
    if pi and not isinstance(pi,str):
        ch=_obj(pi,'latest_charge')
        if ch and not isinstance(ch,str):
            receipt=_obj(ch,'receipt_url'); card=_obj(_obj(ch,'payment_method_details') or {},'card') or {}
            brand=_obj(card,'brand'); last4=_obj(card,'last4')
    received=(wmoney.from_minor(total,order['currency']) if total is not None else float(order['amount'] or 0))
    if db.execute("UPDATE payment_orders SET status='paid',provider_payment_id=COALESCE(?,provider_payment_id),payment_intent_id=COALESCE(?,payment_intent_id),paid_at=?,amount_received=?,receipt_url=COALESCE(?,receipt_url),card_brand=COALESCE(?,card_brand),card_last4=COALESCE(?,card_last4),updated_at=? WHERE id=? AND status<>'paid'",
               (_obj(session,'id'),pi_id,now(),received,receipt,brand,last4,now(),order['id'])).rowcount==0:
        return True,'already'   # otra petición (webhook, vuelta de Stripe, revisión periódica) lo confirmó a la vez
    deposit=(order['payment_kind'] if 'payment_kind' in order.keys() else 'full')=='deposit'
    if order['booking_id']:
        b=db.execute('SELECT * FROM bookings WHERE id=?',(order['booking_id'],)).fetchone()
        if b:
            reserved=int(b['slot_reserved'] or 0); st=wbk.normalize_state(b['status'])
            was_visible=st in ('requested','accepted_pending_payment','confirmed')
            late=st in ('expired','cancelled','rejected')
            days_lost=False
            if db.execute('SELECT 1 FROM booking_days WHERE booking_id=?',(b['id'],)).fetchone():
                # v50.44: a late payment of a booking by days takes its days again if they are still free.
                try: claim_booking_days(db,b)
                except ValueError: days_lost=True
            if (b['slot_id'] and not reserved) or days_lost:
                # The hold was released (late payment): take the spots again if they are still there.
                if not days_lost and reserve_slot_spots(db,b['slot_id'],max(1,int(b['participants'] or 1))): reserved=1
                else:
                    # No spots left for a late payment: never a phantom booking. The payment goes to review/refund.
                    db.execute("UPDATE payment_orders SET status='review',updated_at=? WHERE id=?",(now(),order['id']))
                    db.execute("UPDATE bookings SET payment_status='review',updated_at=? WHERE id=?",(now(),b['id']))
                    audit(db,order['user_id'],'payment_after_slot_full','booking',b['id'],{'source':source})
                    notify_booking(db,b['id'],'payment_review')
                    return False,'late_no_spots'
            # A payment confirmed by Stripe is the ONLY way a «Pago al reservar» booking becomes confirmed.
            paid_total=round(float(b['amount_paid'] or 0)+received,2); due=round(max(0.0,float(b['price'] or 0)-paid_total),2)
            db.execute("UPDATE bookings SET payment_status=?,amount_paid=?,amount_due=?,status=CASE WHEN status IN ('pending','requested','payment_in_progress','accepted_pending_payment','confirmed','expired') THEN 'confirmed' ELSE status END,confirmed_at=COALESCE(confirmed_at,?),slot_reserved=?,expired_reason=NULL,updated_at=? WHERE id=?",
                       ('deposit_paid' if deposit and due>0 else 'paid',paid_total,due,now(),reserved,now(),b['id']))
            body=(f'Hemos recibido la señal de {received:.2f} {order["currency"] or "EUR"}. Tu reserva #{b["id"]} está confirmada; el resto ({due:.2f} {order["currency"] or "EUR"}) se paga en el centro.'
                  if deposit and due>0 else f'Hemos recibido tu pago de {received:.2f} {order["currency"] or "EUR"}. Tu reserva #{b["id"]} está confirmada.')
            db.execute("INSERT INTO messages(sender_user_id,recipient_user_id,booking_id,subject,body,created_at,kind) VALUES(?,?,?,?,?,?,'system')",(order['provider_user_id'] or b['user_id'],b['user_id'],b['id'],'Pago recibido · reserva confirmada',body,now()))
            notify_booking(db,b['id'],'paid',{'was_confirmed':st=='accepted_pending_payment' or (was_visible and st=='confirmed'),'late':late})
            reject_overlapping_requests(db,b)
    if order['experience_booking_id']:
        db.execute("UPDATE experience_bookings SET status='confirmed',payment_status='paid',amount_paid=COALESCE(amount_paid,0)+?,updated_at=? WHERE id=?",(received,now(),order['experience_booking_id']))
    audit(db,order['user_id'],'payment_completed','payment_order',order['id'],{'provider':'stripe','source':source})
    return True,'paid'


def release_order_hold(db, order, new_status):
    """A Checkout ended without payment. «Pago al reservar»: the booking expires and its spots are freed at once
    (it never existed for the centre). «Bajo petición» accepted: the spots stay held until the payment deadline."""
    db.execute('UPDATE payment_orders SET status=?,updated_at=? WHERE id=?',(new_status,now(),order['id']))
    if order['booking_id']:
        b=db.execute('SELECT * FROM bookings WHERE id=?',(order['booking_id'],)).fetchone()
        if not b or b['payment_status']=='paid': return
        if wbk.normalize_state(b['status'])=='payment_in_progress':
            expire_checkout(order)
            release_booking_spots(db,b)
            db.execute("UPDATE bookings SET status='expired',expired_reason=?,payment_status='not_paid',updated_at=? WHERE id=?",('payment_cancelled' if new_status=='cancelled' else 'hold_expired',now(),b['id']))
        elif wbk.normalize_state(b['status'])=='accepted_pending_payment':
            db.execute("UPDATE bookings SET payment_status='required',updated_at=? WHERE id=?",(now(),b['id']))


def sweep_payment_orders():
    """Every few minutes: confirm payments whose webhook never arrived and free the spots of abandoned checkouts."""
    while True:
        time.sleep(300)
        db=None
        try:
            db=connect(); limit=datetime.now(timezone.utc).timestamp()-40*60
            for o in db.execute("SELECT * FROM payment_orders WHERE status='pending' ORDER BY id LIMIT 200").fetchall():
                try: created=datetime.fromisoformat(o['created_at']).timestamp()
                except Exception: continue
                if created>limit: continue
                done=False
                if stripe_secret() and o['provider_payment_id']:
                    try:
                        sess=stripe_session(o)
                        if _obj(sess,'payment_status')=='paid': finalize_paid_order(db,o,sess,'sweeper'); done=True
                        elif _obj(sess,'status')=='open': expire_checkout(o)
                    except Exception as exc: sys.stderr.write(f'[pagos] no se pudo revisar el pedido {o["id"]}: {exc}\n')
                if not done: release_order_hold(db,o,'expired')
                db.commit()
        except Exception as exc:
            sys.stderr.write(f'[pagos] revisión periódica: {exc}\n')
        finally:
            if db: db.close()


# ---------------------------------------------------------------------------
# Automatic emails (v50.30)
# Every email is rendered at the moment of the event (in the recipient's language) and stored in
# email_outbox inside the same transaction as the change that caused it. A background sender
# delivers the queue through SMTP (WOD_SMTP_*). Without SMTP configured nothing is lost: emails
# wait in the outbox and the administrator can read them in Administración → Correos.
# ---------------------------------------------------------------------------
import smtplib as _smtplib
from email.message import EmailMessage as _EmailMessage
from email.utils import formataddr as _formataddr, make_msgid as _make_msgid
from datetime import timedelta as _timedelta

# The 9 languages of the site (v50.33, ru retired in v50.46). Retired: ja, ko, ru → en and zt → zh (see normalize_lang).
MAIL_LANGS = ('es', 'en', 'fr', 'de', 'it', 'pt', 'pl', 'nl', 'zh')   # v50.46: Russian retired (no Stripe or cards there)
HTML_LANG = {'zh': 'zh-Hans'}
_EMAIL_I18N = {}


def email_i18n(lang):
    """Translations of the email texts (Spanish source → language), kept in app/emails/<lang>.json."""
    if lang in _EMAIL_I18N: return _EMAIL_I18N[lang]
    d = {}
    try:
        p = ROOT / 'app' / 'emails' / f'{lang}.json'
        if lang != 'es' and p.exists(): d = json.loads(p.read_text(encoding='utf-8'))
    except Exception as exc:
        sys.stderr.write(f'[correo] traducciones {lang}: {exc}\n')
    _EMAIL_I18N[lang] = d
    return d


class _SafeDict(dict):
    def __missing__(self, key): return ''


def mail_t(lang, text, **kw):
    s = email_i18n(lang).get(text, text) if lang and lang != 'es' else text
    try: return s.format_map(_SafeDict(kw))
    except Exception:
        try: return text.format_map(_SafeDict(kw))
        except Exception: return text


def public_site_url():
    return (os.environ.get('WOD_PUBLIC_URL', '').strip() or f'http://localhost:{PORT}').rstrip('/')


def smtp_config():
    host = os.environ.get('WOD_SMTP_HOST', '').strip()
    site_host = urlparse(public_site_url()).hostname or ''
    default_from = f'no-reply@{site_host}' if '.' in site_host and not site_host.replace('.', '').isdigit() else 'no-reply@worldives.local'
    try: port = int(os.environ.get('WOD_SMTP_PORT', '587') or 587)
    except ValueError: port = 587
    return {'host': host, 'port': port,
            'user': os.environ.get('WOD_SMTP_USER', '').strip(), 'password': os.environ.get('WOD_SMTP_PASSWORD', ''),
            'security': (os.environ.get('WOD_SMTP_SECURITY', 'starttls') or 'starttls').strip().lower(),
            'from': os.environ.get('WOD_MAIL_FROM', '').strip() or default_from,
            'from_name': os.environ.get('WOD_MAIL_FROM_NAME', 'WORLDIVES DISCOVERY').strip() or 'WORLDIVES DISCOVERY',
            'reply_to': os.environ.get('WOD_MAIL_REPLY_TO', '').strip(), 'enabled': bool(host) and not wcfg.demo_mode()}   # the test environment never sends real emails


def legal_settings(db):
    rows = {r['key']: r['value'] for r in db.execute("SELECT key,value FROM site_settings WHERE key LIKE 'legal\\_%' ESCAPE '\\'").fetchall()}
    return {k[6:]: (v or '').strip() for k, v in rows.items()}


def user_lang(db, user_id):
    r = db.execute('SELECT preferred_language FROM user_profiles WHERE user_id=?', (user_id,)).fetchone()
    return normalize_lang((r['preferred_language'] if r else '') or 'es')


def mail_deliverable(email):
    e = str(email or '').strip().lower()
    # The test environment writes its e-mails to a folder (never sent), also for the test accounts @example.com.
    return bool(re.fullmatch(r'[^@\s]+@[^@\s]+\.[a-z]{2,}', e)) and not e.endswith('.local') and not e.endswith('.test') and (not e.endswith('@example.com') or wcfg.demo_mode())


