def self_payee(db, user, data):
    """The payee a signed-in provider manages: its centre, or itself as freelance. The admin names one."""
    if user['role'] == 'center':
        p = payee_of(db, user['center_id']) if user['center_id'] else None
    elif user['role'] == 'freelance':
        p = payee_of(db, None, user['id'])
    else:
        cid = int(data.get('center_id') or 0); uid = int(data.get('user_id') or 0)
        p = payee_of(db, cid) if cid else (payee_of(db, None, uid) if uid else None)
    if not p: raise ValueError('Centro o profesional no válido.')
    return p


def create_stripe_checkout(db, user, *, amount, currency, title, payee, booking_id=None, experience_booking_id=None, provider_user_id=None,
                           service_id=None, slot_id=None, cancel_url, hold_reserved=False, kind='full', description=None, success_url=None):
    """Creates the payment order and its Stripe Checkout Session as a DIRECT charge on the provider's connected
    account (no application fee, no transfer: WORLDIVES takes no commission). Raises ValueError when it cannot."""
    if amount <= 0: raise ValueError('Esta reserva no tiene un importe que pagar online.')
    if wmoney.below_minimum(amount, currency):   # Stripe refuses charges below its minimum for the currency
        raise ValueError(f'El importe online mínimo en {wmoney.code(currency)} es {wmoney.minimum(currency):g}. Pide al centro que cobre esta reserva en el centro.')
    secret = stripe_secret(); base = public_site_url()
    if not secret: raise ValueError('El pago seguro aún no está configurado en el servidor.')
    if not payee or not payee_ready(payee): raise ValueError('El prestador no tiene ahora mismo los cobros online activos.')
    account_id = payee['stripe_account_id']
    oid = db.execute('''INSERT INTO payment_orders(user_id,provider_user_id,booking_id,experience_booking_id,service_id,slot_id,amount,currency,status,provider,platform_fee,
                         connected_account_id,charge_type,payment_kind,payee_type,payee_id,hold_reserved,created_at,updated_at)
                         VALUES(?,?,?,?,?,?,?,?,'pending','stripe',0,?,'direct',?,?,?,?,?,?)''',
                     (user['id'], provider_user_id, booking_id, experience_booking_id, service_id, slot_id, amount, currency, account_id, kind, payee['type'], payee['id'],
                      1 if hold_reserved else 0, now(), now())).lastrowid
    db.commit()
    ref = f'WOD-{int(booking_id):06d}' if booking_id else f'EXP-{int(experience_booking_id or 0):05d}'
    meta = {'payment_order_id': str(oid), 'booking_id': str(booking_id or ''), 'experience_booking_id': str(experience_booking_id or ''), 'platform': 'worldives'}
    try:
        stripe = stripe_module()
        session = stripe.checkout.Session.create(
            mode='payment',
            line_items=[{'price_data': {'currency': currency.lower(), 'product_data': {'name': title[:250], 'description': (description or f'{ref} · {payee["name"]}')[:500]},
                                        'unit_amount': wmoney.to_minor(amount, currency)}, 'quantity': 1}],
            success_url=success_url or f'{base}/#/pago-ok?session_id={{CHECKOUT_SESSION_ID}}',
            cancel_url=cancel_url,
            metadata=meta,
            payment_intent_data={'description': f'{ref} · {payee["name"]}'[:500], 'metadata': meta},
            client_reference_id=f'WOD-{oid}',
            customer_email=user['email'] if mail_deliverable(user['email']) else None,
            expires_at=int(time.time()) + 30 * 60, locale='auto',
            stripe_account=account_id,
            idempotency_key=f'wod-checkout-{oid}')
    except ImportError:
        db.execute("UPDATE payment_orders SET status='failed',updated_at=? WHERE id=?", (now(), oid)); db.commit()
        raise ValueError('Falta instalar la dependencia stripe en el servidor.')
    except Exception as exc:
        db.execute("UPDATE payment_orders SET status='failed',updated_at=? WHERE id=?", (now(), oid)); db.commit()
        sys.stderr.write(f'[pagos] Stripe rechazó el pedido {oid}: {exc}\n')
        raise ValueError('No se ha podido abrir el pago seguro. Inténtalo de nuevo en unos minutos.')
    db.execute('UPDATE payment_orders SET provider_payment_id=?,checkout_url=?,updated_at=? WHERE id=?', (session.id, session.url, now(), oid)); db.commit()
    return {'checkout_url': session.url, 'order_id': oid}


def start_checkout(db, user, b, app=None):
    """Opens the payment of a booking in its two legal moments (Fase 1B): the whole price or the deposit (Fase 2.5).
    From the app (v50.48), Stripe sends the person back into the app (app = its scheme)."""
    st = wbk.normalize_state(b['status'])
    if b['payment_status'] in ('paid', 'deposit_paid'): raise ValueError('Esta reserva ya está pagada.')
    if st == 'payment_in_progress':
        hold = parse_local(b['hold_expires_at'])
        if hold and local_now() > hold: raise ValueError('El tiempo para pagar esta reserva ha terminado y las plazas se han liberado. Vuelve a reservar.')
    elif st == 'accepted_pending_payment':
        dl = parse_local(b['payment_deadline'])
        if dl and local_now() > dl: raise ValueError('El plazo para pagar esta reserva ha terminado.')
    elif st == 'requested': raise ValueError('El centro todavía no ha aceptado esta solicitud. No se cobra nada hasta entonces.')
    else: raise ValueError('Esta reserva no tiene ningún pago pendiente.')
    reuse = _open_order(db, 'booking_id=?', (b['id'],))
    if reuse: return {'checkout_url': reuse['checkout_url'], 'order_id': reuse['id'], 'reused': True}
    svc, payee = booking_payee(db, b)
    if not payee_ready(payee):
        raise ValueError('El centro no tiene ahora mismo los cobros online activos. Contacta con el centro.')
    price = float(b['price'] or 0); currency = b['currency'] or 'EUR'
    deposit = float(b['deposit_amount'] or 0) if 'deposit_amount' in b.keys() else 0
    amount, kind = (deposit, 'deposit') if 0 < deposit < price else (price, 'full')
    title = (svc['title'] if svc else 'Reserva de buceo') + (' · señal' if kind == 'deposit' else '')
    return create_stripe_checkout(db, user, amount=amount, currency=currency, title=title, payee=payee, kind=kind,
                                  provider_user_id=svc['provider_user_id'] if svc else None, booking_id=b['id'],
                                  service_id=b['service_id'], slot_id=b['slot_id'], hold_reserved=bool(b['slot_reserved']),
                                  cancel_url=wmovil.return_urls(public_site_url(), app, b['id'])[1] if app else f"{public_site_url()}/#/reserva?id={b['id']}&pago=cancelado",
                                  success_url=wmovil.return_urls(public_site_url(), app)[0] if app else None)


def start_experience_checkout(db, user, eb):
    """Experiences are booked on request; once confirmed by the organiser they are paid online when it charges online.
    The price is per person (price × participants). Centres and freelance professionals alike."""
    if eb['status'] not in ('confirmed', 'accepted_pending_payment'): raise ValueError('El organizador todavía no ha aceptado tu solicitud.')
    if (eb['payment_status'] if 'payment_status' in eb.keys() else None) == 'paid': raise ValueError('Esta experiencia ya está pagada.')
    e = db.execute('SELECT * FROM travel_experiences WHERE id=?', (eb['travel_experience_id'],)).fetchone()
    if not e: raise ValueError('Experiencia no disponible.')
    reuse = _open_order(db, 'experience_booking_id=?', (eb['id'],))
    if reuse: return {'checkout_url': reuse['checkout_url'], 'order_id': reuse['id'], 'reused': True}
    payee = payee_of(db, e['center_id'], e['provider_user_id'])
    if not payee or not payee_ready(payee): raise ValueError('Este organizador no cobra online: pagarás directamente con él.')
    amount = round(float(e['price'] or 0) * max(1, int(eb['participants'] or 1)), 2)
    return create_stripe_checkout(db, user, amount=amount, currency=e['currency'] or 'EUR', title=e['title'], payee=payee,
                                  provider_user_id=e['provider_user_id'], experience_booking_id=eb['id'], cancel_url=f'{public_site_url()}/#/area?payment=cancelled')


def warn_payment_mode_without_payments(db, center_id=None, user_id=None):
    """A provider lost its online payments: its «Pago al reservar» services stop being bookable (never silently
    «pay at the centre») and it is told to move them to «Bajo petición». Centres, or freelance without a centre."""
    if center_id:
        svcs = db.execute("SELECT id,title FROM provider_services WHERE center_id=? AND active=1 AND booking_mode='payment'", (center_id,)).fetchall()
        row = db.execute('SELECT payments_warning_at FROM centers WHERE id=?', (center_id,)).fetchone(); table, key = 'centers', center_id
    else:
        svcs = db.execute("SELECT id,title FROM provider_services WHERE provider_user_id=? AND center_id IS NULL AND active=1 AND booking_mode='payment'", (user_id,)).fetchall()
        row = db.execute('SELECT payments_warning_at FROM users WHERE id=?', (user_id,)).fetchone(); table, key = 'users', user_id
    if not svcs: return
    if row and row['payments_warning_at'] and row['payments_warning_at'] > (datetime.now(timezone.utc) - _timedelta(days=1)).isoformat(): return
    db.execute(f'UPDATE {table} SET payments_warning_at=? WHERE id=?', (now(), key))
    names = ', '.join(s['title'] for s in svcs)
    for email, name, lang in provider_recipients(db, center_id, user_id):
        queue_email(db, 'center_payments_disabled', email, name, {'services': names, 'panel_url': f'{public_site_url()}/#/admin?tab=services'}, lang, ('center', center_id) if center_id else ('user', user_id))


def new_password_reset(db, user_id):
    token = secrets.token_urlsafe(32)
    exp = (datetime.now(timezone.utc) + _timedelta(hours=1)).isoformat(timespec='seconds')
    db.execute('UPDATE password_resets SET used_at=? WHERE user_id=? AND used_at IS NULL', (now(), user_id))
    db.execute('INSERT INTO password_resets(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)', (hashlib.sha256(token.encode()).hexdigest(), user_id, exp, now()))
    return token


def export_user_data(db, uid):
    """Right of access / portability: every row about the user, as JSON (secrets left out)."""
    out = {'exported_at': now(), 'site': public_site_url()}
    u = db.execute('SELECT id,fullname,email,username,role,created_at,last_login,provider_bio,avatar_url,instagram_url,facebook_url,twitter_url,youtube_url,tiktok_url,terms_version,terms_accepted_at FROM users WHERE id=?', (uid,)).fetchone()
    out['account'] = dict(u) if u else {}
    skip = {'sessions', 'password_resets', 'email_outbox', 'audit_log', 'login_attempts'}
    for t in [r['name'] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").fetchall()]:
        if t in skip or t == 'users' or t.startswith('sqlite_'): continue
        cols = [r['name'] for r in db.execute(f'PRAGMA table_info("{t}")').fetchall()]
        if 'user_id' not in cols: continue
        keep = [c for c in cols if c not in ('password_hash', 'token_hash', 'api_key_hash', 'file_path', 'internal_notes')]
        rows = db.execute(f'SELECT {",".join(chr(34) + c + chr(34) for c in keep)} FROM "{t}" WHERE user_id=? LIMIT 5000', (uid,)).fetchall()
        if rows: out[t] = [dict(r) for r in rows]
    out['messages_received'] = [dict(r) for r in db.execute('SELECT subject,body,created_at,read_at FROM messages WHERE recipient_user_id=? ORDER BY id DESC LIMIT 2000', (uid,)).fetchall()]
    out['emails_sent_to_you'] = [dict(r) for r in db.execute('SELECT template,subject,status,created_at,sent_at FROM email_outbox WHERE to_email=(SELECT lower(email) FROM users WHERE id=?) ORDER BY id DESC LIMIT 500', (uid,)).fetchall()]
    return out


def export_user_zip(db, uid):
    """Right of access / portability (v50.36): a ZIP with all the data (datos.json) and the documents the user uploaded."""
    import io, zipfile
    data = export_user_data(db, uid)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z:
        z.writestr('datos.json', json.dumps(data, ensure_ascii=False, indent=2, default=str))
        z.writestr('LEEME.txt', mail_t(user_lang(db, uid), 'Copia de tus datos en WORLDIVES DISCOVERY. datos.json contiene tu cuenta, ficha, reservas, pagos, puntos, reseñas, avisos y consentimientos; la carpeta documentos contiene los archivos que subiste.') + '\n')
        for d in db.execute('SELECT id,document_type,file_path,original_name FROM user_documents WHERE user_id=?', (uid,)).fetchall():
            fp = document_file_path(d['file_path'])
            if not fp or not fp.exists(): continue
            name = re.sub(r'[^A-Za-z0-9._-]+', '_', d['original_name'] or fp.name)[-80:] or fp.name
            z.write(fp, f"documentos/{d['id']}_{d['document_type'] or 'documento'}_{name}")
    return buf.getvalue()


def request_account_deletion(db, user):
    """Erasure is confirmed from the account's email. Without a deliverable email the password already confirmed it."""
    uid = user['id']
    if not mail_deliverable(user['email']): return None
    token = wsec.random_token(32)
    exp = (datetime.now(timezone.utc) + _timedelta(hours=24)).isoformat(timespec='seconds')
    db.execute('UPDATE account_deletion_requests SET used_at=? WHERE user_id=? AND used_at IS NULL', (now(), uid))
    db.execute('INSERT INTO account_deletion_requests(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)', (hashlib.sha256(token.encode()).hexdigest(), uid, exp, now()))
    ctx, lang = user_mail_ctx(db, uid)
    if ctx:
        ctx.update({'confirm_url': f'{public_site_url()}/#/eliminar-cuenta?token={token}', 'export_url': f'{public_site_url()}/#/cuenta'})
        queue_email(db, 'account_delete_confirm', user['email'], user['fullname'], ctx, lang, ('user', uid))
    audit(db, uid, 'account_deletion_requested', 'user', uid)
    return token


def delete_user_account(db, user):
    """Right to erasure: personal data removed or anonymised. Bookings and payments stay (anonymised) for the centres' and
    the tax obligations; reviews stay without the author's name."""
    uid = user['id']
    future = db.execute("SELECT COUNT(*) FROM bookings WHERE user_id=? AND status IN ('pending','confirmed') AND booking_date>=?", (uid, _dt.date.today().isoformat())).fetchone()[0]
    if future: raise ValueError(f'Tienes {future} reserva(s) próxima(s). Cancélalas antes de eliminar tu cuenta.')
    notify_user(db, uid, 'account_deleted', related=('user', uid))
    db.execute('DELETE FROM document_alerts WHERE document_id IN (SELECT id FROM user_documents WHERE user_id=?)', (uid,))
    for d in db.execute('SELECT file_path FROM user_documents WHERE user_id=?', (uid,)).fetchall():
        delete_document_file(d['file_path'])
    tag = secrets.token_hex(4)
    db.execute('''UPDATE users SET fullname='Usuario eliminado', email=?, username=?, password_hash='!', provider_bio=NULL, avatar_url=NULL,
                  instagram_url=NULL, facebook_url=NULL, twitter_url=NULL, youtube_url=NULL, tiktok_url=NULL WHERE id=?''',
               (f'eliminado-{uid}-{tag}@sin-email.worldives.local', f'eliminado_{uid}_{tag}', uid))
    db.execute('DELETE FROM user_profiles WHERE user_id=?', (uid,))
    for sql in ('DELETE FROM user_documents WHERE user_id=?', 'DELETE FROM sessions WHERE user_id=?', 'DELETE FROM logbook_entries WHERE user_id=?',
                'DELETE FROM center_links WHERE user_id=?', 'DELETE FROM password_resets WHERE user_id=?', 'DELETE FROM messages WHERE recipient_user_id=?',
                "UPDATE promotion_codes SET status='revoked',revoked_at=? WHERE user_id=? AND status='active'",
                "UPDATE center_claims SET status='withdrawn', phone=NULL, note=NULL, email=NULL, reviewed_at=COALESCE(reviewed_at,?) WHERE user_id=? AND status='pending'",
                "UPDATE reward_redemptions SET status='cancelled', cancelled_at=? WHERE user_id=? AND status='issued'",
                'DELETE FROM account_deletion_requests WHERE user_id=?',
                'UPDATE bookings SET contact_phone=NULL, contact_phone_hash=NULL, contact_email=NULL, contact_name=NULL, notes=NULL, equipment_notes=NULL, guide_notes=NULL WHERE user_id=?',
                'DELETE FROM info_requests WHERE user_id=?'):
        db.execute(sql, (now(), uid) if sql.count('?') == 2 else (uid,))
    audit(db, uid, 'account_deleted', 'user', uid)


# ------------------------------------------------------------- v50.49 · closing the account of a centre or a freelance
# Decision of the owner (13/10/2026): «borrar cuenta para siempre» closes the account at once; everything is kept
# CLOSE_KEEP_DAYS (six months) so the centre can come back with all its data by signing in and pressing «Reabrir»;
# after that everything is deleted except what the law obliges us to keep (payments, refunds, the amounts and dates of
# the bookings, the tax data for DAC7 and the security log), which keeps its own retention period.
CLOSE_KEEP_DAYS = 183
CLOSE_STATES = ('requested', 'accepted_pending_payment', 'confirmed', 'payment_in_progress', 'pending')
CLOSED_WRITE_OK = ('/api/auth/', '/api/provider/cuenta/reabrir', '/api/account/', '/api/legal/accept', '/api/team/switch', '/api/me', '/api/reports', '/api/contact')
CENTER_PURGE_TABLES = ('center_tariffs', 'center_extras', 'center_equipment', 'center_integrations', 'center_links', 'data_shares', 'team_invites',
                       'center_roles', 'center_point_links', 'qr_codes', 'promotion_partners', 'center_texts')
PROVIDER_PURGE_TABLES = ('notice_outbox', 'notice_batches', 'info_requests', 'whatsapp_accounts', 'provider_settings')
CENTER_ANON_COLS = ('region', 'city', 'address', 'website', 'phone', 'email', 'description', 'specialties', 'latitude', 'longitude', 'source_name', 'source_url',
                    'logo_url', 'logo_source', 'instagram_url', 'facebook_url', 'twitter_url', 'youtube_url', 'tiktok_url', 'cover_url', 'tagline', 'gallery_json',
                    'languages', 'opening_hours', 'cancellation_note', 'insurance_company', 'insurance_policy', 'insurance_doc', 'insurance_alerts', 'ical_token', 'licences_note')
PROVIDER_CLOSURES_SCHEMA = '''CREATE TABLE IF NOT EXISTS provider_closures (id INTEGER PRIMARY KEY AUTOINCREMENT, provider_kind TEXT NOT NULL, provider_oid INTEGER NOT NULL,
  closed_at TEXT NOT NULL, closed_by INTEGER, purge_after TEXT NOT NULL, restore TEXT NOT NULL DEFAULT '{}', reopened_at TEXT, reopened_by INTEGER,
  purged_at TEXT, purge_report TEXT)'''


def provider_of_user(user):
    """('center', centre id) or ('freelance', user id) of a professional account; None otherwise."""
    if not user: return None
    if user['role'] == 'center' and user.get('center_id'): return ('center', int(user['center_id']))
    if user['role'] == 'freelance': return ('freelance', int(user['id']))
    return None


def provider_closure(db, kind, oid):
    return db.execute('''SELECT * FROM provider_closures WHERE provider_kind=? AND provider_oid=? AND reopened_at IS NULL AND purged_at IS NULL
                         ORDER BY id DESC LIMIT 1''', (kind, int(oid))).fetchone()


def provider_future_bookings(db, kind, oid):
    """Bookings that still involve a diver: requests, accepted, confirmed or being paid, from today on."""
    w, a = winq.owner_filter(winq.Ctx(0, kind, kind, int(oid)), 'b')
    q = f'''SELECT b.id,b.booking_date,b.booking_time,b.date_to,b.participants,b.status,b.payment_status,b.currency,b.price,
                  COALESCE(b.contact_name,u.fullname) AS name,ps.title AS service_title FROM bookings b LEFT JOIN users u ON u.id=b.user_id
                  LEFT JOIN provider_services ps ON ps.id=b.service_id
            WHERE {w} AND b.status IN ({','.join('?' * len(CLOSE_STATES))}) AND COALESCE(b.date_to,b.booking_date)>=? ORDER BY b.booking_date,b.booking_time,b.id'''
    out = []
    for r in db.execute(q, (*a, *CLOSE_STATES, local_now().date().isoformat())).fetchall():
        paid_, refunded_, _o = booking_paid_online(db, r['id'])
        out.append({**dict(r), 'paid': round(paid_ - refunded_, 2)})
    return out


def provider_account_status(db, kind, oid):
    c = provider_closure(db, kind, oid)
    fut = provider_future_bookings(db, kind, oid) if not c else []
    closed = None
    if c:
        left = max(0, (_dt.date.fromisoformat(c['purge_after'][:10]) - local_now().date()).days)
        closed = {'closed_at': c['closed_at'], 'purge_after': c['purge_after'][:10], 'days_left': left}
    return {'kind': kind, 'name': provider_label(db, kind, oid), 'closed': closed, 'keep_days': CLOSE_KEEP_DAYS, 'future': fut, 'future_count': len(fut),
            'refund_total': round(sum(x['paid'] for x in fut), 2), 'can_close': not c and not fut}


def provider_cancel_all(db, user, kind, oid, note=''):
    """«Cancelar y avisar a todos»: every future booking is cancelled with the full refund of what was paid and its diver
    is told (email and the app, in their language). Returns {cancelled, refunded, amount}."""
    rep = {'cancelled': 0, 'refunded': 0, 'refund_pending': 0, 'amount': 0.0}
    for x in provider_future_bookings(db, kind, oid):
        b = booking_row(db, x['id'])
        if b['status'] == 'payment_in_progress':
            if expire_booking(db, b, 'provider_closed', notify=False) != 'paid': continue
            b = booking_row(db, x['id'])
        outcome, amount = provider_cancel_booking(db, b, 'provider_closed', user['id'], 'provider_closed', notify=True, refund=True)
        rep['cancelled'] += 1; rep['amount'] = round(rep['amount'] + (amount if outcome == 'refunded' else 0), 2)
        if outcome == 'refunded': rep['refunded'] += 1
        elif outcome not in ('none_paid',): rep['refund_pending'] += 1
    audit(db, user['id'], 'provider_cancel_all', kind, oid, {**rep, 'note': clean_text(note, 300) or None})
    return rep


def provider_close(db, user, kind, oid):
    if provider_closure(db, kind, oid): raise ValueError('Esta cuenta ya está cerrada.')
    fut = provider_future_bookings(db, kind, oid)
    if fut: raise ValueError(f'Tienes {len(fut)} reservas próximas. Resuélvelas o pulsa «Cancelar y avisar a todos» antes de cerrar la cuenta.')
    restore = {'services': [r['id'] for r in db.execute(f"SELECT id FROM provider_services WHERE active=1 AND {'center_id=?' if kind == 'center' else 'provider_user_id=? AND center_id IS NULL'}", (oid,))],
               'experiences': [r['id'] for r in db.execute(f"SELECT id FROM travel_experiences WHERE active=1 AND {'center_id=?' if kind == 'center' else 'provider_user_id=? AND center_id IS NULL'}", (oid,))]}
    if kind == 'center':
        restore['center_active'] = db.execute('SELECT active FROM centers WHERE id=?', (oid,)).fetchone()['active']
        db.execute('UPDATE centers SET active=0,updated_at=? WHERE id=?', (now(), oid))
    key = winq.tenant_key(kind, oid)
    for sid in restore['services']: db.execute('UPDATE provider_services SET active=0 WHERE id=? AND provider_id=?', (sid, key))
    for eid in restore['experiences']: db.execute('UPDATE travel_experiences SET active=0 WHERE id=? AND provider_id=?', (eid, key))
    purge = (datetime.now(timezone.utc) + _timedelta(days=CLOSE_KEEP_DAYS)).isoformat(timespec='seconds')
    db.execute('INSERT INTO provider_closures(provider_kind,provider_oid,closed_at,closed_by,purge_after,restore) VALUES(?,?,?,?,?,?)',
               (kind, oid, now(), user['id'], purge, json.dumps(restore)))
    # Everybody of that centre is signed out (the owner signs in again to reopen it).
    ids = [user['id']] if kind == 'freelance' else [r['user_id'] for r in db.execute('SELECT user_id FROM center_members WHERE center_id=?', (oid,))] + \
        [r['id'] for r in db.execute("SELECT id FROM users WHERE center_id=? AND role='center'", (oid,))]
    for uid in set(ids): db.execute('DELETE FROM sessions WHERE user_id=?', (uid,))
    audit(db, user['id'], 'provider_closed', kind, oid, {'purge_after': purge[:10], 'services': len(restore['services'])})
    return purge[:10]


def provider_reopen(db, user, kind, oid):
    c = provider_closure(db, kind, oid)
    if not c: raise ValueError('Esta cuenta no está cerrada.')
    restore = json.loads(c['restore'] or '{}')
    if kind == 'center' and restore.get('center_active') is not None: db.execute('UPDATE centers SET active=?,updated_at=? WHERE id=?', (restore['center_active'], now(), oid))
    key = winq.tenant_key(kind, oid)
    for sid in restore.get('services', []): db.execute('UPDATE provider_services SET active=1 WHERE id=? AND provider_id=?', (sid, key))
    for eid in restore.get('experiences', []): db.execute('UPDATE travel_experiences SET active=1 WHERE id=? AND provider_id=?', (eid, key))
    db.execute('UPDATE provider_closures SET reopened_at=?,reopened_by=? WHERE id=?', (now(), user['id'], c['id']))
    audit(db, user['id'], 'provider_reopened', kind, oid, {'closed_at': c['closed_at']})


CLOSED_PRIVATE_GET = ('/api/bookings', '/api/center/', '/api/provider/', '/api/provider-services', '/api/manifest/', '/api/pro/', '/api/avisos', '/api/agenda/', '/api/messages',
                      '/api/payments/center', '/api/whatsapp', '/api/boats', '/api/service-templates')


def closed_gate(db, user, path, method):
    """A closed account: its owner reads (history, exports) but changes nothing until reopening it; the rest of its team
    does not see the centre's private data any more."""
    ref = provider_of_user(user)
    if not ref or path.startswith(CLOSED_WRITE_OK) or (method == 'GET' and not path.startswith(CLOSED_PRIVATE_GET)): return
    if not provider_closure(db, *ref): return
    if method == 'GET' and (ref[0] == 'freelance' or member_role(db, user) == 'owner'): return
    raise PermissionError('Esta cuenta está cerrada. El propietario puede reabrirla desde «Mi cuenta» antes de que se borre.')


def purge_provider(db, kind, oid):
    """Six months after closing: deletes the data of a centre or freelance. Kept by law: payments and refunds, the
    amounts and dates of the bookings (without names, emails, phones or notes), the tax data (DAC7) and the security
    log. Every step is independent: what fails is written in the report and retried the next day."""
    key = winq.tenant_key(kind, oid); rep = {}; errors = []
    def step(name, fn):
        try: rep[name] = fn()
        except Exception as exc: errors.append(f'{name}: {exc}'[:200])
    w, a = winq.owner_filter(winq.Ctx(0, kind, kind, int(oid)), 'b')
    bids = f'SELECT b.id FROM bookings b WHERE {w}'
    step('manifest', lambda: db.execute(f'DELETE FROM manifest_entries WHERE booking_id IN ({bids})', a).rowcount)
    step('signatures', lambda: db.execute(f'DELETE FROM waiver_signatures WHERE booking_id IN ({bids})', a).rowcount)
    step('messages', lambda: db.execute(f'DELETE FROM messages WHERE booking_id IN ({bids})', a).rowcount)
    step('bookings_anonymised', lambda: db.execute(f'''UPDATE bookings SET contact_name=NULL,contact_email=NULL,contact_phone=NULL,contact_phone_hash=NULL,notes=NULL,
                                                  internal_notes=NULL,equipment_notes=NULL,guide_notes=NULL,external_ref=NULL WHERE id IN ({bids})''', a).rowcount)
    step('guides', lambda: db.execute('UPDATE slot_groups SET guide_name=NULL WHERE slot_id IN (SELECT id FROM service_slots WHERE provider_id=?)', (key,)).rowcount)
    for t in PROVIDER_PURGE_TABLES:
        step(t, lambda t=t: db.execute(f'DELETE FROM {t} WHERE provider_id=?', (key,)).rowcount)
    people = []
    if kind == 'center':
        for t in CENTER_PURGE_TABLES:
            step(t, lambda t=t: db.execute(f'DELETE FROM {t} WHERE center_id=?', (oid,)).rowcount)
        def photos():
            urls = [r['image_path'] for r in db.execute('SELECT image_path FROM center_photos WHERE center_id=?', (oid,))]
            c = db.execute('SELECT logo_url,cover_url,gallery_json,insurance_doc FROM centers WHERE id=?', (oid,)).fetchone()
            if c:
                urls += [c['logo_url'], c['cover_url']]
                try: urls += [g if isinstance(g, str) else (g or {}).get('url') for g in json.loads(c['gallery_json'] or '[]')]
                except (ValueError, TypeError): pass
                if c['insurance_doc']: delete_document_file(c['insurance_doc'])
            for u in urls: delete_public_image(u)
            db.execute('DELETE FROM center_photos WHERE center_id=?', (oid,)); return len([u for u in urls if u])
        step('photos', photos)
        team = {r['user_id'] for r in db.execute('SELECT user_id FROM center_members WHERE center_id=?', (oid,))} | \
               {r['id'] for r in db.execute("SELECT id FROM users WHERE center_id=? AND role='center'", (oid,))}
        step('members', lambda: db.execute('DELETE FROM center_members WHERE center_id=?', (oid,)).rowcount)
        for uid in team:
            other = db.execute('SELECT center_id FROM center_members WHERE user_id=? ORDER BY created_at LIMIT 1', (uid,)).fetchone()
            if other: db.execute("UPDATE users SET center_id=? WHERE id=? AND center_id=?", (other['center_id'], uid, oid))
            else: people.append(uid)
        people += [r['id'] for r in db.execute('SELECT id FROM users WHERE guest_center_id=?', (oid,))]
        def center_row_():
            cols = {r['name'] for r in db.execute('PRAGMA table_info(centers)')}
            sets = ', '.join(f'{c}=NULL' for c in CENTER_ANON_COLS if c in cols)
            db.execute(f"UPDATE centers SET name='Centro eliminado', active=0, {sets}, updated_at=? WHERE id=?", (now(), oid)); return 1
        step('center', center_row_)
    else:
        step('templates', lambda: db.execute('DELETE FROM service_templates WHERE provider_user_id=?', (oid,)).rowcount)
        people.append(oid)
    def accounts():
        n = 0
        for uid in people:
            u = db.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
            if not u or u['password_hash'] == '!' and (u['email'] or '').startswith('eliminado-'): continue
            try: delete_user_account(db, dict(u))
            except ValueError:   # the person also books as a diver: their diver account stays, without the centre
                db.execute("UPDATE users SET role='recreational',center_id=NULL,requested_role='recreational' WHERE id=? AND role='center'", (uid,))
            n += 1
        return n
    step('accounts', accounts)
    return rep, errors


def run_closure_jobs(db, at=None):
    """Daily: accounts closed more than CLOSE_KEEP_DAYS ago are deleted (a copy of the database is made first)."""
    at = at or datetime.now(timezone.utc)
    due = db.execute('SELECT * FROM provider_closures WHERE reopened_at IS NULL AND purged_at IS NULL AND purge_after<=? LIMIT 20', (at.isoformat(timespec='seconds'),)).fetchall()
    if not due: return 0
    backup_database(db, 'antes_de_borrar_cuentas_cerradas')
    for c in due:
        rep, errors = purge_provider(db, c['provider_kind'], c['provider_oid'])
        if errors: rep['errors'] = errors
        db.execute('UPDATE provider_closures SET purged_at=?,purge_report=? WHERE id=?', (None if errors else now(), json.dumps(rep), c['id']))
        audit(db, None, 'provider_purged' if not errors else 'provider_purge_incomplete', c['provider_kind'], c['provider_oid'], rep)
        db.commit()
    return len(due)


REPORT_TARGETS = ('review', 'center', 'point', 'experience', 'photo', 'promotion', 'profile')


def report_target(db, ttype, tid):
    """The reported item, checked: (label, url, affected user ids) — affected users are told about the decision."""
    if ttype not in REPORT_TARGETS or not tid: return None
    base = public_site_url()
    if ttype == 'review':
        r = db.execute('SELECT cr.id,cr.center_id,cr.user_id,c.name FROM center_reviews cr JOIN centers c ON c.id=cr.center_id WHERE cr.id=?', (tid,)).fetchone()
        return r and (f"Reseña #{r['id']} de {r['name']}", f"{base}/#/centro?id={r['center_id']}", [r['user_id']])
    if ttype in ('center', 'photo'):
        r = db.execute('SELECT id,name FROM centers WHERE id=?', (tid,)).fetchone()
        users = [x['id'] for x in db.execute("SELECT id FROM users WHERE center_id=? AND role='center'", (tid,)).fetchall()]
        return r and ((('Foto de ' if ttype == 'photo' else 'Centro ') + r['name']), f"{base}/#/centro?id={r['id']}", users)
    if ttype == 'point':
        r = db.execute('SELECT id,name FROM dive_points WHERE id=?', (tid,)).fetchone()
        return r and (f"Punto de buceo {r['name']}", f"{base}/#/punto?id={r['id']}", [])
    if ttype == 'experience':
        r = db.execute('SELECT id,title,provider_user_id,center_id,travel_offer_id FROM travel_experiences WHERE id=?', (tid,)).fetchone()
        if not r: return None
        users = [r['provider_user_id']] if r['provider_user_id'] else [x['id'] for x in db.execute("SELECT id FROM users WHERE center_id=? AND role='center'", (r['center_id'] or -1,)).fetchall()]
        return (f"Experiencia {r['title']}", f"{base}/#/experiencia?id={r['travel_offer_id']}", users)
    if ttype == 'promotion':
        r = db.execute('SELECT id,title FROM promotions WHERE id=?', (tid,)).fetchone()
        return r and (f"Promoción {r['title']}", f"{base}/#/promo/{r['id']}", [])
    if ttype == 'profile':
        r = db.execute("SELECT id,fullname FROM users WHERE id=? AND role='freelance'", (tid,)).fetchone()
        return r and (f"Perfil de {r['fullname']}", f"{base}/#/profesional?id={r['id']}", [r['id']])
    return None


