    # Details card + QR
    top = 618; pg.box(40, top - 214, 350, 214, WHITE, LINE, 12); pg.box(402, top - 214, 153, 214, SOFT, None, 12)
    pg.text(56, top - 22, t('Detalles').upper(), 7.5, MUTED, True)
