# ------------------------------------------------------------------ v50.40 · Encargo 2, puntos 1 y 5
# Departure manifest: the divers of a departure split into boats, guides and groups, with what the crew needs
# (level, rental equipment, sizes, nitrox and, only when the diver shares it, the emergency contact); and the
# liability waiver each centre writes, signed by every diver before diving. No health questions (pending lawyer).
from wod import manifest as wmf

MANIFEST_STATES = ('requested', 'accepted_pending_payment', 'confirmed', 'completed')
MANIFEST_DEFAULT_PER_GUIDE = 4
# Prepared, switched off: health questions in the waiver only if the lawyer approves them (encargo 2, punto 5).
WAIVER_HEALTH_QUESTIONS = False


def provider_owner(user):
    """('center', id) for a centre account (any team member), ('freelance', id) for a professional."""
    if user['role'] == 'center' and user['center_id']: return 'center', int(user['center_id'])
    if user['role'] == 'freelance': return 'freelance', int(user['id'])
    raise PermissionError('Solo los centros y los profesionales gestionan salidas.')


def owner_where(kind, oid, alias=''):
    p = f'{alias}.' if alias else ''
    return (f'{p}center_id=?', (oid,)) if kind == 'center' else (f'{p}center_id IS NULL AND {p}provider_user_id=?', (oid,))


def manifest_slot(db, user, slot_id):
    """The departure and its service, if this centre or professional manages it (admins too)."""
    r = db.execute('''SELECT ss.*, s.title AS service_title, s.center_id, s.provider_user_id, s.service_type, s.duration_minutes
                        FROM service_slots ss JOIN provider_services s ON s.id=ss.service_id WHERE ss.id=?''', (slot_id,)).fetchone()
    if not r or (user['role'] != 'admin' and not owns_service(user, r['provider_user_id'], r['center_id'])):
        raise NotFound('Salida no encontrada.')
    return r


def slot_owner(slot):
    return ('center', int(slot['center_id'])) if slot['center_id'] else ('freelance', int(slot['provider_user_id']))


def manifest_settings(db, kind, oid):
    row = db.execute('SELECT manifest_max_per_guide AS m FROM centers WHERE id=?' if kind == 'center' else 'SELECT manifest_max_per_guide AS m FROM users WHERE id=?', (oid,)).fetchone()
    return {'max_per_guide': int(row['m']) if row and row['m'] else MANIFEST_DEFAULT_PER_GUIDE}


def owner_boats(db, kind, oid, active_only=True):
    w, a = owner_where(kind, oid)
    return [dict(r) for r in db.execute(f"SELECT id,name,capacity,active FROM boats WHERE {w}{' AND active=1' if active_only else ''} ORDER BY name,id", a).fetchall()]


def owner_guides(db, kind, oid):
    """Who can guide: the owner and the instructors of the centre (team, Fase 6.6), or the professional himself."""
    if kind == 'freelance':
        u = db.execute('SELECT id,fullname FROM users WHERE id=?', (oid,)).fetchone()
        return [{'user_id': u['id'], 'name': u['fullname']}] if u else []
    rows = db.execute('''SELECT u.id,u.fullname,COALESCE(m.member_role,'owner') AS member_role FROM users u
                           LEFT JOIN center_members m ON m.user_id=u.id AND m.center_id=u.center_id
                          WHERE u.center_id=? AND u.role='center' ORDER BY CASE COALESCE(m.member_role,'owner') WHEN 'instructor' THEN 0 WHEN 'owner' THEN 1 ELSE 2 END, u.fullname''', (oid,)).fetchall()
    # v50.49: also the roles the centre created that can do the check-in on the boat («Instructor máster»…).
    return [{'user_id': r['id'], 'name': r['fullname'], 'member_role': r['member_role']} for r in rows
            if r['member_role'] in ('owner', 'instructor') or (wroles.CLAVE_PROPIA.fullmatch(r['member_role'] or '') and 'checkin' in wroles.permisos(db, oid, r['member_role']))]


def booking_rental(b):
    """Rental items of a booking from its price lines (Fase 1B): «Traje ×2», «Ordenador»… or the old free text."""
    try: lines = json.loads(b['price_breakdown'] or '[]')
    except (TypeError, ValueError): lines = []
    items = []
    for ln in lines if isinstance(lines, list) else []:
        if isinstance(ln, dict) and ln.get('kind') == 'equipment':
            q = int(ln.get('qty') or 1); items.append(f"{ln.get('label') or ''}{' ×' + str(q) if q > 1 else ''}".strip())
    if not items and b['equipment_items']: items = [x.strip() for x in str(b['equipment_items']).split(',') if x.strip()]
    return [x for x in items if x]


def current_waiver(db, kind, oid):
    w, a = owner_where(kind, oid)
    r = db.execute(f'SELECT * FROM waiver_templates WHERE {w} AND active=1 ORDER BY version DESC LIMIT 1', a).fetchone()
    return dict(r) if r else None


def booking_signatures(db, booking_id):
    return {r['seat']: dict(r) for r in db.execute('SELECT id,seat,version,signer_name,signed_at,method FROM waiver_signatures WHERE booking_id=? ORDER BY signed_at', (booking_id,)).fetchall()}


def manifest_data(db, user, slot_id, for_reading=True):
    slot = manifest_slot(db, user, slot_id)
    if for_reading and not slot_visible(db, user, slot_id): raise NotFound('Salida no encontrada.')
    kind, oid = slot_owner(slot)
    st = ','.join('?' * len(MANIFEST_STATES))
    books = db.execute(f'''SELECT b.*, COALESCE(b.contact_name,u.fullname) AS diver_name, u.fullname AS user_fullname, up.phone AS profile_phone,
                                  up.emergency_contact_name, up.emergency_contact_phone, up.suit_type, up.suit_size, up.boot_size, up.bcd_size, up.fin_size,
                                  up.mask_size, up.usual_weight_kg, c.name AS certification_name
                             FROM bookings b LEFT JOIN users u ON u.id=b.user_id LEFT JOIN user_profiles up ON up.user_id=b.user_id
                             LEFT JOIN certifications c ON c.id=up.certification_id
                            WHERE b.slot_id=? AND b.status IN ({st}) ORDER BY b.id''', (slot_id, *MANIFEST_STATES)).fetchall()
    groups = [dict(g) for g in db.execute('SELECT * FROM slot_groups WHERE slot_id=? ORDER BY sort,id', (slot_id,)).fetchall()]
    gids = {g['id'] for g in groups}
    waiver = current_waiver(db, kind, oid)
    divers = []
    for b in books:
        visible = provider_can_see_user(db, b) or is_guest_user(db, b['user_id'], b['center_id'] or -1)
        shared = bool(provider_can_see_user(db, b))
        sigs = booking_signatures(db, b['id'])
        for seat in range(1, max(1, int(b['participants'] or 1)) + 1):
            e = db.execute('SELECT * FROM manifest_entries WHERE booking_id=? AND seat=?', (b['id'], seat)).fetchone()
            if not e:
                db.execute('INSERT INTO manifest_entries(booking_id,seat,slot_id,updated_at) VALUES(?,?,?,?)', (b['id'], seat, slot_id, now()))
                e = db.execute('SELECT * FROM manifest_entries WHERE booking_id=? AND seat=?', (b['id'], seat)).fetchone()
            main = seat == 1
            row = {'booking_id': b['id'], 'seat': seat, 'participants': int(b['participants'] or 1), 'status': b['status'],
                   'group_id': e['group_id'] if e['group_id'] in gids else None,
                   'name': (e['name'] or (b['diver_name'] if main else '')) or '', 'companion_of': None if main else b['diver_name'],
                   'level_name': b['certification_name'] if main and visible else None,
                   'level': wmf.level_of(b['certification_name'] if main and visible else None),
                   'nitrox': bool(b['nitrox']), 'rental': booking_rental(b) if main else [],
                   'sizes': None, 'emergency': None, 'phone': None, 'shared': shared if main else False,
                   'notes': b['notes'] if main else None, 'checked_in_at': e['checked_in_at'], 'no_show': bool(e['no_show']), 'note': e['note'],
                   'signed': (sigs.get(seat) or {}).get('signed_at'), 'signature_id': (sigs.get(seat) or {}).get('id')}
            if main and visible:
                row['sizes'] = {k: b[k] for k in ('suit_type', 'suit_size', 'boot_size', 'bcd_size', 'fin_size', 'mask_size', 'usual_weight_kg') if b[k]}
                row['phone'] = b['contact_phone'] or b['profile_phone']
            if main and shared and (b['emergency_contact_name'] or b['emergency_contact_phone']):
                row['emergency'] = {'name': b['emergency_contact_name'], 'phone': b['emergency_contact_phone']}
            divers.append(row)
    settings = manifest_settings(db, kind, oid)
    boats = owner_boats(db, kind, oid, active_only=False)
    guides = owner_guides(db, kind, oid)
    gname = {g['user_id']: g['name'] for g in guides}
    for i, g in enumerate(groups, 1):
        g['label'] = g['label'] or f'Grupo {i}'
        g['guide'] = gname.get(g['guide_user_id']) or g['guide_name'] or None
        g['count'] = sum(1 for d in divers if d['group_id'] == g['id'])
    warn = wmf.warnings(groups, boats, settings['max_per_guide'], sum(1 for d in divers if not d['group_id']))
    if waiver:
        unsigned = sum(1 for d in divers if not d['signed'])
        if unsigned: warn.append({'kind': 'unsigned', 'ref': None, 'text': f"{unsigned} {'buceador sin firmar el descargo' if unsigned == 1 else 'buceadores sin firmar el descargo'}."})
    can_edit = user_can(db, user, 'barco')
    return {'slot': {k: slot[k] for k in ('id', 'service_id', 'slot_date', 'slot_time', 'spots_total', 'spots_available', 'status', 'service_title', 'service_type', 'duration_minutes')},
            'points': [dict(p) for p in db.execute('SELECT p.id,p.name FROM service_slot_points sp JOIN dive_points p ON p.id=sp.dive_point_id WHERE sp.slot_id=? ORDER BY p.name', (slot_id,)).fetchall()],
            'settings': settings, 'boats': boats, 'guides': guides, 'groups': groups, 'divers': divers, 'warnings': warn,
            'waiver': {'id': waiver['id'], 'version': waiver['version'], 'title': waiver['title']} if waiver else None,
            'can_edit': bool(can_edit), 'level_labels': wmf.LEVEL_LABELS,
            'cancelled': {'at': slot['cancelled_at'], 'reason': slot['cancel_reason'], 'note': slot['cancel_note']} if slot['cancelled_at'] else None,
            'waitlist': [{**dict(r), 'expires_at': server_instant(r['expires_at'])} for r in db.execute('''SELECT w.id,w.participants,w.status,w.created_at,w.expires_at,u.fullname FROM waitlist_entries w JOIN users u ON u.id=w.user_id
                                                        WHERE w.slot_id=? AND w.status IN ('waiting','notified') ORDER BY w.created_at,w.id''', (slot_id,)).fetchall()],
            'waitlist_enabled': (db.execute('SELECT waitlist_enabled FROM provider_services WHERE id=?', (slot['service_id'],)).fetchone()['waitlist_enabled'] != 0),
            'events': [{**dict(e), 'details': json.loads(e['details'] or '{}')} for e in db.execute('SELECT e.kind,e.details,e.created_at,u.fullname AS who FROM slot_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.slot_id=? ORDER BY e.id DESC LIMIT 100', (slot_id,)).fetchall()]}


def manifest_require_edit(db, user, slot_id):
    slot = manifest_slot(db, user, slot_id)
    if not user_can(db, user, 'barco'): raise PermissionError(wroles.NO_PUEDE['barco'])
    return slot


def manifest_suggest(db, user, slot_id, apply=False):
    """The automatic split by level and qualification. With apply=False it only says what would be done."""
    slot = manifest_require_edit(db, user, slot_id)
    kind, oid = slot_owner(slot)
    data = manifest_data(db, user, slot_id)
    by_booking = {}
    for d in data['divers']:
        e = by_booking.setdefault(d['booking_id'], {'id': d['booking_id'], 'seats': [], 'level': d['level']})
        e['seats'].append(d['seat'])
    boats = [b for b in data['boats'] if b['active']]
    groups = wmf.suggest(list(by_booking.values()), data['settings']['max_per_guide'], boats, data['guides'])
    summary = {'divers': len(data['divers']), 'groups': len(groups), 'boats': len({g['boat_id'] for g in groups if g['boat_id']}),
               'without_boat': sum(1 for g in groups if not g['boat_id']), 'without_guide': sum(1 for g in groups if not g['guide_user_id'])}
    if not apply: return summary
    db.execute('UPDATE manifest_entries SET group_id=NULL,updated_at=?,updated_by=? WHERE slot_id=?', (now(), user['id'], slot_id))
    db.execute('DELETE FROM slot_groups WHERE slot_id=?', (slot_id,))
    for i, g in enumerate(groups, 1):
        gid = db.execute('INSERT INTO slot_groups(slot_id,boat_id,guide_user_id,guide_name,label,sort,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',
                         (slot_id, g['boat_id'], g['guide_user_id'], None, None, i, now(), now())).lastrowid
        for bid, seat in g['members']:
            db.execute('UPDATE manifest_entries SET group_id=?,updated_at=?,updated_by=? WHERE booking_id=? AND seat=?', (gid, now(), user['id'], bid, seat))
    audit(db, user['id'], 'manifest_suggested', 'service_slot', slot_id, summary)
    return summary


def clean_strokes(raw):
    """A drawn signature: up to 60 strokes of points (x, y) between 0 and 1. At least a real line is needed."""
    try: strokes = json.loads(raw) if isinstance(raw, str) else raw
    except ValueError: strokes = None
    if not isinstance(strokes, list) or not strokes or len(strokes) > 60: raise ValueError('Dibuja tu firma en el recuadro.')
    out, total = [], 0
    for s in strokes:
        if not isinstance(s, list): raise ValueError('Dibuja tu firma en el recuadro.')
        pts = []
        for p in s[:400]:
            if not (isinstance(p, (list, tuple)) and len(p) == 2): raise ValueError('Dibuja tu firma en el recuadro.')
            x, y = float(p[0]), float(p[1])
            if not (0 <= x <= 1 and 0 <= y <= 1): raise ValueError('Dibuja tu firma en el recuadro.')
            pts.append([round(x, 4), round(y, 4)])
        if pts: out.append(pts); total += len(pts)
    span = max((max(p[0] for p in s) - min(p[0] for p in s)) for s in out) if out else 0
    if total < 8 or span < 0.08: raise ValueError('La firma es demasiado corta. Dibújala en el recuadro.')
    return out


def waiver_pdf(db, sig_id, lang='es'):
    s = db.execute('''SELECT w.*, b.booking_date, b.booking_time, b.participants, b.center_id, b.provider_user_id, srv.title AS service_title,
                             COALESCE(ce.name, pu.fullname) AS provider_name
                        FROM waiver_signatures w JOIN bookings b ON b.id=w.booking_id LEFT JOIN provider_services srv ON srv.id=b.service_id
                        LEFT JOIN centers ce ON ce.id=b.center_id LEFT JOIN users pu ON pu.id=b.provider_user_id WHERE w.id=?''', (sig_id,)).fetchone()
    if not s: return None
    T = lambda x: mail_t(lang, x)
    d = wpdf.Document(T('Descargo de responsabilidad'), lang)
    ink, muted = (0.04, 0.17, 0.24), (0.38, 0.43, 0.46)
    d.box(24, 748, 547, 70, BRAND_PDF['abismo'], None, 16); pdf_brand_icon(d, 40, 756, 54)
    d.text(104, 790, 'WORLDIVES DISCOVERY', 21, (1, 1, 1)); d.text(104, 773, T('DESCARGO FIRMADO').upper(), 8, BRAND_PDF['agua'])
    d.text(46, 722, d.fit(s['title'], 16, 500), 16, ink)
    meta = [(T('Centro'), s['provider_name'] or '—'), (T('Reserva'), f"WOD-{s['booking_id']:06d}"), (T('Actividad'), s['service_title'] or '—'),
            (T('Fecha'), mail_date(s['booking_date'], lang) + (' · ' + s['booking_time'] if s['booking_time'] else '')),
            (T('Versión'), f"v{s['version']}"), (T('Plaza'), f"{s['seat']} / {s['participants']}")]
    for i, (lab, val) in enumerate(meta):
        x = 46 + (i % 3) * 170; y = 696 - (i // 3) * 30
        d.text(x, y, lab.upper(), 7, muted); d.text(x, y - 13, d.fit(str(val), 9, 160), 9, ink)
    y = 626
    for para in str(s['body'] or '').split('\n'):
        lines = d.wrap(para, 9.5, 500, max_lines=400) if para.strip() else ['']
        for ln in lines:
            if y < 230:
                d.new_page(); y = 790
            d.text(46, y, ln, 9.5, ink); y -= 13.5
        y -= 4
    if y < 240: d.new_page(); y = 790
    top = y - 10
    d.box(46, top - 150, 300, 140, None, (0.86, 0.89, 0.91), 10)
    d.text(58, top - 24, T('FIRMA').upper(), 7, muted)
    try: strokes = json.loads(s['strokes'] or '[]')
    except ValueError: strokes = []
    bx, by, bw, bh = 58, top - 140, 276, 100
    for st in strokes:
        for (x1, y1), (x2, y2) in zip(st, st[1:]):
            d.line(bx + x1 * bw, by + (1 - y1) * bh, bx + x2 * bw, by + (1 - y2) * bh, ink, 1.4)
    when = s['signed_at'][:19].replace('T', ' ')
    info = [(T('Nombre completo'), s['signer_name']), (T('Firmado el'), when + ' UTC'), (T('Cómo'), T('En «Mi reserva»') if s['method'] == 'online' else T('En el check-in del centro'))]
    for i, (lab, val) in enumerate(info):
        yy = top - 24 - i * 34
        d.text(366, yy, lab.upper(), 7, muted); d.text(366, yy - 13, d.fit(str(val), 9, 190), 9, ink)
    d.text(46, 60, T('Documento generado por WORLDIVES DISCOVERY con el texto exacto que se firmó (versión y fecha).'), 7, muted)
    return d.pdf()


# ------------------------------------------------------------------ v50.41 · Encargo 2, puntos 2, 3 y 4
# 2. A centre cancels a departure (weather, sea…): every diver chooses another date of the same service or the full
#    refund; without an answer before the deadline (48 h by default) the refund is automatic.
# 3. The diver changes the date himself, within the service's deadline, directly or with the centre's approval.
# 4. Waiting list on full departures: when a spot frees up, the first person who fits gets it kept for 2 h (never
#    after the start); without a booking it goes to the next one.
SLOT_CANCEL_REASONS = {'weather': 'Mal tiempo', 'sea': 'Estado del mar', 'boat': 'Avería del barco', 'other': 'Otro motivo'}
PROVIDER_CLOSED_REASON = 'Ha cerrado su cuenta en WORLDIVES y ha cancelado todas sus próximas reservas'
SLOT_CHOICE_HOURS_DEFAULT = 48
RESCHEDULE_HOURS_DEFAULT = 48
RESCHEDULE_MODES = ('none', 'direct', 'approval')
WAITLIST_HOLD_HOURS = 2
OPEN_OFFER_SQL = 'id NOT IN (SELECT booking_id FROM slot_cancel_offers WHERE resolved_at IS NULL)'


def slot_event(db, slot_id, kind, user_id=None, **details):
    db.execute('INSERT INTO slot_events(slot_id,kind,details,user_id,created_at) VALUES(?,?,?,?,?)', (slot_id, kind, json.dumps(details, ensure_ascii=False), user_id, now()))


def slot_start(db, slot):
    """Start of a departure on the server's clock (see on_server_clock)."""
    return on_server_clock(db, wbk.activity_start(slot['slot_date'], slot['slot_time']), slot['service_id'])


def move_booking(db, b, slot):
    """Moves a booking to another departure: the new spots are taken before the old ones are released (atomic in the
    same transaction). Returns the old date and time."""
    pax = max(1, int(b['participants'] or 1))
    if b['slot_reserved']:
        if not reserve_slot_spots(db, slot['id'], pax): raise ValueError('No quedan plazas suficientes en esa salida.')
    db.execute('UPDATE bookings SET slot_id=?,booking_date=?,booking_time=?,reminder_sent_at=NULL,reminder48_sent_at=NULL,updated_at=? WHERE id=?',
               (slot['id'], slot['slot_date'], slot['slot_time'], now(), b['id']))
    db.execute('DELETE FROM manifest_entries WHERE booking_id=?', (b['id'],))
    if b['slot_reserved'] and b['slot_id']: release_slot_spots(db, b['slot_id'], pax)
    if b['slot_id']: slot_event(db, b['slot_id'], 'booking_moved_out', None, booking_id=b['id'], to_slot=slot['id'])
    slot_event(db, slot['id'], 'booking_moved_in', None, booking_id=b['id'], from_slot=b['slot_id'])
    return b['booking_date'], b['booking_time']


def when_text(date, time_, lang):
    return mail_date(date, lang) + (f' · {time_}' if time_ else '')


def target_slots(db, b, exclude=None):
    """Departures of the same service with enough free spots for the booking, not started."""
    pax = max(1, int(b['participants'] or 1)); out = []
    for s in db.execute("SELECT * FROM service_slots WHERE service_id=? AND status IN ('open','full') AND id<>? AND slot_date>=? ORDER BY slot_date,slot_time LIMIT 200",
                        (b['service_id'], exclude or b['slot_id'] or 0, local_now().date().isoformat())).fetchall():
        st = slot_start(db, s)
        if st and st <= local_now(): continue
        if int(s['spots_available'] or 0) < pax: continue
        out.append(s)
    return out


def provider_cancel_booking(db, b, reason, actor=None, source='slot_cancel', notify=True, refund=True):
    """The provider cancels a booking: spots released, pending payments cancelled and everything paid refunded.
    v50.47: with refund=False the refund is left to the notice worker (after the transaction, with Stripe's
    idempotency) and with notify=False the notices are sent by the notice queue."""
    release_booking_spots(db, b)
    db.execute("UPDATE bookings SET status='cancelled',cancelled_at=?,cancelled_by='center',reject_reason=?,updated_at=? WHERE id=?", (now(), reason, now(), b['id']))
    for o in db.execute("SELECT * FROM payment_orders WHERE booking_id=? AND status='pending'", (b['id'],)).fetchall():
        expire_checkout(o); db.execute("UPDATE payment_orders SET status='cancelled',updated_at=? WHERE id=?", (now(), o['id']))
    paid_, refunded_, _o = booking_paid_online(db, b['id']); net_ = round(paid_ - refunded_, 2)
    if not refund: return ('refund_pending' if net_ > 0 else 'none_paid'), net_
    outcome = refund_booking(db, b['id'], net_, 'requested_by_customer', actor, reason, source) if net_ > 0 else 'none_paid'
    if outcome == 'refunded' and notify: notify_booking(db, b['id'], 'refund_issued', {'amount': net_, 'note': reason})
    if notify: notify_booking(db, b['id'], 'cancelled_center', {'refund': outcome, 'reason': reason})
    return outcome, net_


def service_choice_hours(db, slot):
    r = db.execute('SELECT s.center_id,s.provider_user_id FROM provider_services s WHERE s.id=?', (slot['service_id'],)).fetchone()
    row = db.execute('SELECT slot_cancel_choice_hours AS h FROM centers WHERE id=?', (r['center_id'],)).fetchone() if r and r['center_id'] else \
        db.execute('SELECT slot_cancel_choice_hours AS h FROM users WHERE id=?', (r['provider_user_id'],)).fetchone() if r else None
    return int(row['h']) if row and row['h'] else SLOT_CHOICE_HOURS_DEFAULT


def slot_cancel_preview(db, slot):
    out = []
    for b in db.execute(f"""SELECT b.*, COALESCE(b.contact_name,u.fullname) AS diver_name FROM bookings b LEFT JOIN users u ON u.id=b.user_id
                            WHERE b.slot_id=? AND b.status IN ('requested','accepted_pending_payment','confirmed','payment_in_progress') ORDER BY b.id""", (slot['id'],)).fetchall():
        paid_, refunded_, _o = booking_paid_online(db, b['id']); net_ = round(paid_ - refunded_, 2)
        out.append({'booking_id': b['id'], 'name': b['diver_name'] if b['status'] != 'payment_in_progress' else None, 'participants': int(b['participants'] or 1), 'status': b['status'],
                    'paid': net_, 'currency': b['currency'] or 'EUR', 'alternatives': len(target_slots(db, b, slot['id'])) if b['status'] != 'payment_in_progress' else 0,
                    'receives': 'released' if b['status'] == 'payment_in_progress' else ('refund' if net_ > 0 else 'no_charge')})
    return out


def cancel_slot(db, user, slot, reason, note, hours, notify=True):
    """Cancels a departure and gives every booking the choice (punto 2). Returns the list of affected bookings.
    v50.47: with notify=False the divers are told by the notice queue (WhatsApp, email and app)."""
    affected = slot_cancel_preview(db, slot)
    db.execute("UPDATE service_slots SET status='closed',cancelled_at=?,cancel_reason=?,cancel_note=?,cancelled_by=?,updated_at=? WHERE id=?",
               (now(), reason, note, user['id'], now(), slot['id']))
    deadline = local_iso(local_now() + _timedelta(hours=hours))
    for a in affected:
        b = booking_row(db, a['booking_id'])
        if b['status'] == 'payment_in_progress':
            if expire_booking(db, b, 'slot_cancelled', notify=False) != 'paid': continue
            b = booking_row(db, a['booking_id'])
        db.execute('INSERT OR IGNORE INTO slot_cancel_offers(booking_id,slot_id,deadline,created_at) VALUES(?,?,?,?)', (b['id'], slot['id'], deadline, now()))
        if notify: notify_booking(db, b['id'], 'slot_cancelled', {'reason_key': reason, 'note': note, 'deadline_iso': deadline, 'paid_net': a['paid']})
    for w in db.execute("SELECT * FROM waitlist_entries WHERE slot_id=? AND status IN ('waiting','notified')", (slot['id'],)).fetchall():
        db.execute("UPDATE waitlist_entries SET status='cancelled',held=0,updated_at=? WHERE id=?", (now(), w['id']))
    slot_event(db, slot['id'], 'cancelled', user['id'], reason=reason, note=note, affected=len(affected), choice_hours=hours)
    audit(db, user['id'], 'service_slot_cancelled', 'service_slot', slot['id'], {'reason': reason, 'affected': len(affected)})
    return affected


def slot_offer_for(db, bid):
    return db.execute('''SELECT o.*, ss.slot_date, ss.slot_time, ss.cancel_reason, ss.cancel_note FROM slot_cancel_offers o JOIN service_slots ss ON ss.id=o.slot_id
                         WHERE o.booking_id=? ORDER BY o.id DESC LIMIT 1''', (bid,)).fetchone()


def resolve_slot_offer(db, b, offer, choice, actor=None, new_slot=None):
    """choice: 'reschedule' (with new_slot), 'refund' or 'auto' (deadline passed)."""
    if offer['resolved_at']: raise ValueError('Ya habías elegido una opción para esta reserva.')
    if choice == 'reschedule':
        if not new_slot or new_slot['service_id'] != b['service_id'] or new_slot['id'] == offer['slot_id']: raise ValueError('Elige otra salida del mismo servicio.')
        old_date, old_time = move_booking(db, b, new_slot)
        db.execute("UPDATE slot_cancel_offers SET choice='reschedule',new_slot_id=?,resolved_at=?,resolved_by=? WHERE id=?", (new_slot['id'], now(), actor, offer['id']))
        lang = user_lang(db, b['user_id'])
        notify_booking(db, b['id'], 'date_changed', {'old_when': when_text(old_date, old_time, lang), 'by': 'slot_cancel'})
        slot_event(db, offer['slot_id'], 'choice_reschedule', actor, booking_id=b['id'], to_slot=new_slot['id'])
        return 'rescheduled'
    outcome, amount = provider_cancel_booking(db, b, mail_t('es', 'Salida cancelada por el centro'), actor)
    db.execute("UPDATE slot_cancel_offers SET choice=?,refund_result=?,resolved_at=?,resolved_by=? WHERE id=?", ('refund' if choice == 'refund' else 'auto_refund', outcome, now(), actor, offer['id']))
    notify_booking(db, b['id'], 'slot_choice_center', {'choice_key': 'refund' if choice == 'refund' else 'auto'})
    slot_event(db, offer['slot_id'], 'choice_refund' if choice == 'refund' else 'auto_refund', actor, booking_id=b['id'], refund=outcome, amount=amount)
    return outcome


def run_slot_cancel_jobs(db):
    """Every minute: offers of cancelled departures whose deadline has passed get the full refund automatically."""
    now_l = local_iso(local_now())
    for o in db.execute('SELECT * FROM slot_cancel_offers WHERE resolved_at IS NULL AND deadline<? LIMIT 200', (now_l,)).fetchall():
        b = booking_row(db, o['booking_id'])
        if not b or b['status'] not in ('requested', 'accepted_pending_payment', 'confirmed'):
            db.execute("UPDATE slot_cancel_offers SET choice='closed',resolved_at=? WHERE id=?", (now(), o['id'])); db.commit(); continue
        try: resolve_slot_offer(db, b, o, 'auto'); db.commit()
        except Exception as exc:
            db.rollback(); audit(db, None, 'slot_cancel_auto_failed', 'booking', o['booking_id'], {'error': str(exc)[:200]}); db.commit()
    # Point 3: change requests whose original departure has started are closed.
    for r in db.execute("SELECT r.*, b.booking_date, b.booking_time, b.service_id AS b_service, b.center_id AS b_center FROM reschedule_requests r JOIN bookings b ON b.id=r.booking_id WHERE r.status='pending' LIMIT 200").fetchall():
        st = on_server_clock(db, wbk.activity_start(r['booking_date'], r['booking_time']), r['b_service'], r['b_center'])
        if st and st <= local_now():
            db.execute("UPDATE reschedule_requests SET status='expired',decided_at=? WHERE id=?", (now(), r['id'])); db.commit()
    run_waitlist_jobs(db)


# =================================================================== v50.47 · Mass notices of the centres (partes D y E)
# A centre cancels a departure (or changes its time or meeting point, or the day-before reminder goes out) and every
# diver of that departure is told by WhatsApp (from the centre's OWN number, with consent), email and the app.
# - The recipients are computed here, from the bookings of that departure of that centre. Never a list from the browser.
# - Nothing leaves for NOTICE_UNDO_SECONDS: the centre can undo. Then one transaction cancels the departure and its
#   bookings, prepares the refunds and queues one row per diver and channel (notice_outbox; unique per booking, event
#   and channel, so a double click or a restart never sends twice).
# - Before each message everything is checked again (centre of the session = of the departure = of the booking = owner
#   of the WhatsApp number). Any doubt: the message is not sent, it is marked «bloqueado por seguridad» and the
#   administrators are told (regla de oro).
NOTICE_UNDO_SECONDS = wcfg.env_int('WOD_AVISOS_DESHACER_SEGUNDOS', 10, 3, 120)
NOTICE_MAX_PER_DAY = wcfg.env_int('WOD_AVISOS_MAX_DIA', 10, 1, 500)
NOTICE_ALERT_RECIPIENTS = wcfg.env_int('WOD_AVISOS_ALERTA_DESTINATARIOS', 60, 2, 100000)
NOTICE_ALERT_CANCELLATIONS = wcfg.env_int('WOD_AVISOS_ALERTA_CANCELACIONES', 5, 1, 1000)
NOTICE_RETRY_MINUTES = (1, 5, 15, 60, 240)
NOTICE_LINK_DAYS = 14
NOTICE_RECIPIENT_STATES = ('requested', 'accepted_pending_payment', 'confirmed')
NOTICE_CHANNELS = ('whatsapp', 'email', 'app')
NOTICE_TEMPLATES = wwa.TEMPLATE_NAMES


def wa_enabled():
    """WhatsApp is on when the owner enabled it in the .env, and always in the test environment, where it is simulated:
    nothing goes to Meta and every message is written to data/pruebas/avisos/<centre>/whatsapp/."""
    return wwa.enabled() or wcfg.demo_mode()


def notice_actor_ctx(db, user):
    """The tenant of the session, for notices: owner or manager of a centre, or a freelance. Never the admin."""
    ctx = winq.ctx_from_user(db, user)
    if not ctx: raise PermissionError('Solo los centros y profesionales envían avisos a sus clientes.')
    if not ctx.can_send_notices: raise PermissionError(wroles.NO_PUEDE['avisos'])
    return ctx


def provider_settings(db, key):
    r = db.execute('SELECT * FROM provider_settings WHERE provider_id=?', (key,)).fetchone()
    return dict(r) if r else {'provider_id': key, 'notice_policy': 'choice', 'reminder_enabled': 1, 'reminder_hour': 18, 'reminder_bring': ''}


def tenant_parts(key):
    kind, oid = key.split(':')
    return ('center' if kind == 'c' else 'freelance'), int(oid)


def whatsapp_account(db, key):
    """The connected WhatsApp number of THIS tenant (never another one). None when WhatsApp is off or not connected."""
    if not wa_enabled(): return None
    return db.execute("SELECT * FROM whatsapp_accounts WHERE provider_id=? AND status='connected'", (key,)).fetchone()


def diver_contact(db, b):
    """Who the diver of a booking is and how they can be told. The WhatsApp phone is ONLY the one the diver wrote in
    their own profile, with their consent and an international prefix; never a phone typed or imported by a centre."""
    u = db.execute('''SELECT u.id,u.fullname,u.email,u.password_hash,u.guest_center_id,up.phone,up.wa_consent
                        FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id WHERE u.id=?''', (b['user_id'],)).fetchone()
    guest = (not u) or (u['password_hash'] == '!' and bool(u['guest_center_id']))
    name = (b['contact_name'] if guest and b['contact_name'] else (u['fullname'] if u else '')) or ''
    email = ((b['contact_email'] if guest else (u['email'] if u else '')) or '').strip().lower()
    phone = None if guest or not u else wcif.normalize_phone(u['phone'])
    return {'user_id': b['user_id'], 'name': name, 'email': email if mail_deliverable(email) else '', 'guest': guest,
            'phone': phone, 'consent': bool(u and not guest and u['wa_consent']), 'lang': user_lang(db, b['user_id'])}


def notice_channels(contact, wa_acc):
    """{channel: (recipient or None, reason when skipped)}."""
    out = {}
    if not wa_acc: out['whatsapp'] = (None, 'El centro no tiene WhatsApp conectado' if wa_enabled() else 'WhatsApp no está activado en el servidor')
    elif contact['guest']: out['whatsapp'] = (None, 'Cliente sin cuenta: sin permiso de WhatsApp')
    elif not contact['consent']: out['whatsapp'] = (None, 'Sin permiso para avisos por WhatsApp')
    elif not contact['phone']: out['whatsapp'] = (None, 'Teléfono sin prefijo internacional')
    else: out['whatsapp'] = (contact['phone'], '')
    out['email'] = (contact['email'], '') if contact['email'] else (None, 'Sin correo')
    out['app'] = (str(contact['user_id']), '') if not contact['guest'] else (None, 'Cliente sin cuenta en WORLDIVES')
    return out


def slot_label(slot, lang='es'):
    return f"{slot['service_title'] or ''} · {mail_date(slot['slot_date'], lang)}" + (f" · {slot['slot_time']}" if slot['slot_time'] else '')


def notice_link(bid, kind, slot_date):
    """Signed link that opens only this booking (14 days, and at least until 2 days after the departure)."""
    try: until = datetime.fromisoformat(f'{slot_date}T23:59:59').replace(tzinfo=timezone.utc).timestamp() + 2 * 86400
    except (TypeError, ValueError): until = 0
    exp = int(max(time.time() + NOTICE_LINK_DAYS * 86400, until))
    return wav.sign_link(notice_link_secret(), bid, kind, exp)


def notice_link_secret():
    """WOD_SECRET_KEY (required in production); without it, random per process, never a fixed text (ASVS 5.0 V9.1.3)."""
    return wcfg.env('WOD_SECRET_KEY') or wsec.secret_key().hex()


def notice_texts(db, kind, slot, booking, lang, *, center, reason=None, note=None, policy='choice', paid=0.0, new_time=None, new_point=None, bring=None, meeting=None):
    """(WhatsApp body params, app subject, app body) of one booking, in the diver's language."""
    lang = wav.lang_of(lang)
    date_txt = mail_date(slot['slot_date'], lang); time_txt = slot['slot_time'] or ''
    if kind == 'slot_cancelled':
        money = wav.money_text(policy, paid, mail_money(paid, booking['currency'] or 'EUR', lang), lang)
        params = wav.params(kind, lang, center=center, date=date_txt, time_=time_txt, reason=reason, note=note, money=money)
    elif kind == 'slot_changed':
        params = wav.params(kind, lang, center=center, date=date_txt, time_=time_txt, change=wav.change_text(lang, new_time, new_point), note=note)
    else:
        params = wav.params(kind, lang, center=center, date=date_txt, time_=time_txt, point=meeting, bring=bring)
    params = [wav.whatsapp_safe(p) for p in params]
    subject = wav.text('app_subject_' + kind, lang, service=slot['service_title'] or '')
    return params, subject, wav.body(kind, lang, params)


def notice_preview(db, ctx, slot_id, kind, *, reason=None, note='', policy=None, new_time=None, new_point=None):
    """What the confirmation screen shows: recipients per channel, names with initial, money of each booking and the
    message in each language. Computed only from the bookings of this departure of this tenant."""
    slot, rows = winq.slot_bookings(db, ctx, slot_id, NOTICE_RECIPIENT_STATES + ('payment_in_progress',))
    sett = provider_settings(db, ctx.key)
    policy = policy if policy in ('choice', 'refund') else sett['notice_policy']
    wa = whatsapp_account(db, ctx.key)
    center = provider_label(db, ctx.kind, ctx.oid)
    counts = {c: 0 for c in NOTICE_CHANNELS}; people = []; langs = {}; money = {'refund': 0.0, 'currency': None, 'paying': 0}
    for b in rows:
        if b['status'] == 'payment_in_progress':
            money['paying'] += 1; continue
        contact = diver_contact(db, b); chans = notice_channels(contact, wa)
        paid_, refunded_, _o = booking_paid_online(db, b['id']); net = round(paid_ - refunded_, 2)
        for c, (to, _why) in chans.items():
            if to: counts[c] += 1
        if kind == 'slot_cancelled' and net > 0: money['refund'] = round(money['refund'] + net, 2); money['currency'] = b['currency'] or 'EUR'
        people.append({'name': winq.first_name_initial(contact['name']), 'participants': int(b['participants'] or 1), 'lang': contact['lang'],
                       'channels': {c: bool(to) for c, (to, _w) in chans.items()}, 'why_not': {c: w for c, (to, w) in chans.items() if not to},
                       'paid': net, 'currency': b['currency'] or 'EUR',
                       'money': (('Devolución de ' + mail_money(net, b['currency'] or 'EUR', 'es')) if net > 0 else 'Sin cobro') if kind == 'slot_cancelled' and policy == 'refund' else
                                (('Elige otra fecha o devolución de ' + mail_money(net, b['currency'] or 'EUR', 'es')) if net > 0 else 'Elige otra fecha o anula sin coste') if kind == 'slot_cancelled' else ''})
        langs.setdefault(contact['lang'], b)
    previews = []
    for lang, b in sorted(langs.items()):
        paid_, refunded_, _o = booking_paid_online(db, b['id']); net = round(paid_ - refunded_, 2)
        params, subject, body = notice_texts(db, kind, slot, b, lang, center=center, reason=reason, note=note, policy=policy, paid=net,
                                             new_time=new_time, new_point=new_point, bring=sett.get('reminder_bring') or None, meeting=slot_meeting_point(db, slot))
        previews.append({'lang': lang, 'whatsapp': body, 'button': wav.button_label(kind, lang), 'app_subject': subject, 'app_body': body})
    return {'slot': {'id': slot['id'], 'uid': slot['uid'], 'label': slot_label(slot), 'date': slot['slot_date'], 'time': slot['slot_time'], 'service': slot['service_title'],
                     'cancelled': bool(slot['cancelled_at'])},
            'kind': kind, 'policy': policy, 'counts': counts, 'people': people, 'recipients': len(people), 'money': money, 'previews': previews,
            'whatsapp': {'enabled': wa_enabled(), 'connected': bool(wa), 'number': wcif.mask_phone(wcif.decrypt_secret(wa['display_number'])) if wa else None},
            'undo_seconds': NOTICE_UNDO_SECONDS, 'confirm_hint': confirm_words(slot)}


def slot_meeting_point(db, slot):
    mp = slot['meeting_point'] if 'meeting_point' in slot.keys() else None
    if mp: return mp
    kind, oid = tenant_parts(slot['provider_id'])
    if kind == 'center':
        c = db.execute('SELECT address, city FROM centers WHERE id=?', (oid,)).fetchone()
        return ', '.join(x for x in ((c['address'] if c else None), (c['city'] if c else None)) if x) or None
    return None


def confirm_words(slot):
    """What the centre may type to confirm: the date (17/10 or 2026-10-17) or the name of the departure."""
    d = slot['slot_date'] or ''
    short = f'{d[8:10]}/{d[5:7]}' if len(d) >= 10 else d
    return {'date': short, 'iso': d, 'name': slot['service_title'] or ''}


def confirm_matches(slot, typed):
    t = fold_text(str(typed or '').strip()).replace(' ', '')
    if not t: return False
    w = confirm_words(slot)
    return t in {fold_text(w['date']).replace(' ', ''), w['iso'], fold_text(w['name']).replace(' ', '')}


def create_notice_batch(db, handler, user, data, kind):
    """A mass notice of the session's tenant. Returns the batch row. Nothing is sent for NOTICE_UNDO_SECONDS."""
    ctx = notice_actor_ctx(db, user)
    slot = winq.get_slot(db, ctx, data.get('slot_id'))
    if kind in ('slot_cancelled', 'slot_changed'):
        st = slot_start(db, slot)
        if slot['cancelled_at'] and kind == 'slot_changed': raise ValueError('Esta salida está cancelada.')
        if st and st <= local_now(): raise ValueError('Esta salida ya ha empezado.')
    reason = data.get('reason') if kind == 'slot_cancelled' else None
    if kind == 'slot_cancelled' and reason not in wav.REASONS: raise ValueError('Elige el motivo de la cancelación.')
    note = wav.clean_note(data.get('note'))
    if kind == 'slot_cancelled' and reason == 'other' and not note: raise ValueError('Explica el motivo en la nota (máximo 200 caracteres).')
    policy = data.get('policy') if data.get('policy') in ('choice', 'refund') else provider_settings(db, ctx.key)['notice_policy']
    new_time = new_point = None
    if kind == 'slot_changed':
        new_time = clean_text(data.get('new_time'), 5) or None
        if new_time and not re.fullmatch(r'([01]\d|2[0-3]):[0-5]\d', new_time): raise ValueError('La hora debe tener el formato HH:MM.')
        if new_time == slot['slot_time']: new_time = None
        new_point = clean_text(data.get('meeting_point'), 160) or None
        if not new_time and not new_point: raise ValueError('Indica la nueva hora o el nuevo punto de encuentro.')
    if kind != 'reminder' and not confirm_matches(slot, data.get('confirm')):
        raise ValueError(f"Para confirmar, escribe la fecha de la salida ({confirm_words(slot)['date']}) o su nombre.")
    existing = db.execute("SELECT * FROM notice_batches WHERE slot_id=? AND provider_id=? AND kind='slot_cancelled' AND status IN ('scheduled','running','done')", (slot['id'], ctx.key)).fetchone() if kind == 'slot_cancelled' else None
    if existing: return existing                     # a double click shows the same notice, never a second one
    if kind == 'slot_cancelled' and slot['cancelled_at']: raise ValueError('Esta salida ya está cancelada.')
    today = local_now().date().isoformat()
    sent_today = db.execute("SELECT COUNT(*) FROM notice_batches WHERE provider_id=? AND kind IN ('slot_cancelled','slot_changed') AND status<>'undone' AND substr(created_at,1,10)=?",
                            (ctx.key, today)).fetchone()[0]
    if sent_today >= NOTICE_MAX_PER_DAY:
        security_alert('notice_limit', {'provider': ctx.key, 'today': sent_today, 'limit': NOTICE_MAX_PER_DAY}, user['id'])
        raise ValueError('Has llegado al límite de avisos masivos por día. Si es una emergencia, escribe a la administración.')
    pv = notice_preview(db, ctx, slot['id'], kind, reason=reason, note=note, policy=policy, new_time=new_time, new_point=new_point)
    uid = secrets.token_hex(16)
    run_after = (datetime.now(timezone.utc) + _timedelta(seconds=NOTICE_UNDO_SECONDS)).isoformat(timespec='seconds')
    try:
        db.execute('''INSERT INTO notice_batches(uid,provider_id,slot_id,kind,reason,note,policy,new_time,new_meeting,status,run_after,created_by,ip_hash,counts,created_at)
                      VALUES(?,?,?,?,?,?,?,?,?,'scheduled',?,?,?,?,?)''',
                   (uid, ctx.key, slot['id'], kind, reason, note or None, policy if kind == 'slot_cancelled' else None, new_time, new_point, run_after, user['id'],
                    wsec.ip_hash(handler.client_ip()) if handler else None, json.dumps({'previstos': pv['counts'], 'destinatarios': pv['recipients']}), now()))
    except sqlite3.IntegrityError:
        again = db.execute("SELECT * FROM notice_batches WHERE slot_id=? AND provider_id=? AND kind=? AND status IN ('scheduled','running','done')", (slot['id'], ctx.key, kind)).fetchone()
        if again: return again
        raise
    audit(db, user['id'], 'notice_batch_created', 'notice_batch', None, {'uid': uid, 'kind': kind, 'slot': slot['id'], 'provider': ctx.key,
                                                                         'recipients': pv['recipients'], 'channels': pv['counts']})
    if pv['recipients'] > NOTICE_ALERT_RECIPIENTS:
        security_alert('notice_unusual', {'provider': ctx.key, 'kind': kind, 'recipients': pv['recipients'], 'threshold': NOTICE_ALERT_RECIPIENTS}, user['id'])
    if kind == 'slot_cancelled':
        n = db.execute("SELECT COUNT(*) FROM notice_batches WHERE provider_id=? AND kind='slot_cancelled' AND status<>'undone' AND substr(created_at,1,10)=?", (ctx.key, today)).fetchone()[0]
        if n >= NOTICE_ALERT_CANCELLATIONS:
            security_alert('notice_unusual', {'provider': ctx.key, 'cancellations_today': n, 'threshold': NOTICE_ALERT_CANCELLATIONS}, user['id'])
    return db.execute('SELECT * FROM notice_batches WHERE uid=? AND provider_id=?', (uid, ctx.key)).fetchone()


def notice_batch_of(db, ctx, uid):
    r = db.execute('SELECT * FROM notice_batches WHERE uid=? AND provider_id=?', (str(uid or ''), ctx.key)).fetchone()
    if not r: raise NotFound('Aviso no encontrado.')
    return r


def undo_notice_batch(db, ctx, user, uid):
    b = notice_batch_of(db, ctx, uid)
    if db.execute("UPDATE notice_batches SET status='undone',finished_at=? WHERE id=? AND provider_id=? AND status='scheduled'", (now(), b['id'], ctx.key)).rowcount != 1:
        raise ValueError('Ya no se puede deshacer: el aviso ha empezado a salir.')
    audit(db, user['id'], 'notice_batch_undone', 'notice_batch', b['id'], {'uid': uid})
    return True


def notice_status(db, ctx, uid):
    """Status panel: one line per diver and channel (never the phone or email in clear)."""
    b = notice_batch_of(db, ctx, uid)
    slot = winq.get_slot(db, ctx, b['slot_id'])
    rows = db.execute('''SELECT o.*, bk.participants FROM notice_outbox o JOIN bookings bk ON bk.id=o.booking_id
                          WHERE o.batch_id=? AND o.provider_id=? ORDER BY o.booking_id, o.channel''', (b['id'], ctx.key)).fetchall()
    people = {}
    for r in rows:
        p = people.setdefault(r['booking_id'], {'name': winq.first_name_initial(r['recipient_name']), 'participants': r['participants'], 'lang': r['lang'], 'channels': {}})
        status = r['status']
        if r['channel'] == 'email' and r['email_id'] and status == 'sent':
            e = db.execute('SELECT status FROM email_outbox WHERE id=?', (r['email_id'],)).fetchone()
            status = {'sent': 'sent', 'queued': 'sending', 'sending': 'sending', 'failed': 'failed', 'expired': 'failed', 'skipped': 'skipped'}.get(e['status'] if e else '', status)
        p['channels'][r['channel']] = {'status': status, 'reason': r['skip_reason'] or r['last_error'] or '', 'at': r['read_at'] or r['delivered_at'] or r['sent_at']}
    summary = {}
    for p in people.values():
        for c, v in p['channels'].items(): summary.setdefault(c, {}).setdefault(v['status'], 0); summary[c][v['status']] += 1
    refunds = [dict(r) for r in db.execute('SELECT status, amount, currency FROM notice_refunds WHERE batch_id=?', (b['id'],)).fetchall()]
    left = max(0, int((datetime.fromisoformat(b['run_after']) - datetime.now(timezone.utc)).total_seconds())) if b['status'] == 'scheduled' else 0
    return {'uid': b['uid'], 'kind': b['kind'], 'status': b['status'], 'undo_left': left, 'slot': {'id': slot['id'], 'label': slot_label(slot)},
            'reason': b['reason'], 'note': b['note'], 'policy': b['policy'], 'created_at': b['created_at'], 'result': b['result'],
            'people': list(people.values()), 'summary': summary, 'refunds': refunds}


# ---- the worker
def _batch_actor(db, batch):
    u = db.execute('SELECT id FROM users WHERE id=?', (batch['created_by'],)).fetchone() if batch['created_by'] else None
    return {'id': u['id'] if u else None}


def execute_notice_batch(db, batch):
    """ONE transaction: the change (cancellation, new time…), the refunds to make and one queued row per diver and
    channel. If anything fails, nothing at all is changed."""
    slot = db.execute('''SELECT ss.*, s.title AS service_title, s.center_id, s.provider_user_id, s.currency AS service_currency
                           FROM service_slots ss JOIN provider_services s ON s.id=ss.service_id WHERE ss.id=? AND ss.provider_id=?''', (batch['slot_id'], batch['provider_id'])).fetchone()
    if not slot or slot['provider_id'] != batch['provider_id']:
        security_alert('notice_tenant_mismatch', {'batch': batch['uid'], 'provider': batch['provider_id'], 'slot': batch['slot_id']}, batch['created_by'])
        raise LookupError('la salida no es del centro del aviso')
    kind = batch['kind']; actor = _batch_actor(db, batch)
    tkind, toid = tenant_parts(batch['provider_id'])
    w, a = winq.owner_filter(winq.Ctx(actor['id'] or 0, tkind, tkind, toid), 'b')
    rows = db.execute(f"SELECT b.* FROM bookings b WHERE b.slot_id=? AND {w} AND b.status IN ({','.join('?' * len(NOTICE_RECIPIENT_STATES))}) ORDER BY b.id",
                      (slot['id'], *a, *NOTICE_RECIPIENT_STATES)).fetchall()
    paid = {}
    for b in rows:
        paid_, refunded_, _o = booking_paid_online(db, b['id']); paid[b['id']] = round(paid_ - refunded_, 2)
    if kind == 'slot_cancelled':
        if slot['cancelled_at']: raise ValueError('la salida ya estaba cancelada')
        reason_es = SLOT_CANCEL_REASONS.get(batch['reason'], 'Otro motivo')
        if batch['policy'] == 'refund':
            db.execute("UPDATE service_slots SET status='closed',cancelled_at=?,cancel_reason=?,cancel_note=?,cancelled_by=?,updated_at=? WHERE id=? AND provider_id=?",
                       (now(), batch['reason'], batch['note'], actor['id'], now(), slot['id'], batch['provider_id']))
            for b in db.execute("SELECT * FROM bookings WHERE slot_id=? AND provider_id=? AND status='payment_in_progress'", (slot['id'], batch['provider_id'])).fetchall():
                expire_booking(db, b, 'slot_cancelled', notify=False)
            for b in rows:
                provider_cancel_booking(db, b, reason_es + (f": {batch['note']}" if batch['note'] else ''), actor['id'], 'slot_cancel', notify=False, refund=False)
                if paid[b['id']] > 0:
                    db.execute('INSERT INTO notice_refunds(batch_id,provider_id,booking_id,amount,currency,status,created_at) VALUES(?,?,?,?,?,?,?)',
                               (batch['id'], batch['provider_id'], b['id'], paid[b['id']], b['currency'] or 'EUR', 'pending', now()))
            for wl in db.execute("SELECT id FROM waitlist_entries WHERE slot_id=? AND status IN ('waiting','notified')", (slot['id'],)).fetchall():
                db.execute("UPDATE waitlist_entries SET status='cancelled',held=0,updated_at=? WHERE id=?", (now(), wl['id']))
            slot_event(db, slot['id'], 'cancelled', actor['id'], reason=batch['reason'], note=batch['note'], affected=len(rows), policy='refund')
        else:
            cancel_slot(db, actor, slot, batch['reason'], batch['note'], service_choice_hours(db, slot), notify=False)
    elif kind == 'slot_changed':
        if batch['new_time']:
            db.execute('UPDATE notice_batches SET old_time=? WHERE id=? AND provider_id=?', (slot['slot_time'], batch['id'], batch['provider_id']))
            db.execute('UPDATE service_slots SET slot_time=?,updated_at=? WHERE id=? AND provider_id=?', (batch['new_time'], now(), slot['id'], batch['provider_id']))
            for b in rows: db.execute('UPDATE bookings SET booking_time=?,updated_at=? WHERE id=? AND provider_id=?', (batch['new_time'], now(), b['id'], batch['provider_id']))
        if batch['new_meeting']: db.execute('UPDATE service_slots SET meeting_point=?,updated_at=? WHERE id=? AND provider_id=?', (batch['new_meeting'], now(), slot['id'], batch['provider_id']))
        slot_event(db, slot['id'], 'changed', actor['id'], new_time=batch['new_time'], meeting_point=batch['new_meeting'], note=batch['note'])
    wa = whatsapp_account(db, batch['provider_id'])
    origin = wa['pnid_hash'] if wa else None
    queued = {c: 0 for c in NOTICE_CHANNELS}
    event = f"{kind}:{slot['id']}" if kind != 'slot_changed' else f"slot_changed:{batch['uid']}"
    for b in rows:
        contact = diver_contact(db, b)
        for ch, (to, why) in notice_channels(contact, wa).items():
            db.execute('''INSERT INTO notice_outbox(uid,batch_id,provider_id,slot_id,booking_id,event,channel,template,lang,status,recipient,recipient_name,origin,skip_reason,created_at,updated_at)
                          VALUES(?,?,?,?,?,?,?,?,?,?,wod_cifrar(?),?,?,?,?,?) ON CONFLICT(booking_id,event,channel) DO NOTHING''',
                       (secrets.token_hex(16), batch['id'], batch['provider_id'], slot['id'], b['id'], event, ch, NOTICE_TEMPLATES[kind], contact['lang'],
                        'queued' if to else 'skipped', to, contact['name'] or None, origin if ch == 'whatsapp' else None, why or None, now(), now()))
            if to: queued[ch] += 1
    db.execute('UPDATE notice_batches SET counts=?,result=? WHERE id=? AND provider_id=?', (json.dumps({'encolados': queued, 'destinatarios': len(rows)}), None, batch['id'], batch['provider_id']))
    return len(rows)


def run_notice_batches(db):
    due = db.execute("SELECT * FROM notice_batches WHERE status='scheduled' AND run_after<=? ORDER BY id LIMIT 20", (now(),)).fetchall()
    for batch in due:
        if not batch['provider_id']:
            security_alert('job_without_tenant', {'batch': batch['uid']}); continue
        if db.execute("UPDATE notice_batches SET status='running',started_at=? WHERE id=? AND provider_id=? AND status='scheduled'", (now(), batch['id'], batch['provider_id'])).rowcount != 1:
            db.commit(); continue
        db.commit()
        try:
            t0 = time.perf_counter()
            n = execute_notice_batch(db, batch)
            ms = int((time.perf_counter() - t0) * 1000)
            c = json.loads(db.execute('SELECT counts FROM notice_batches WHERE id=? AND provider_id=?', (batch['id'], batch['provider_id'])).fetchone()['counts'] or '{}'); c['ms'] = ms
            db.execute('UPDATE notice_batches SET counts=? WHERE id=? AND provider_id=?', (json.dumps(c), batch['id'], batch['provider_id']))
            audit(db, batch['created_by'], 'notice_batch_started', 'notice_batch', batch['id'], {'uid': batch['uid'], 'recipients': n, 'provider': batch['provider_id'], 'ms': ms})
            db.commit()
        except Exception as exc:
            db.rollback()
            blocked = isinstance(exc, LookupError)
            db.execute('UPDATE notice_batches SET status=?,result=?,finished_at=? WHERE id=? AND provider_id=?', ('blocked' if blocked else 'failed', str(exc)[:300], now(), batch['id'], batch['provider_id']))
            audit(db, batch['created_by'], 'notice_batch_failed', 'notice_batch', batch['id'], {'uid': batch['uid'], 'error': str(exc)[:200]})
            db.commit()


def run_notice_refunds(db):
    for r in db.execute("SELECT * FROM notice_refunds WHERE status='pending' AND (next_try_at IS NULL OR next_try_at<=?) ORDER BY id LIMIT 20", (now(),)).fetchall():
        b = db.execute('SELECT * FROM bookings WHERE id=? AND provider_id=?', (r['booking_id'], r['provider_id'])).fetchone()
        if not b or b['provider_id'] != r['provider_id']:
            db.execute("UPDATE notice_refunds SET status='blocked',last_error=? WHERE id=? AND provider_id=?", ('reserva de otro centro', r['id'], r['provider_id']))
            security_alert('refund_tenant_mismatch', {'notice_refund': r['id'], 'booking': r['booking_id'], 'provider': r['provider_id']}); db.commit(); continue
        if db.execute("UPDATE notice_refunds SET status='working',attempts=attempts+1 WHERE id=? AND status='pending'", (r['id'],)).rowcount != 1: db.commit(); continue
        db.commit()
        try:
            outcome = refund_booking(db, b['id'], r['amount'], 'requested_by_customer', None, 'Salida cancelada por el centro', 'slot_cancel')
            if outcome == 'refunded':
                db.execute("UPDATE notice_refunds SET status='done',result=?,done_at=? WHERE id=? AND provider_id=?", (outcome, now(), r['id'], r['provider_id']))
                notify_booking(db, b['id'], 'refund_issued', {'amount': r['amount'], 'note': ''})
            elif outcome in ('none_paid', 'no_refund'):
                db.execute("UPDATE notice_refunds SET status='done',result=?,done_at=? WHERE id=? AND provider_id=?", (outcome, now(), r['id'], r['provider_id']))
            else:
                att = int(r['attempts'] or 0) + 1
                db.execute("UPDATE notice_refunds SET status=?,result=?,next_try_at=? WHERE id=?",
                           ('failed' if att >= len(NOTICE_RETRY_MINUTES) else 'pending', outcome,
                            (datetime.now(timezone.utc) + _timedelta(minutes=NOTICE_RETRY_MINUTES[min(att, len(NOTICE_RETRY_MINUTES) - 1)])).isoformat(timespec='seconds'), r['id']))
            db.commit()
        except Exception as exc:
            db.rollback()
            db.execute("UPDATE notice_refunds SET status='pending',last_error=?,next_try_at=? WHERE id=?",
                       (str(exc)[:200], (datetime.now(timezone.utc) + _timedelta(minutes=15)).isoformat(timespec='seconds'), r['id'])); db.commit()


def notice_recheck(db, row):
    """Everything is checked again just before sending. Returns (problem, batch, booking, slot, account)."""
    # Each object is read only as part of the tenant of the message: an object of another tenant simply is not found.
    batch = db.execute('SELECT * FROM notice_batches WHERE id=? AND provider_id=?', (row['batch_id'], row['provider_id'])).fetchone()
    booking = db.execute('SELECT * FROM bookings WHERE id=? AND provider_id=?', (row['booking_id'], row['provider_id'])).fetchone()
    slot = db.execute('''SELECT ss.*, s.title AS service_title, s.center_id, s.provider_user_id FROM service_slots ss JOIN provider_services s ON s.id=ss.service_id
                          WHERE ss.id=? AND ss.provider_id=?''', (row['slot_id'], row['provider_id'])).fetchone()
    acc = db.execute('SELECT * FROM whatsapp_accounts WHERE provider_id=?', (row['provider_id'],)).fetchone() if row['channel'] == 'whatsapp' else None
    key = row['provider_id']
    if not batch or not booking or not slot: return 'faltan datos del aviso', batch, booking, slot, acc
    if batch['provider_id'] != key or booking['provider_id'] != key or slot['provider_id'] != key: return 'centro distinto', batch, booking, slot, acc
    if booking['slot_id'] != slot['id']: return 'la reserva no es de esta salida', batch, booking, slot, acc
    if batch['status'] not in ('running', 'done'): return 'aviso no activo', batch, booking, slot, acc
    if row['channel'] == 'whatsapp':
        if not acc or acc['status'] != 'connected': return 'whatsapp_off', batch, booking, slot, acc
        if acc['provider_id'] != key or acc['pnid_hash'] != row['origin']: return 'el número de origen no es el del centro', batch, booking, slot, acc
        # the credentials stored are really those of the number connected by this tenant (never another one's)
        if wcif.keyed_hash('pnid', wcif.decrypt_secret(acc['phone_number_id'])) != acc['pnid_hash']: return 'credenciales de WhatsApp de otro número', batch, booking, slot, acc
    return '', batch, booking, slot, acc


def _notice_retry(db, row, error, final=False):
    att = int(row['attempts'] or 0) + 1
    if final or att >= len(NOTICE_RETRY_MINUTES):
        db.execute("UPDATE notice_outbox SET status='failed',last_error=?,updated_at=? WHERE id=? AND provider_id=?", (str(error)[:200], now(), row['id'], row['provider_id']))
    else:
        nxt = (datetime.now(timezone.utc) + _timedelta(minutes=NOTICE_RETRY_MINUTES[att - 1])).isoformat(timespec='seconds')
        db.execute("UPDATE notice_outbox SET status='queued',last_error=?,next_try_at=?,updated_at=? WHERE id=? AND provider_id=?", (str(error)[:200], nxt, now(), row['id'], row['provider_id']))


def demo_notice_copy(row, payload):
    """Test environment: WhatsApp messages (and a copy of every notice) are written to a local folder per centre."""
    base = Path(os.environ['WOD_MAIL_FILE_DIR']).parent if os.environ.get('WOD_MAIL_FILE_DIR') else DATA
    folder = base / 'avisos' / row['provider_id'].replace(':', '-') / row['channel']
    folder.mkdir(parents=True, exist_ok=True)
    (folder / f"{row['created_at'][:10]}-{row['uid']}.json").write_text(json.dumps(payload, ensure_ascii=False, indent=1), encoding='utf-8')


def send_notice_row(db, row):
    if db.execute("UPDATE notice_outbox SET status='sending',attempts=attempts+1,updated_at=? WHERE id=? AND provider_id=? AND status='queued'", (now(), row['id'], row['provider_id'])).rowcount != 1:
        db.commit(); return
    db.commit()
    problem, batch, booking, slot, acc = notice_recheck(db, row)
    if problem == 'whatsapp_off':
        db.execute("UPDATE notice_outbox SET status='skipped',skip_reason=?,updated_at=? WHERE id=? AND provider_id=?",
                   ('El centro ha desconectado WhatsApp o tiene que reconectarlo' if acc else 'El centro no tiene WhatsApp conectado', now(), row['id'], row['provider_id'])); db.commit(); return
    if problem:
        db.execute("UPDATE notice_outbox SET status='blocked',skip_reason=?,updated_at=? WHERE id=? AND provider_id=?", ('Bloqueado por seguridad', now(), row['id'], row['provider_id']))
        security_alert('notice_tenant_mismatch', {'notice': row['uid'], 'provider': row['provider_id'], 'booking': row['booking_id'], 'channel': row['channel'], 'problem': problem})
        db.commit(); return
    kind = batch['kind']; lang = row['lang']
    tkind, toid = tenant_parts(row['provider_id'])
    center = provider_label(db, tkind, toid)
    paid_, refunded_, _o = booking_paid_online(db, booking['id'])
    paid = round(paid_ - refunded_, 2)
    if kind == 'slot_cancelled' and batch['policy'] == 'refund':
        r = db.execute('SELECT amount FROM notice_refunds WHERE batch_id=? AND booking_id=?', (batch['id'], booking['id'])).fetchone()
        paid = float(r['amount']) if r else paid
    sett = provider_settings(db, row['provider_id'])
    params, subject, body = notice_texts(db, kind, slot, booking, lang, center=center, reason=batch['reason'], note=batch['note'], policy=batch['policy'] or 'choice',
                                         paid=paid, new_time=batch['new_time'], new_point=batch['new_meeting'], bring=sett.get('reminder_bring') or None, meeting=slot_meeting_point(db, slot))
    link = notice_link(booking['id'], kind, slot['slot_date'])
    try:
        if row['channel'] == 'app':
            name, phone, email = provider_contact_of(db, row['provider_id'])
            mid = db.execute('''INSERT INTO messages(sender_user_id,recipient_user_id,booking_id,subject,body,created_at,kind,contact_phone,contact_email,sender_name)
                                VALUES(?,?,?,?,?,?,'notice',wod_cifrar(?),?,?)''',
                             (batch['created_by'] or booking['user_id'], booking['user_id'], booking['id'], subject, body + f"\n{public_site_url()}/r/{link}", now(), phone, email, name)).lastrowid
            db.execute("UPDATE notice_outbox SET status='sent',message_id=?,sent_at=?,updated_at=? WHERE id=? AND provider_id=?", (mid, now(), now(), row['id'], row['provider_id']))
            if wcfg.demo_mode(): demo_notice_copy(row, {'canal': 'app', 'asunto': subject, 'texto': body})
        elif row['channel'] == 'email':
            before = db.execute('SELECT COALESCE(MAX(id),0) FROM email_outbox').fetchone()[0]
            if kind == 'slot_cancelled' and batch['policy'] == 'refund':
                notify_booking(db, booking['id'], 'cancelled_center', {'refund': 'refund_pending' if paid > 0 else 'none_paid', 'reason': batch['reason'], 'note': batch['note']})
            elif kind == 'slot_cancelled':
                offer = slot_offer_for(db, booking['id'])
                notify_booking(db, booking['id'], 'slot_cancelled', {'reason_key': batch['reason'], 'note': batch['note'], 'paid_net': paid,
                                                                     'deadline_iso': offer['deadline'] if offer else None, 'link': f'{public_site_url()}/r/{link}'})
            elif kind == 'slot_changed':
                notify_booking(db, booking['id'], 'changed', {'old_when': when_text(slot['slot_date'], batch['old_time'] or slot['slot_time'], lang),
                                                              'reason': wav.change_text(lang, batch['new_time'], batch['new_meeting']) + (f". {batch['note']}" if batch['note'] else '')})
            else:
                notify_booking(db, booking['id'], 'reminder')
            eid = db.execute('SELECT MAX(id) FROM email_outbox WHERE id>? AND related_type=? AND related_id=?', (before, 'booking', booking['id'])).fetchone()[0]
            db.execute("UPDATE notice_outbox SET status=?,email_id=?,sent_at=?,updated_at=? WHERE id=? AND provider_id=?", ('sent' if eid else 'skipped', eid, now(), now(), row['id'], row['provider_id']))
            if wcfg.demo_mode(): demo_notice_copy(row, {'canal': 'correo', 'asunto': subject, 'texto': body})
        else:
            to = row['recipient']
            if not to or not wcif.normalize_phone(to):
                db.execute("UPDATE notice_outbox SET status='skipped',skip_reason=?,updated_at=? WHERE id=? AND provider_id=?", ('Teléfono no válido', now(), row['id'], row['provider_id'])); db.commit(); return
            u = db.execute('SELECT up.phone, up.wa_consent FROM user_profiles up WHERE up.user_id=?', (booking['user_id'],)).fetchone()
            if not u or not u['wa_consent'] or wcif.fingerprint(u['phone']) != wcif.fingerprint(to):
                db.execute("UPDATE notice_outbox SET status='skipped',skip_reason=?,updated_at=? WHERE id=? AND provider_id=?", ('El buceador ha retirado el permiso o cambiado el teléfono', now(), row['id'], row['provider_id'])); db.commit(); return
            name = NOTICE_TEMPLATES[kind]
            buttons = [link] + ([quote(slot_meeting_point(db, slot) or center)] if kind == 'reminder' else [])
            if wcfg.demo_mode():
                wamid = 'wamid.pruebas.' + row['uid'][:16]
                demo_notice_copy(row, {'canal': 'whatsapp', 'desde': wcif.mask_phone(wcif.decrypt_secret(acc['display_number'])), 'para': wcif.mask_phone(to),
                                       'plantilla': name, 'idioma': wwa.META_LANG.get(lang, 'es'), 'texto': body, 'boton_texto': wav.button_label(kind, lang),
                                       'boton': f'{public_site_url()}/r/{link}'})
            else:
                wamid = wwa.send_template(wcif.decrypt_secret(acc['token']), wcif.decrypt_secret(acc['phone_number_id']), to, name, lang, params, buttons)
            db.execute("UPDATE notice_outbox SET status='sent',wamid=?,sent_at=?,last_error=NULL,updated_at=? WHERE id=? AND provider_id=?", (wamid, now(), now(), row['id'], row['provider_id']))
        db.commit()
    except wwa.GraphError as exc:
        db.rollback()
        if exc.code in wwa.TOKEN_CODES:
            db.execute("UPDATE whatsapp_accounts SET status='reconnect',last_error=?,updated_at=? WHERE provider_id=?", ('El permiso de WhatsApp ha caducado o se ha retirado: reconecta.', now(), row['provider_id']))
            _notice_retry(db, row, 'El centro tiene que reconectar WhatsApp', final=True)
        else:
            _notice_retry(db, row, f'WhatsApp: {exc}', final=not exc.temporary)
        db.commit()
    except Exception as exc:
        db.rollback(); _notice_retry(db, row, exc); db.commit()


def provider_contact_of(db, key):
    """Name, phone and email the diver sees under a notice of this tenant (to answer the centre directly)."""
    kind, oid = tenant_parts(key)
    if kind == 'center':
        c = db.execute('SELECT name,phone,email FROM centers WHERE id=?', (oid,)).fetchone()
        return (c['name'], c['phone'] or '', c['email'] or '') if c else ('', '', '')
    u = db.execute('SELECT u.fullname,u.email,up.phone FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id WHERE u.id=?', (oid,)).fetchone()
    return (u['fullname'], u['phone'] or '', u['email'] or '') if u else ('', '', '')


def run_notice_outbox(db, budget=200):
    # A row left «sending» by a restart is never sent again automatically (it may have left): «unknown».
    db.execute("UPDATE notice_outbox SET status='unknown',last_error='Interrumpido (reinicio del servidor): revisa con el cliente' WHERE status='sending' AND updated_at<?",
               ((datetime.now(timezone.utc) - _timedelta(minutes=5)).isoformat(timespec='seconds'),)); db.commit()
    rows = db.execute("SELECT * FROM notice_outbox WHERE status='queued' AND (next_try_at IS NULL OR next_try_at<=?) ORDER BY id LIMIT ?", (now(), budget)).fetchall()
    per_origin = {}
    for row in rows:
        if not row['provider_id']: security_alert('job_without_tenant', {'notice': row['uid']}); continue
        if row['channel'] == 'whatsapp':      # Meta's throughput per number: never more than SEND_PER_SECOND
            n = per_origin.get(row['origin'], 0)
            if n and n % wwa.SEND_PER_SECOND == 0: time.sleep(1)
            per_origin[row['origin']] = n + 1
        send_notice_row(db, row)
    # Batches whose rows are all final are done.
    for b in db.execute("SELECT id, provider_id FROM notice_batches WHERE status='running'").fetchall():
        if not db.execute("SELECT 1 FROM notice_outbox WHERE batch_id=? AND provider_id=? AND status IN ('queued','sending')", (b['id'], b['provider_id'])).fetchone() and \
           not db.execute("SELECT 1 FROM notice_refunds WHERE batch_id=? AND status IN ('pending','working')", (b['id'],)).fetchone():
            summary = {r['channel'] + ':' + r['status']: r['n'] for r in db.execute('SELECT channel,status,COUNT(*) n FROM notice_outbox WHERE batch_id=? AND provider_id=? GROUP BY 1,2', (b['id'], b['provider_id'])).fetchall()}
            db.execute("UPDATE notice_batches SET status='done',finished_at=?,result=? WHERE id=? AND provider_id=?", (now(), json.dumps(summary), b['id'], b['provider_id']))
            audit(db, None, 'notice_batch_done', 'notice_batch', b['id'], summary)
    db.commit()


def run_reminder_batches(db):
    """Day-before reminder at the hour each tenant chose (default 18:00). One per departure."""
    nowl = local_now(); tomorrow = (nowl.date() + _timedelta(days=1)).isoformat()
    rows = db.execute(f'''SELECT ss.id, ss.provider_id, COALESCE(ps.reminder_hour,18) AS hour FROM service_slots ss LEFT JOIN provider_settings ps ON ps.provider_id=ss.provider_id
                           WHERE ss.slot_date=? AND ss.status IN ('open','full') AND ss.cancelled_at IS NULL AND COALESCE(ps.reminder_enabled,1)=1
                             AND ss.provider_id IS NOT NULL AND ss.provider_id<>'x:0'
                             AND EXISTS(SELECT 1 FROM bookings b WHERE b.slot_id=ss.id AND b.status='confirmed')
                             AND NOT EXISTS(SELECT 1 FROM notice_batches nb WHERE nb.slot_id=ss.id AND nb.kind='reminder' AND nb.status<>'undone')''', (tomorrow,)).fetchall()
    for r in rows:
        if nowl.hour < int(r['hour']): continue
        try:
            db.execute('''INSERT INTO notice_batches(uid,provider_id,slot_id,kind,status,run_after,created_at) VALUES(?,?,?,'reminder','scheduled',?,?)''',
                       (secrets.token_hex(16), r['provider_id'], r['id'], now(), now()))
            db.commit()
        except sqlite3.IntegrityError:
            db.rollback()


def run_notice_jobs(db):
    run_reminder_batches(db)
    run_notice_batches(db)
    run_notice_refunds(db)
    run_notice_outbox(db)


# ---- WhatsApp of each centre (parte D)
def whatsapp_status(db, ctx):
    acc = db.execute('SELECT * FROM whatsapp_accounts WHERE provider_id=?', (ctx.key,)).fetchone()
    country = ''
    if ctx.kind == 'center':
        c = db.execute('SELECT country FROM centers WHERE id=?', (ctx.oid,)).fetchone(); country = country_iso(c['country']) if c else ''
    tpl = json.loads(acc['templates'] or '{}') if acc else {}
    return {'enabled': wa_enabled(), 'demo': wcfg.demo_mode(), 'app_id': wcfg.env('WHATSAPP_APP_ID') if wwa.enabled() else '', 'config_id': wcfg.env('WHATSAPP_CONFIG_ID') if wa_enabled() else '',
            'graph_version': wcfg.env('WHATSAPP_GRAPH_VERSION') or 'v23.0', 'country': country, 'coexistence_available': not wwa.coex_unavailable(country),
            'connected': bool(acc), 'status': acc['status'] if acc else None, 'number': wcif.mask_phone(wcif.decrypt_secret(acc['display_number'])) if acc else None,
            'verified_name': acc['verified_name'] if acc else None, 'coexistence': bool(acc['coexistence']) if acc else None, 'connected_at': acc['connected_at'] if acc else None,
            'last_error': acc['last_error'] if acc else None,
            'templates': {'approved': sum(1 for v in tpl.values() if v in ('APPROVED', 'EXISTS')), 'pending': sum(1 for v in tpl.values() if v in ('PENDING', 'IN_APPEAL')),
                          'rejected': sum(1 for v in tpl.values() if v in ('REJECTED', 'ERROR', 'DISABLED', 'PAUSED')), 'total': len(tpl)},
            'can_manage': ctx.can_send_notices}


def country_iso(name):
    n = fold_text(str(name or '')).strip()
    if len(n) == 2: return n.upper()
    return COUNTRY_ISO.get(n, '')


COUNTRY_ISO = {'espana': 'ES', 'spain': 'ES', 'portugal': 'PT', 'francia': 'FR', 'france': 'FR', 'italia': 'IT', 'italy': 'IT', 'alemania': 'DE', 'germany': 'DE',
               'reino unido': 'GB', 'united kingdom': 'GB', 'mexico': 'MX', 'egipto': 'EG', 'egypt': 'EG', 'tailandia': 'TH', 'thailand': 'TH', 'indonesia': 'ID',
               'filipinas': 'PH', 'philippines': 'PH', 'malta': 'MT', 'croacia': 'HR', 'croatia': 'HR', 'grecia': 'GR', 'greece': 'GR', 'nigeria': 'NG',
               'sudafrica': 'ZA', 'south africa': 'ZA', 'estados unidos': 'US', 'united states': 'US', 'belice': 'BZ', 'honduras': 'HN', 'colombia': 'CO', 'brasil': 'BR'}


def whatsapp_connect(db, ctx, user, data):
    """Embedded Signup finished in the browser: the server exchanges the code, checks that the number belongs to the
    WhatsApp Business account the centre has just authorised and that no other centre uses it, subscribes the app,
    registers the number (not with coexistence) and creates the templates. Credentials are stored encrypted."""
    if not wa_enabled(): raise ValueError('WhatsApp todavía no está activado en WORLDIVES.')
    if wcfg.demo_mode(): return whatsapp_connect_demo(db, ctx, user, data)
    code = clean_text(data.get('code'), 600)
    if not code: raise ValueError('Falta la autorización de Meta: vuelve a pulsar «Conectar mi WhatsApp Business».')
    coex = bool(data.get('coexistence'))
    try:
        token = wwa.exchange_code(code)
        info = wwa.verify_connection(token, clean_text(data.get('waba_id'), 40), clean_text(data.get('phone_number_id'), 40))
    except wwa.GraphError as exc:
        security_alert('whatsapp_wrong_number', {'provider': ctx.key, 'error': str(exc)[:150]}, user['id'])
        raise ValueError(f'No se ha podido conectar: {exc}')
    digits = re.sub(r'\D', '', info['display_number'])
    number = '+' + digits if digits else ''
    number_hash = wcif.fingerprint(number); pnid_hash = wcif.keyed_hash('pnid', info['phone_number_id']); waba_hash = wcif.keyed_hash('waba', info['waba_id'])
    other = db.execute('SELECT provider_id FROM whatsapp_accounts WHERE (number_hash=? OR pnid_hash=?) AND provider_id<>?', (number_hash, pnid_hash, ctx.key)).fetchone()
    if other:
        # Never says which centre has it (regla de oro); the administrators are told.
        security_alert('whatsapp_number_taken', {'provider': ctx.key, 'number': wcif.mask_phone(number)}, user['id'])
        raise ValueError('Ese número de WhatsApp ya está conectado en WORLDIVES. Si es tuyo, escribe a la administración.')
    try:
        wwa.subscribe_app(token, info['waba_id'])
        if not coex: wwa.register_number(token, info['phone_number_id'], f'{secrets.randbelow(10**6):06d}')
        templates = wwa.create_templates(token, info['waba_id'], wwa.template_payloads(wav.data(), public_site_url()))
    except wwa.GraphError as exc:
        raise ValueError(f'Meta ha rechazado un paso de la conexión: {exc}')
    vals = (wcif.encrypt_secret(info['waba_id']), wcif.encrypt_secret(info['phone_number_id']), wcif.encrypt_secret(number), wcif.encrypt_secret(token),
            pnid_hash, number_hash, waba_hash, info['verified_name'][:120], 1 if coex else 0, json.dumps(templates), now(), user['id'], now())
    db.execute('''INSERT INTO whatsapp_accounts(provider_id,status,waba_id,phone_number_id,display_number,token,pnid_hash,number_hash,waba_hash,verified_name,coexistence,templates,connected_at,connected_by,updated_at)
                  VALUES(?,'connected',?,?,?,?,?,?,?,?,?,?,?,?,?)
                  ON CONFLICT(provider_id) DO UPDATE SET status='connected',waba_id=excluded.waba_id,phone_number_id=excluded.phone_number_id,display_number=excluded.display_number,
                  token=excluded.token,pnid_hash=excluded.pnid_hash,number_hash=excluded.number_hash,waba_hash=excluded.waba_hash,verified_name=excluded.verified_name,
                  coexistence=excluded.coexistence,templates=excluded.templates,connected_at=excluded.connected_at,connected_by=excluded.connected_by,last_error=NULL,updated_at=excluded.updated_at''',
               (ctx.key, *vals))
    audit(db, user['id'], 'whatsapp_connected', 'provider', None, {'provider': ctx.key, 'number': wcif.mask_phone(number), 'coexistence': coex})
    db.commit()
    return whatsapp_status(db, ctx)


def whatsapp_connect_demo(db, ctx, user, data):
    """Test environment only: a simulated WhatsApp number for the centre (no Meta account). Uniqueness between centres
    is checked as in production."""
    number = wcif.normalize_phone(data.get('number'))
    if not number: raise ValueError('Escribe el número de WhatsApp con prefijo internacional, por ejemplo +34 600 000 101.')
    pnid = 'pruebas-' + ctx.key.replace(':', '-')
    number_hash = wcif.fingerprint(number); pnid_hash = wcif.keyed_hash('pnid', pnid)
    if db.execute('SELECT 1 FROM whatsapp_accounts WHERE (number_hash=? OR pnid_hash=?) AND provider_id<>?', (number_hash, pnid_hash, ctx.key)).fetchone():
        security_alert('whatsapp_number_taken', {'provider': ctx.key, 'number': wcif.mask_phone(number)}, user['id'])
        raise ValueError('Ese número de WhatsApp ya está conectado en WORLDIVES. Si es tuyo, escribe a la administración.')
    tpl = {f'{n}:{wwa.META_LANG[l]}': 'APPROVED' for n in wwa.TEMPLATE_NAMES.values() for l in wwa.META_LANG}
    db.execute('''INSERT INTO whatsapp_accounts(provider_id,status,waba_id,phone_number_id,display_number,token,pnid_hash,number_hash,waba_hash,verified_name,coexistence,templates,connected_at,connected_by,updated_at)
                  VALUES(?,'connected',?,?,?,?,?,?,?,?,1,?,?,?,?)
                  ON CONFLICT(provider_id) DO UPDATE SET status='connected',phone_number_id=excluded.phone_number_id,display_number=excluded.display_number,token=excluded.token,
                  pnid_hash=excluded.pnid_hash,number_hash=excluded.number_hash,templates=excluded.templates,connected_at=excluded.connected_at,last_error=NULL,updated_at=excluded.updated_at''',
               (ctx.key, wcif.encrypt_secret('pruebas-' + ctx.key), wcif.encrypt_secret(pnid), wcif.encrypt_secret(number), wcif.encrypt_secret('pruebas'), pnid_hash, number_hash,
                wcif.keyed_hash('waba', 'pruebas-' + ctx.key), 'WhatsApp de prueba', json.dumps(tpl), now(), user['id'], now()))
    audit(db, user['id'], 'whatsapp_connected', 'provider', None, {'provider': ctx.key, 'number': wcif.mask_phone(number), 'pruebas': True})
    db.commit()
    return whatsapp_status(db, ctx)


def whatsapp_refresh_templates(db, ctx):
    acc = db.execute("SELECT * FROM whatsapp_accounts WHERE provider_id=?", (ctx.key,)).fetchone()
    if not acc: raise NotFound('No tienes WhatsApp conectado.')
    if wcfg.demo_mode(): return whatsapp_status(db, ctx)
    try:
        st = wwa.template_statuses(wcif.decrypt_secret(acc['token']), wcif.decrypt_secret(acc['waba_id']))
    except wwa.GraphError as exc:
        if exc.code in wwa.TOKEN_CODES:
            db.execute("UPDATE whatsapp_accounts SET status='reconnect',last_error=?,updated_at=? WHERE provider_id=?", ('El permiso de WhatsApp ha caducado o se ha retirado: reconecta.', now(), ctx.key)); db.commit()
        raise ValueError(f'Meta no ha respondido: {exc}')
    mine = {k: v for k, v in st.items() if k.split(':')[0] in wwa.TEMPLATE_NAMES.values()}
    db.execute('UPDATE whatsapp_accounts SET templates=?,updated_at=? WHERE provider_id=?', (json.dumps(mine), now(), ctx.key)); db.commit()
    return whatsapp_status(db, ctx)


WA_STATUS_ORDER = {'sent': 1, 'delivered': 2, 'read': 3, 'failed': 4}


def whatsapp_webhook(handler, db):
    """Statuses of the messages sent (sent/delivered/read/failed) and template reviews. Signed by Meta with the app
    secret (X-Hub-Signature-256); duplicates are ignored; a status is applied only to a message sent from that very
    number of that very centre. The divers' replies are never read or stored: they reach the centre's WhatsApp."""
    raw = handler.rfile.read(body_length(handler, wcfg.MAX_WEBHOOK_BYTES))
    if not wwa.valid_signature(raw, handler.headers.get('X-Hub-Signature-256') or ''):
        security_alert('webhook_bad_signature', {'bytes': len(raw)}); handler.send_json({'error': 'Firma no válida.'}, 403); return
    try: payload = json.loads(raw.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError): handler.send_json({'error': 'JSON no válido.'}, 400); return
    applied = ignored = 0
    for pnid, wamid, status, ts, err in wwa.statuses_of(payload):
        key = hashlib.sha256(f'{wamid}|{status}|{ts}'.encode()).hexdigest()
        if db.execute('INSERT OR IGNORE INTO whatsapp_webhook_events(event_key,received_at) VALUES(?,?)', (key, now())).rowcount != 1: ignored += 1; continue
        row = db.execute('SELECT * FROM notice_outbox WHERE wamid=?', (wamid,)).fetchone()
        ph = wcif.keyed_hash('pnid', pnid)
        acc = db.execute('SELECT provider_id FROM whatsapp_accounts WHERE pnid_hash=?', (ph,)).fetchone()
        if not row or row['origin'] != ph or not acc or acc['provider_id'] != row['provider_id']:
            security_alert('webhook_wrong_number', {'known_message': bool(row), 'status': status}); ignored += 1; continue
        if status not in WA_STATUS_ORDER: continue
        cur = WA_STATUS_ORDER.get(row['status'], 0)
        if status != 'failed' and WA_STATUS_ORDER[status] <= cur: continue
        col = {'delivered': 'delivered_at', 'read': 'read_at'}.get(status)
        db.execute(f"UPDATE notice_outbox SET status=?,{col + '=?,' if col else ''}last_error=?,updated_at=? WHERE id=? AND provider_id=?",
                   (status, *([now()] if col else []), (f'Meta: error {err}' if status == 'failed' and err else row['last_error']), now(), row['id'], row['provider_id']))
        applied += 1
    for waba, name, lang, st in wwa.template_updates_of(payload):
        acc = db.execute('SELECT provider_id,templates FROM whatsapp_accounts WHERE waba_hash=?', (wcif.keyed_hash('waba', waba),)).fetchone()
        if not acc: continue
        tpl = json.loads(acc['templates'] or '{}'); tpl[f'{name}:{lang}'] = st
        db.execute('UPDATE whatsapp_accounts SET templates=?,updated_at=? WHERE provider_id=?', (json.dumps(tpl), now(), acc['provider_id']))
    db.commit()
    handler.send_json({'ok': True, 'applied': applied, 'ignored': ignored})


# ---- signed links of the notices (D.2.4)
def signed_link_booking(db, token):
    got = wav.verify_link(notice_link_secret(), token)
    b = booking_row(db, got[0]) if got else None
    if not b: raise NotFound('El enlace no es válido o ha caducado.')
    return b, got[1]


def signed_link_view(db, b, kind):
    """What the link of a notice opens: only this booking (no other data of the diver or of the centre)."""
    svc = db.execute('SELECT title FROM provider_services WHERE id=? AND provider_id=?', (b['service_id'], b['provider_id'])).fetchone() if b['service_id'] else None
    who = booking_payee(db, b)[1] or {}
    slot = db.execute('SELECT slot_date,slot_time,meeting_point,provider_id FROM service_slots WHERE id=?', (b['slot_id'],)).fetchone() if b['slot_id'] else None
    out = {'kind': kind, 'booking': {'ref': f"WOD-{b['id']:06d}", 'participants': b['participants'], 'status': b['status'], 'service': svc['title'] if svc else '',
                                      'center': who.get('name') or '', 'center_phone': who.get('phone') or '', 'center_email': who.get('email') or '',
                                      'booking_date': b['booking_date'], 'booking_time': b['booking_time'],
                                      'meeting_point': (slot['meeting_point'] if slot else None) or (slot_meeting_point(db, dict(slot, meeting_point=slot['meeting_point'])) if slot else None)}}
    offer = slot_offer_for(db, b['id'])
    if offer:
        paid_, refunded_, _o = booking_paid_online(db, b['id']); net_ = round(paid_ - refunded_, 2)
        out['offer'] = {'slot_date': offer['slot_date'], 'slot_time': offer['slot_time'], 'reason': offer['cancel_reason'], 'note': offer['cancel_note'], 'deadline': offer['deadline'],
                        'choice': offer['choice'], 'resolved_at': offer['resolved_at']}
        out['paid'] = net_; out['currency'] = b['currency'] or 'EUR'
        out['alternatives'] = [{'slot_id': x['id'], 'slot_date': x['slot_date'], 'slot_time': x['slot_time'], 'spots_available': x['spots_available']}
                               for x in target_slots(db, b, offer['slot_id'])] if not offer['resolved_at'] else []
    return out


# ---- WhatsApp consent of the diver (C.5)
WA_CONSENT_TEXT = 'Recibir por WhatsApp los avisos de mis reservas del centro'


def set_wa_consent(db, user_id, granted, lang, source, ip=None):
    db.execute('INSERT OR IGNORE INTO user_profiles(user_id,updated_at) VALUES(?,?)', (user_id, now()))
    cur = db.execute('SELECT wa_consent FROM user_profiles WHERE user_id=?', (user_id,)).fetchone()
    if bool(cur and cur['wa_consent']) == bool(granted): return False
    db.execute('UPDATE user_profiles SET wa_consent=?,wa_consent_at=?,wa_consent_version=?,wa_consent_lang=?,updated_at=? WHERE user_id=?',
               (1 if granted else 0, now(), WHATSAPP_CONSENT_VERSION, normalize_lang(lang or 'es'), now(), user_id))
    db.execute('INSERT INTO consent_log(user_id,kind,granted,created_at,ip_hash,text_version,lang,source) VALUES(?,?,?,?,?,?,?,?)',
               (user_id, 'whatsapp_avisos', 1 if granted else 0, now(), wsec.ip_hash(ip) if ip else None, WHATSAPP_CONSENT_VERSION, normalize_lang(lang or 'es'), source))
    return True


def wa_profile_info(db, user_id):
    p = db.execute('SELECT phone, wa_consent, wa_consent_at, wa_consent_version FROM user_profiles WHERE user_id=?', (user_id,)).fetchone()
    phone = p['phone'] if p else None
    return {'consent': bool(p and p['wa_consent']), 'consent_at': p['wa_consent_at'] if p else None, 'version': p['wa_consent_version'] if p else None,
            'phone_ok': bool(wcif.normalize_phone(phone)), 'phone_warning': wcif.phone_problem(phone), 'text': WA_CONSENT_TEXT}


# ---- C.3: every view or export of phones by a centre is logged
def count_phones(obj):
    """Phones of clients inside an answer (the centre's own public phone does not count)."""
    if isinstance(obj, dict):
        return sum((1 if (isinstance(k, str) and 'phone' in k and k not in ('center_phone',) and v) else count_phones(v)) if not isinstance(v, (dict, list)) else count_phones(v) for k, v in obj.items())
    if isinstance(obj, list): return sum(count_phones(x) for x in obj)
    return 0


def log_phone_access(db, user, what, count, ref=None):
    if not user or user['role'] not in ('center', 'freelance', 'admin') or not count: return
    audit(db, user['id'], 'phones_viewed' if not what.startswith('export') else 'phones_exported', what, ref, {'phones': count})
    db.commit()


def notice_loop():
    """Background thread (only in the worker process): notices go out a few seconds after the undo window."""
    while True:
        db = None
        try:
            db = connect(); run_notice_jobs(db)
        except Exception as exc:
            sys.stderr.write(f'[avisos] {type(exc).__name__}: {exc}\n')
        finally:
            if db is not None: db.close()
            flush_security_alerts()
        time.sleep(wcfg.env_int('WOD_AVISOS_SEGUNDOS', 2, 1, 60))


# ---- 3. Change of date by the diver
def reschedule_policy(db, b):
    s = db.execute('SELECT reschedule_mode, reschedule_hours FROM provider_services WHERE id=?', (b['service_id'],)).fetchone() if b['service_id'] else None
    mode = (s['reschedule_mode'] if s and s['reschedule_mode'] in RESCHEDULE_MODES else 'approval') if s else 'none'
    hours = int(s['reschedule_hours']) if s and s['reschedule_hours'] is not None else RESCHEDULE_HOURS_DEFAULT
    return mode, hours


def reschedule_options(db, b, user):
    """What «Cambiar fecha» offers to the diver for a booking: whether it is allowed, until when, and the departures."""
    mode, hours = reschedule_policy(db, b)
    start = wbk.activity_start(b['booking_date'], b['booking_time'])
    until = start - _timedelta(hours=hours) if start else None   # wall time of the place
    until_here = on_server_clock(db, until, b['service_id'], b['center_id'])
    pending = db.execute("SELECT r.*, ss.slot_date, ss.slot_time FROM reschedule_requests r JOIN service_slots ss ON ss.id=r.to_slot_id WHERE r.booking_id=? AND r.status='pending'", (b['id'],)).fetchone()
    why = None
    if mode == 'none': why = 'Este centro no permite cambiar la fecha desde la web. Escríbele si lo necesitas.'
    elif b['status'] not in ('requested', 'accepted_pending_payment', 'confirmed') or not b['slot_id']: why = 'Esta reserva ya no se puede cambiar de fecha.'
    elif db.execute(f"SELECT 1 FROM slot_cancel_offers WHERE booking_id=? AND resolved_at IS NULL", (b['id'],)).fetchone(): why = 'El centro ha cancelado esta salida: elige la nueva fecha desde el aviso de cancelación.'
    elif until_here and local_now() > until_here: why = 'El plazo para cambiar la fecha ha terminado.'
    opts = []
    if not why:
        pax = max(1, int(b['participants'] or 1)); old_total = float(b['price'] or 0)
        for s in target_slots(db, b):
            unit = effective_service_tariff(db, b['service_id'], s['slot_date'])[0]
            base_old = effective_service_tariff(db, b['service_id'], b['booking_date'])[0]
            diff = round((float(unit or 0) - float(base_old or 0)) * pax, 2)
            opts.append({'slot_id': s['id'], 'slot_date': s['slot_date'], 'slot_time': s['slot_time'], 'spots_available': s['spots_available'], 'price_diff': diff})
    return {'allowed': not why, 'reason': why, 'mode': mode, 'hours': hours, 'until': place_instant(until, place_tz(db, b['service_id'], b['center_id'])) if until else None, 'options': opts, 'currency': b['currency'] or 'EUR',
            'pending': {'id': pending['id'], 'slot_date': pending['slot_date'], 'slot_time': pending['slot_time'], 'price_diff': pending['price_diff']} if pending else None}


# ---- 4. Waiting list
def waitlist_offer(db, slot_id):
    """Spots were freed: keep them for the first people of the list who fit (2 h, never after the start)."""
    s = db.execute('''SELECT ss.*, ps.waitlist_enabled, ps.title AS service_title, ps.center_id, ps.provider_user_id FROM service_slots ss JOIN provider_services ps ON ps.id=ss.service_id
                      WHERE ss.id=?''', (slot_id,)).fetchone()
    if not s or s['status'] not in ('open', 'full') or s['cancelled_at'] or not (s['waitlist_enabled'] if s['waitlist_enabled'] is not None else 1): return
    start = slot_start(db, s)
    if not start or start <= local_now(): return
    for w in db.execute("SELECT * FROM waitlist_entries WHERE slot_id=? AND status='waiting' ORDER BY created_at, id", (slot_id,)).fetchall():
        free = db.execute('SELECT spots_available FROM service_slots WHERE id=?', (slot_id,)).fetchone()['spots_available']
        if free <= 0: break
        if w['participants'] > free: continue
        if not reserve_slot_spots(db, slot_id, w['participants']): continue
        until = min(local_now() + _timedelta(hours=WAITLIST_HOLD_HOURS), start)
        db.execute("UPDATE waitlist_entries SET status='notified',held=?,notified_at=?,expires_at=?,updated_at=? WHERE id=?", (w['participants'], now(), local_iso(until), now(), w['id']))
        u = db.execute('SELECT id,fullname,email FROM users WHERE id=?', (w['user_id'],)).fetchone()
        if u and mail_deliverable(u['email']):
            lang = user_lang(db, u['id']); base = public_site_url()
            who = s['center_id'] and db.execute('SELECT name FROM centers WHERE id=?', (s['center_id'],)).fetchone()
            ctx = {'first_name': (u['fullname'] or '').split(' ')[0], 'service': s['service_title'], 'center': (who['name'] if who else '') or '',
                   'when': when_text(s['slot_date'], s['slot_time'], lang), 'deadline': mail_deadline(db, until, lang, s['service_id'], s['center_id']), 'participants': w['participants'],
                   'book_url': f"{base}/#/reservar?{'center=' + str(s['center_id']) if s['center_id'] else 'provider=' + str(s['provider_user_id'])}&service={s['service_id']}&slot={slot_id}"}
            queue_email(db, 'waitlist_spot', u['email'], u['fullname'], ctx, lang, ('service_slot', slot_id))
        slot_event(db, slot_id, 'waitlist_notified', None, entry=w['id'], participants=w['participants'], until=local_iso(until))


def waitlist_hold_for(db, slot_id, user_id):
    w = db.execute("SELECT * FROM waitlist_entries WHERE slot_id=? AND user_id=? AND status='notified' AND held>0", (slot_id, user_id)).fetchone()
    if w and w['expires_at'] and w['expires_at'] < local_iso(local_now()): return None
    return w


def run_waitlist_jobs(db):
    now_l = local_iso(local_now())
    for w in db.execute("SELECT * FROM waitlist_entries WHERE status='notified' AND expires_at<? LIMIT 200", (now_l,)).fetchall():
        db.execute("UPDATE waitlist_entries SET status='expired',held=0,updated_at=? WHERE id=?", (now(), w['id']))
        slot_event(db, w['slot_id'], 'waitlist_expired', None, entry=w['id'])
        if w['held']: release_slot_spots(db, w['slot_id'], w['held'])   # → next person of the list
        db.commit()
    for w in db.execute("SELECT w.id, ss.slot_date, ss.slot_time, ss.service_id FROM waitlist_entries w JOIN service_slots ss ON ss.id=w.slot_id WHERE w.status='waiting' LIMIT 500").fetchall():
        st = slot_start(db, w)
        if st and st <= local_now(): db.execute("UPDATE waitlist_entries SET status='expired',updated_at=? WHERE id=?", (now(), w['id']))
    db.commit()


def waitlist_for_slots(db, user_id, slot_ids):
    out = {}
    if not user_id or not slot_ids: return out
    for chunk in [slot_ids[i:i + 500] for i in range(0, len(slot_ids), 500)]:
        for w in db.execute(f"SELECT * FROM waitlist_entries WHERE user_id=? AND status IN ('waiting','notified') AND slot_id IN ({','.join('?' * len(chunk))})", (user_id, *chunk)).fetchall():
            pos = db.execute("SELECT COUNT(*) FROM waitlist_entries WHERE slot_id=? AND status='waiting' AND (created_at<? OR (created_at=? AND id<=?))", (w['slot_id'], w['created_at'], w['created_at'], w['id'])).fetchone()[0]
            out[w['slot_id']] = {'status': w['status'], 'participants': w['participants'], 'held': w['held'] or 0, 'expires_at': server_instant(w['expires_at']), 'position': pos if w['status'] == 'waiting' else None}
    return out


def booking_token(db, bid):
    row = db.execute('SELECT public_token FROM bookings WHERE id=?', (bid,)).fetchone()
    if row and row['public_token']: return row['public_token']
    tok = wsec.random_token(); db.execute('UPDATE bookings SET public_token=? WHERE id=?', (tok, bid)); return tok


# ------------------------------------------------------------------ v50.44 · Common agenda engine (encargo unificado, bloque A)
# One engine for everybody: a *resource* (the freelance, and from v50.45 instructors and boats) is busy because of
# *blocks*. A freelance's services booked by days or half days use his own resource, so two services can never be
# booked for the same day. A centre's service booked by days has a resource of its own. Blocks are never deleted:
# they are released (history). The public calendar only says free / busy / half day / not available per day.
AGENDA_KINDS = {'booking', 'manual', 'holiday', 'unavailable'}


def service_unit(svc):
    try: u = svc['booking_unit']
    except (KeyError, IndexError, TypeError): u = None
    return u if u in wag.UNITS else 'slot'


def service_tz(db, svc):
    tz = wag.valid_tz(svc['timezone'] if 'timezone' in svc.keys() else None)
    if tz: return tz
    if svc['center_id']:
        c = db.execute('SELECT country FROM centers WHERE id=?', (svc['center_id'],)).fetchone()
        return wag.tz_for_country(c['country'] if c else None, wcfg.env('WOD_TIMEZONE', wag.DEFAULT_TZ))
    r = db.execute('SELECT up.country FROM user_profiles up WHERE up.user_id=?', (svc['provider_user_id'],)).fetchone()
    return wag.tz_for_country(r['country'] if r else None, wcfg.env('WOD_TIMEZONE', wag.DEFAULT_TZ))


def person_resource(db, user_id, create=True):
    """The freelance's own resource («yo»): every service he sells by days shares it."""
    r = db.execute("SELECT * FROM resources WHERE kind='person' AND owner_user_id=? AND user_id=? AND owner_center_id IS NULL", (user_id, user_id)).fetchone()
    if r or not create: return r
    u = db.execute('SELECT u.fullname,up.country FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id WHERE u.id=?', (user_id,)).fetchone()
    tz = wag.tz_for_country(u['country'] if u else None, wcfg.env('WOD_TIMEZONE', wag.DEFAULT_TZ))
    db.execute("INSERT INTO resources(owner_user_id,kind,user_id,name,capacity,timezone,active,created_at,updated_at) VALUES(?,'person',?,?,1,?,1,?,?)",
               (user_id, user_id, (u['fullname'] if u else '') or 'Yo', tz, now(), now()))
    return db.execute('SELECT * FROM resources WHERE id=last_insert_rowid()').fetchone()


def service_resource(db, svc, create=True):
    if not svc['center_id']: return person_resource(db, svc['provider_user_id'], create)
    r = db.execute("SELECT * FROM resources WHERE kind='service' AND service_id=?", (svc['id'],)).fetchone()
    if r or not create: return r
    db.execute("INSERT INTO resources(owner_center_id,kind,service_id,name,capacity,timezone,active,created_at,updated_at) VALUES(?,'service',?,?,1,?,1,?,?)",
               (svc['center_id'], svc['id'], svc['title'], service_tz(db, svc), now(), now()))
    return db.execute('SELECT * FROM resources WHERE id=last_insert_rowid()').fetchone()


def owner_resource(db, user):
    """The resource whose agenda the signed-in provider manages (v50.44: the freelance's own)."""
    if user['role'] == 'freelance': return person_resource(db, user['id'])
    raise PermissionError('La agenda por días es, de momento, para profesionales. Los centros la tendrán con los cursos (v50.45).')


def resource_hours(db, rid):
    days = [r['weekday'] for r in db.execute('SELECT DISTINCT weekday FROM resource_hours WHERE resource_id=? ORDER BY weekday', (rid,)).fetchall()]
    closures = [{'id': r['id'], 'from': r['date_from'], 'to': r['date_to'], 'label': r['label'] or ''}
                for r in db.execute('SELECT * FROM resource_closures WHERE resource_id=? ORDER BY date_from', (rid,)).fetchall()]
    return days or None, closures


def active_blocks(db, rid, start_utc, end_utc):
    return [dict(r) for r in db.execute("""SELECT * FROM resource_blocks WHERE resource_id=? AND status='active' AND starts_at<? AND ends_at>?
                                           ORDER BY starts_at""", (rid, end_utc, start_utc)).fetchall()]


def agenda_lock(db):
    """Serialize every write that checks for overlaps (SQLite lets one writer at a time): of two confirmations of
    the same days at the same moment, the second one sees the first and fails."""
    if not db.in_transaction: db.execute('BEGIN IMMEDIATE')


def agenda_claim(db, rid, spans, kind, ref_type, ref_id, actor=None, note=None):
    """Blocks a resource for each (start_utc, end_utc, local_from, local_to). Raises ValueError on overlap."""
    agenda_lock(db)
    for s, e, lf, lt in spans:
        clash = active_blocks(db, rid, s, e)
        clash = [c for c in clash if not (c['ref_type'] == ref_type and c['ref_id'] == ref_id)]
        if clash:
            raise ValueError('Esos días acaban de ocuparse. Elige otras fechas.' if kind == 'booking' else 'Ya hay algo en esas fechas.')
    for s, e, lf, lt in spans:
        db.execute("""INSERT INTO resource_blocks(resource_id,starts_at,ends_at,local_date_from,local_date_to,kind,ref_type,ref_id,status,private_note,created_by,created_at)
                      VALUES(?,?,?,?,?,?,?,?,'active',?,?,?)""", (rid, s, e, lf, lt, kind, ref_type, ref_id, note, actor, now()))


def agenda_release(db, ref_type, ref_id):
    db.execute("UPDATE resource_blocks SET status='released',released_at=? WHERE ref_type=? AND ref_id=? AND status='active'", (now(), ref_type, ref_id))


def booking_day_rows(db, bid):
    return [dict(r) for r in db.execute('SELECT local_date,part FROM booking_days WHERE booking_id=? ORDER BY local_date', (bid,)).fetchall()]


def booking_spans(db, b, rows=None):
    svc = db.execute('SELECT * FROM provider_services WHERE id=?', (b['service_id'],)).fetchone() if b['service_id'] else None
    rows = rows if rows is not None else booking_day_rows(db, b['id'])
    if not svc or not rows: return None, None, []
    rules = wag.clean_rules(svc['unit_rules']); tz = service_tz(db, svc); part = rows[0]['part']
    spans = []
    for a, z in wag.ranges([r['local_date'] for r in rows]):
        s, e = wag.block_span(a, z, part, rules, tz); spans.append((s, e, a, z))
    return svc, service_resource(db, svc), spans


def claim_booking_days(db, b):
    """The days of a booking by days become busy (confirmation or «Pago al reservar»). Idempotent."""
    svc, res, spans = booking_spans(db, b)
    if not spans: return False
    if db.execute("SELECT 1 FROM resource_blocks WHERE ref_type='booking' AND ref_id=? AND status='active'", (b['id'],)).fetchone(): return True
    agenda_claim(db, res['id'], spans, 'booking', 'booking', b['id'])
    return True


def reject_overlapping_requests(db, b, actor=None):
    """When days are confirmed, the other pending requests for those days are rejected with a kind notice and a
    link to the other dates of the same provider."""
    svc, res, spans = booking_spans(db, b)
    if not spans: return 0
    sids = [r['id'] for r in db.execute('SELECT id FROM provider_services WHERE active IN (0,1) AND ' + ('center_id IS NULL AND provider_user_id=?' if not svc['center_id'] else 'id=?'),
                                        (svc['provider_user_id'] if not svc['center_id'] else svc['id'],)).fetchall()]
    n = 0
    for o in db.execute(f"""SELECT * FROM bookings WHERE id<>? AND service_id IN ({','.join('?' * len(sids))}) AND status IN ('requested','pending')
                            AND EXISTS (SELECT 1 FROM booking_days d WHERE d.booking_id=bookings.id)""", (b['id'], *sids)).fetchall():
        _s2, _r2, sp2 = booking_spans(db, o)
        if any(wag.overlaps(a1, z1, a2, z2) for a1, z1, _x, _y in spans for a2, z2, _u, _v in sp2):
            reject_booking(db, actor, o, '', event='dates_taken'); n += 1
    return n


def day_booking_selection(db, svc, data, participants):
    """Validates the days chosen by the diver and prices them (single source: wag.quote)."""
    unit = service_unit(svc); rules = wag.clean_rules(svc['unit_rules']); tz = service_tz(db, svc)
    pricing = wag.clean_pricing(svc['pricing'], svc['price'])
    days = wag.normalize_selection(data.get('days'), data.get('date_from'), data.get('date_to'))
    part = data.get('part') if data.get('part') in wag.PARTS else 'full'
    res = service_resource(db, svc)
    states = public_day_states(db, svc, res, days, rules, tz, unit) if days else {}
    err = wag.check_selection(days, part, unit, rules, states)
    if err: raise ValueError(err)
    price, lines = wag.quote(pricing, days, part, participants, as_list(data.get('agenda_extras')), svc['title'])
    start_hhmm = rules['am'][0] if part in ('full', 'am') else rules['pm'][0]
    return {'days': days, 'part': part, 'tz': tz, 'rules': rules, 'price': price, 'lines': lines, 'time': rules['full'][0] if part == 'full' else start_hhmm,
            'start': wag.to_server_local(days[0], start_hhmm, tz)}


def public_day_states(db, svc, res, days, rules, tz, unit):
    if not days: return {}
    s = wag.local_to_utc(days[0], '00:00', tz); e = wag.local_to_utc(days[-1], '24:00', tz)
    blocks = active_blocks(db, res['id'], s, e)
    work, closures = resource_hours(db, res['id'])
    return wag.day_states(days, blocks, rules, tz, unit, work, closures)


def agenda_public(db, sid, month):
    """GET /api/agenda/public: one word per day. Never names, reasons, hours or references (A4.3)."""
    svc = db.execute('SELECT * FROM provider_services WHERE id=? AND active=1', (sid,)).fetchone()
    if not svc or service_unit(svc) not in wag.DAY_UNITS: raise NotFound('Servicio no encontrado.')
    tz = service_tz(db, svc); month = wag.clean_month(month, tz); rules = wag.clean_rules(svc['unit_rules'])
    res = service_resource(db, svc); db.commit()
    days = wag.month_days(month)
    states = public_day_states(db, svc, res, days, rules, tz, service_unit(svc))
    pricing = wag.clean_pricing(svc['pricing'], svc['price'])
    if svc['center_id']:
        c = db.execute('SELECT id,name,logo_url,city,country FROM centers WHERE id=?', (svc['center_id'],)).fetchone()
        prov = {'type': 'center', 'id': c['id'], 'name': c['name'], 'image': c['logo_url'] or '', 'place': ', '.join(x for x in (c['city'], c['country']) if x)}
    else:
        u = db.execute('SELECT u.id,u.fullname,u.avatar_url,up.city,up.country FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id WHERE u.id=?', (svc['provider_user_id'],)).fetchone()
        prov = {'type': 'freelance', 'id': u['id'], 'name': u['fullname'], 'image': u['avatar_url'] or '', 'place': ', '.join(x for x in (u['city'], u['country']) if x)}
    info = service_mode_info(db, svc)
    return {'service_id': sid, 'title': svc['title'], 'description': svc['description'] or '', 'service_type': svc['service_type'], 'provider': prov,
            'booking_mode': info['booking_mode'], 'mode_label': info['mode_label'], 'bookable': info['bookable'], 'instant': info['instant'],
            'unavailable_reason': info.get('unavailable_reason') or '', 'deposit_type': svc['deposit_type'], 'deposit_value': svc['deposit_value'],
            'month': month, 'timezone': tz, 'today': wag.today_in(tz).isoformat(), 'unit': service_unit(svc), 'days': states,
            'rules': {k: rules[k] for k in ('min_days', 'max_days', 'continuous', 'lead_hours', 'am', 'pm', 'full')}, 'pricing': pricing,
            'currency': svc['currency'] or 'EUR', 'max_participants': svc['max_participants']}


def agenda_mine(db, user, month):
    """The provider's own agenda (A2.2): blocks with what is behind each one, pending requests and usual hours."""
    res = owner_resource(db, user); db.commit()
    tz = wag.valid_tz(res['timezone']) or wag.DEFAULT_TZ; month = wag.clean_month(month, tz); days = wag.month_days(month)
    s = wag.local_to_utc(days[0], '00:00', tz); e = wag.local_to_utc(days[-1], '24:00', tz)
    items = []
    for bl in active_blocks(db, res['id'], s, e):
        it = {'id': bl['id'], 'kind': bl['kind'], 'from': bl['local_date_from'], 'to': bl['local_date_to'],
              'start': wag.utc_to_local(bl['starts_at'], tz).strftime('%H:%M'), 'end': wag.utc_to_local(bl['ends_at'], tz).strftime('%H:%M'), 'note': bl['private_note'] or ''}
        if bl['ref_type'] == 'booking':
            b = db.execute("""SELECT b.id,b.participants,b.status,b.payment_status,b.price,b.currency,b.notes,COALESCE(b.contact_name,u.fullname) AS client,s.title AS service
                              FROM bookings b JOIN users u ON u.id=b.user_id LEFT JOIN provider_services s ON s.id=b.service_id WHERE b.id=?""", (bl['ref_id'],)).fetchone()
            if b: it['booking'] = dict(b)
        items.append(it)
    reqs = []
    sids = [r['id'] for r in db.execute('SELECT id FROM provider_services WHERE provider_user_id=? AND center_id IS NULL', (user['id'],)).fetchall()] or [0]
    for b in db.execute(f"""SELECT b.id,b.participants,b.status,b.response_deadline,b.price,b.currency,b.notes,COALESCE(b.contact_name,u.fullname) AS client,s.title AS service,
                                   (SELECT MIN(local_date) FROM booking_days d WHERE d.booking_id=b.id) AS d_from,(SELECT MAX(local_date) FROM booking_days d WHERE d.booking_id=b.id) AS d_to,
                                   (SELECT part FROM booking_days d WHERE d.booking_id=b.id LIMIT 1) AS part
                            FROM bookings b JOIN users u ON u.id=b.user_id LEFT JOIN provider_services s ON s.id=b.service_id
                            WHERE b.service_id IN ({','.join('?' * len(sids))}) AND b.status IN ('requested','pending') AND EXISTS (SELECT 1 FROM booking_days d WHERE d.booking_id=b.id)
                            ORDER BY d_from""", sids).fetchall():
        if b['d_to'] >= days[0] and b['d_from'] <= days[-1]: reqs.append(dict(b))
    work, closures = resource_hours(db, res['id'])
    return {'resource': {'id': res['id'], 'name': res['name'], 'timezone': tz}, 'month': month, 'today': wag.today_in(tz).isoformat(),
            'blocks': items, 'requests': reqs, 'weekdays': work if work is not None else list(range(7)), 'closures': closures}


def agenda_block_days(db, user, data):
    res = owner_resource(db, user); tz = wag.valid_tz(res['timezone']) or wag.DEFAULT_TZ
    days = wag.normalize_selection(None, data.get('date_from'), data.get('date_to'))
    if not days: raise ValueError('Elige los días que quieres bloquear.')
    part = data.get('part') if data.get('part') in wag.PARTS else 'full'
    kind = data.get('kind') if data.get('kind') in ('manual', 'holiday') else 'manual'
    rules = wag.DEFAULT_RULES
    s1 = db.execute("SELECT unit_rules FROM provider_services WHERE provider_user_id=? AND center_id IS NULL AND booking_unit='half_day' AND active=1 LIMIT 1", (user['id'],)).fetchone()
    if s1: rules = wag.clean_rules(s1['unit_rules'])
    spans = []
    for a, z in wag.ranges(days):
        s, e = wag.block_span(a, z, part, rules, tz); spans.append((s, e, a, z))
    ref = secrets.randbelow(2**31)
    agenda_claim(db, res['id'], spans, kind, 'manual', ref, user['id'], clean_text(data.get('note'), 200))
    audit(db, user['id'], 'agenda_blocked', 'resource', res['id'], {'from': days[0], 'to': days[-1], 'part': part, 'kind': kind})
    return {'ok': True, 'days': len(days)}


def agenda_unblock(db, user, data):
    res = owner_resource(db, user); bid = int(data.get('id') or 0)
    bl = db.execute("SELECT * FROM resource_blocks WHERE id=? AND resource_id=? AND status='active'", (bid, res['id'])).fetchone()
    if not bl: raise NotFound('Bloqueo no encontrado.')
    if bl['ref_type'] == 'booking': raise ValueError('Ese día está ocupado por una reserva: cancélala o cámbiale la fecha desde la reserva.')
    db.execute("UPDATE resource_blocks SET status='released',released_at=? WHERE id=?", (now(), bid))
    audit(db, user['id'], 'agenda_unblocked', 'resource', res['id'], {'block': bid})
    return {'ok': True}


def agenda_save_hours(db, user, data):
    res = owner_resource(db, user)
    wds = sorted({int(x) for x in (data.get('weekdays') or []) if str(x).isdigit() and 0 <= int(x) <= 6})
    if not wds: raise ValueError('Marca al menos un día de trabajo.')
    tz = wag.valid_tz(data.get('timezone')) or res['timezone']
    db.execute('DELETE FROM resource_hours WHERE resource_id=?', (res['id'],))   # the usual week is replaced as a whole (it is a setting, not data)
    db.executemany("INSERT INTO resource_hours(resource_id,weekday,start_time,end_time) VALUES(?,?,'00:00','24:00')", [(res['id'], d) for d in wds])
    closures = []
    for c in (data.get('closures') or [])[:20]:
        a = wag.normalize_selection(None, (c or {}).get('from'), (c or {}).get('to'))
        if a: closures.append((a[0], a[-1], clean_text((c or {}).get('label'), 80)))
    db.execute('DELETE FROM resource_closures WHERE resource_id=?', (res['id'],))
    db.executemany('INSERT INTO resource_closures(resource_id,date_from,date_to,label) VALUES(?,?,?,?)', [(res['id'], *x) for x in closures])
    db.execute('UPDATE resources SET timezone=?,updated_at=? WHERE id=?', (tz, now(), res['id']))
    audit(db, user['id'], 'agenda_hours', 'resource', res['id'], {'weekdays': wds, 'closures': len(closures), 'timezone': tz})
    return {'ok': True}


def save_service_agenda_options(db, user, sid, data):
    """Service form: booking unit (por salida · por días · por días o medias jornadas), rules, prices and time zone."""
    if 'booking_unit' not in data: return
    unit = data.get('booking_unit') if data.get('booking_unit') in wag.UNITS else 'slot'
    if unit in wag.DAY_UNITS:
        ref = provider_ref(db, user)
        if user['role'] != 'admin' and (not ref or not provider_has(db, ref[0], ref[1], 'agenda_days')): raise PlanRequired('agenda_days')
    svc = db.execute('SELECT * FROM provider_services WHERE id=?', (sid,)).fetchone()
    rules = wag.clean_rules(data.get('unit_rules') or {}); pricing = wag.clean_pricing(data.get('pricing') or {}, svc['price'])
    tz = wag.valid_tz(data.get('timezone')) or svc['timezone']
    db.execute('UPDATE provider_services SET booking_unit=?,unit_rules=?,pricing=?,timezone=?,updated_at=? WHERE id=?',
               (unit, json.dumps(rules), json.dumps(pricing, ensure_ascii=False), tz, now(), sid))
    if unit in wag.DAY_UNITS:
        db.execute('UPDATE provider_services SET price=? WHERE id=?', (pricing['day'], sid))   # «desde» in listings
        res = service_resource(db, db.execute('SELECT * FROM provider_services WHERE id=?', (sid,)).fetchone())
        if wag.valid_tz(data.get('timezone')) and res['timezone'] != data.get('timezone'):
            db.execute('UPDATE resources SET timezone=?,updated_at=? WHERE id=?', (data.get('timezone'), now(), res['id']))   # the place where he works


def agenda_quote(db, data):
    sid = int(data.get('service_id') or 0)
    svc = db.execute('SELECT * FROM provider_services WHERE id=? AND active=1', (sid,)).fetchone()
    if not svc or service_unit(svc) not in wag.DAY_UNITS: raise NotFound('Servicio no encontrado.')
    pax = max(1, int(data.get('participants') or 1))
    if svc['max_participants'] and pax > int(svc['max_participants']): raise ValueError(f'Este servicio admite como máximo {svc["max_participants"]} personas.')
    sel = day_booking_selection(db, svc, data, pax); db.commit()
    deposit = deposit_for(svc, sel['price'], pax)
    return {'ok': True, 'days': sel['days'], 'part': sel['part'], 'total': sel['price'], 'lines': sel['lines'], 'deposit': deposit, 'currency': svc['currency'] or 'EUR'}


# ------------------------------------------------------------------ v50.42 · Encargo 2, punto 6: check-in without coverage
# The staff app keeps the manifest of the day on the device (only the departures of that day, never documents) to
# check divers in, mark «no se presentó» and write notes without connection; back online, the changes are sent and
# compared field by field with what the server has (three-way): a change made meanwhile by someone else is a conflict.
DAY_FIELDS = ('booking_id', 'seat', 'participants', 'status', 'group_id', 'name', 'companion_of', 'level_name', 'nitrox', 'rental', 'sizes', 'emergency', 'phone', 'signed')


def entry_state(e):
    return {'status': 'present' if e['checked_in_at'] else ('no_show' if e['no_show'] else ''), 'note': e['note'] or ''}


def manifest_day(db, user, day):
    kind, oid = provider_owner(user)
    w, a = owner_where(kind, oid, 's')
    slots = db.execute(f"""SELECT ss.id FROM service_slots ss JOIN provider_services s ON s.id=ss.service_id
                           WHERE {w} AND ss.slot_date=? AND ss.cancelled_at IS NULL AND ss.status IN ('open','full','closed') ORDER BY ss.slot_time""", (*a, day)).fetchall()
    out = []
    for r in slots:
        if not slot_visible(db, user, r['id']): continue
        d = manifest_data(db, user, r['id'])
        if not d['divers']: continue
        divers = []
        for x in d['divers']:
            row = {k: x.get(k) for k in DAY_FIELDS}; row['booking_status'] = row.pop('status')
            e = db.execute('SELECT checked_in_at,no_show,note FROM manifest_entries WHERE booking_id=? AND seat=?', (x['booking_id'], x['seat'])).fetchone()
            row.update(entry_state(e)); divers.append(row)
        out.append({'slot': d['slot'], 'points': d['points'], 'groups': [{k: g[k] for k in ('id', 'label', 'guide', 'boat_id')} for g in d['groups']],
                    'boats': [{k: b[k] for k in ('id', 'name')} for b in d['boats']], 'waiver': bool(d['waiver']), 'divers': divers})
    return out


def manifest_sync(db, user, changes):
    """changes: [{slot_id, booking_id, seat, field ('status'|'note'), base, value, at, force}] → applied and conflicts."""
    applied, conflicts, seen = 0, [], {}
    for c in changes[:500]:
        if not isinstance(c, dict): continue
        slot_id = int(c.get('slot_id') or 0); bid = int(c.get('booking_id') or 0); seat = int(c.get('seat') or 1); field = c.get('field')
        if field not in ('status', 'note'): raise ValueError('Cambio no válido.')
        if slot_id not in seen: seen[slot_id] = manifest_slot(db, user, slot_id)
        e = db.execute('SELECT * FROM manifest_entries WHERE booking_id=? AND seat=? AND slot_id=?', (bid, seat, slot_id)).fetchone()
        if not e: conflicts.append({**c, 'reason': 'gone'}); continue
        cur = entry_state(e)[field]
        value = str(c.get('value') or '')[:500] if field == 'note' else (c.get('value') or '')
        if field == 'status' and value not in ('present', 'no_show', ''): raise ValueError('Cambio no válido.')
        base = str(c.get('base') or '')
        if cur != base and cur != value and not c.get('force'):
            who = db.execute('SELECT fullname FROM users WHERE id=?', (e['checkin_by'] if field == 'status' else e['updated_by'],)).fetchone() if (e['checkin_by'] if field == 'status' else e['updated_by']) else None
            conflicts.append({**c, 'server_value': cur, 'server_by': who['fullname'] if who else None, 'server_at': e['checkin_updated_at'] if field == 'status' else e['note_updated_at']}); continue
        at = clean_text(c.get('at'), 40) or now()
        if field == 'status':
            db.execute('UPDATE manifest_entries SET checked_in_at=?,no_show=?,checkin_by=?,checkin_source=?,checkin_updated_at=?,updated_at=?,updated_by=? WHERE booking_id=? AND seat=?',
                       (at if value == 'present' else None, 1 if value == 'no_show' else 0, user['id'], 'offline' if c.get('offline') else 'online', now(), now(), user['id'], bid, seat))
        else:
            db.execute('UPDATE manifest_entries SET note=?,note_updated_at=?,updated_at=?,updated_by=? WHERE booking_id=? AND seat=?', (value or None, now(), now(), user['id'], bid, seat))
        applied += 1
    for sid in seen:
        if applied: slot_event(db, sid, 'checkin_synced', user['id'], applied=applied, conflicts=len(conflicts))
    return applied, conflicts


# =================================================================== v50.49 · the professional app (Centro PRO / Freelance PRO)
PRO_URGENT_MINUTES = 180      # requests and payments that expire within 3 hours go to the top of «Hoy»
PRO_AGENDA_MAX_DAYS = 42


def pro_slots(db, user, day):
    """The departures of one day, with what the staff needs at a glance: spots, people, who arrived, unsigned forms and
    guides. Without «todas_salidas» a person sees the departures where they guide a group and those without guides."""
    kind, oid = provider_owner(user)
    w, a = owner_where(kind, oid, 's')
    st = ','.join('?' * len(MANIFEST_STATES))
    see_all = user_can(db, user, 'todas_salidas')
    waiver = current_waiver(db, kind, oid)
    key = winq.tenant_key(kind, oid)
    out = []
    for r in db.execute(f"""SELECT ss.id, ss.slot_date, ss.slot_time, ss.spots_total, ss.spots_available, ss.status, ss.cancelled_at, ss.meeting_point,
                                   s.id AS service_id, s.title AS service_title, s.color AS service_color, s.service_type, s.duration_minutes
                              FROM service_slots ss JOIN provider_services s ON s.id=ss.service_id
                             WHERE {w} AND ss.slot_date=? ORDER BY ss.slot_time, ss.id""", (*a, day)).fetchall():
        bk = db.execute(f"""SELECT COALESCE(SUM(CASE WHEN status IN ('confirmed','completed') THEN participants ELSE 0 END),0) AS ok,
                                   COALESCE(SUM(CASE WHEN status='accepted_pending_payment' THEN participants ELSE 0 END),0) AS pay,
                                   COALESCE(SUM(CASE WHEN status='requested' THEN participants ELSE 0 END),0) AS req, COUNT(*) AS n
                              FROM bookings WHERE slot_id=? AND provider_id=? AND status IN ({st})""", (r['id'], key, *MANIFEST_STATES)).fetchone()
        me = db.execute(f"""SELECT COALESCE(SUM(CASE WHEN m.checked_in_at IS NOT NULL THEN 1 ELSE 0 END),0) AS present, COALESCE(SUM(m.no_show),0) AS no_show
                              FROM manifest_entries m JOIN bookings b ON b.id=m.booking_id WHERE m.slot_id=? AND b.provider_id=? AND b.status IN ({st})""",
                        (r['id'], key, *MANIFEST_STATES)).fetchone()
        groups = db.execute('''SELECT g.label, g.guide_user_id, COALESCE(u.fullname, g.guide_name) AS guide FROM slot_groups g JOIN service_slots x ON x.id=g.slot_id AND x.provider_id=?
                               LEFT JOIN users u ON u.id=g.guide_user_id WHERE g.slot_id=? ORDER BY g.sort, g.id''', (key, r['id'])).fetchall()
        mine = any(g['guide_user_id'] == user['id'] for g in groups)
        if not see_all and any(g['guide'] for g in groups) and not mine: continue
        unsigned = 0
        if waiver:
            people = int(bk['ok'] or 0)
            signed = db.execute("SELECT COUNT(*) FROM waiver_signatures ws JOIN bookings bb ON bb.id=ws.booking_id WHERE bb.slot_id=? AND bb.provider_id=? AND bb.status IN ('confirmed','completed')", (r['id'], key)).fetchone()[0]
            unsigned = people - int(signed or 0)
        out.append({'slot_id': r['id'], 'date': r['slot_date'], 'time': r['slot_time'], 'service_id': r['service_id'], 'service': r['service_title'],
                    'color': r['service_color'], 'type': r['service_type'], 'duration': r['duration_minutes'], 'meeting_point': r['meeting_point'],
                    'status': 'cancelled' if r['cancelled_at'] else r['status'], 'spots_total': int(r['spots_total'] or 0),
                    'spots_available': int(r['spots_available'] or 0), 'confirmed': int(bk['ok']), 'pending_payment': int(bk['pay']), 'requested': int(bk['req']),
                    'present': int(me['present']), 'no_show': int(me['no_show']), 'unsigned': max(0, int(unsigned)), 'mine': mine,
                    'guides': [g['guide'] for g in groups if g['guide']]})
    return out


def pro_today(db, user):
    """«Hoy» of the professional app: four numbers, what is urgent, today's departures and tomorrow's (folded)."""
    tz = provider_tz(db, user); here = place_now(tz)   # the centre's «today», wherever the server is
    today = here.date(); tomorrow = today + _timedelta(days=1)
    sal = pro_slots(db, user, today.isoformat()); man = pro_slots(db, user, tomorrow.isoformat())
    res = {'date': today.isoformat(), 'tomorrow': tomorrow.isoformat(), 'now': here.isoformat(timespec='minutes'), 'tz': tz,
           'slots': sal, 'tomorrow_slots': man, 'urgent': [], 'requests': None, 'awaiting_payment': None,
           'counts': {'slots': len([x for x in sal if x['status'] != 'cancelled']), 'divers': sum(x['confirmed'] + x['pending_payment'] for x in sal),
                      'present': sum(x['present'] for x in sal)}}
    if user['role'] == 'freelance':
        # Work booked by days or half days (no departure): today's and tomorrow's, with the client.
        jobs = []
        for b in db.execute('''SELECT b.id,b.status,b.participants,b.payment_status,b.price,b.currency,b.notes,b.dive_point_id,COALESCE(b.contact_name,u.fullname) AS client,
                                      s.title AS service,d.local_date,d.part,p.name AS point_name,p.latitude,p.longitude
                                 FROM booking_days d JOIN bookings b ON b.id=d.booking_id JOIN users u ON u.id=b.user_id LEFT JOIN provider_services s ON s.id=b.service_id
                                 LEFT JOIN dive_points p ON p.id=b.dive_point_id
                                WHERE b.center_id IS NULL AND b.provider_user_id=? AND d.local_date IN (?,?) AND b.status IN ('accepted_pending_payment','confirmed','completed')
                                ORDER BY d.local_date,b.id''', (user['id'], today.isoformat(), tomorrow.isoformat())).fetchall():
            jobs.append(dict(b))
        res['jobs'] = jobs
    if user_can(db, user, 'reservas'):
        scope, sargs = provider_scope_sql(user)
        now_l = local_now(); urgent = []
        q = f"""SELECT b.id,b.status,b.booking_date,b.booking_time,b.participants,b.response_deadline,b.payment_deadline,
                       COALESCE(b.contact_name,u.fullname) AS name,s.title AS service
                  FROM bookings b JOIN users u ON u.id=b.user_id LEFT JOIN provider_services s ON s.id=b.service_id
                 WHERE {scope} AND b.status IN ('requested','pending','accepted_pending_payment')"""
        for b in db.execute(q, sargs).fetchall():
            dl = parse_local(b['payment_deadline'] if b['status'] == 'accepted_pending_payment' else b['response_deadline'])
            left = int((dl - now_l).total_seconds() // 60) if dl else None
            if left is not None and left <= PRO_URGENT_MINUTES:
                urgent.append({'booking_id': b['id'], 'kind': 'pago' if b['status'] == 'accepted_pending_payment' else 'solicitud', 'name': b['name'],
                               'service': b['service'], 'date': b['booking_date'], 'time': b['booking_time'], 'participants': b['participants'], 'minutes_left': max(0, left)})
        res['urgent'] = sorted(urgent, key=lambda x: x['minutes_left'])[:8]
        res['requests'] = db.execute(f"SELECT COUNT(*) FROM bookings b WHERE {scope} AND b.status IN ('requested','pending')", sargs).fetchone()[0]
        res['awaiting_payment'] = db.execute(f"SELECT COUNT(*) FROM bookings b WHERE {scope} AND b.status='accepted_pending_payment'", sargs).fetchone()[0]
    return res


def pro_agenda(db, user, start, days):
    """Departures of several days (week and month views of the app), one entry per day."""
    try: d0 = _dt.date.fromisoformat(str(start)[:10])
    except ValueError: d0 = place_now(provider_tz(db, user)).date()
    days = max(1, min(PRO_AGENDA_MAX_DAYS, int(days or 7)))
    out = []
    for i in range(days):
        d = (d0 + _timedelta(days=i)).isoformat(); sl = pro_slots(db, user, d)
        live = [x for x in sl if x['status'] != 'cancelled']
        cap = sum(x['spots_total'] for x in live); people = sum(x['confirmed'] + x['pending_payment'] for x in live)
        out.append({'date': d, 'slots': sl, 'people': people, 'capacity': cap, 'occupancy': round(people / cap, 2) if cap else 0})
    return {'from': d0.isoformat(), 'days': out, 'today': place_now(provider_tz(db, user)).date().isoformat()}


SCAN_TEXT = {
    'ok': 'Llegada marcada.', 'usado': 'Esta reserva ya estaba marcada como llegada.', 'otra_salida': 'Esta reserva es de otra salida.',
    'otro_dia': 'Esta reserva es de otro día.', 'otro_centro': 'Esta reserva no es de tu centro.', 'anulada': 'Esta reserva está cancelada.',
    'sin_aceptar': 'Esta reserva es una solicitud que todavía no has aceptado.', 'pendiente_pago': 'Esta reserva está aceptada pero falta el pago.',
    'no_valido': 'Este código no es de una reserva de WORLDIVES o está mal escrito.', 'sin_lista': 'Reserva correcta. Esta actividad no tiene lista de barco.',
}


def pro_scan(db, user, data):
    """The staff scans the QR of a booking (or types its code). Only bookings of the session's centre are described;
    the check-in is written exactly as the boat list does (manifest_entries)."""
    parsed = wpro.parse_code(data.get('code'))
    if not parsed: return {'result': 'no_valido', 'message': SCAN_TEXT['no_valido']}
    bid, tok, how = parsed
    b = db.execute('SELECT * FROM bookings WHERE id=?', (bid,)).fetchone()
    if not b or not wpro.token_matches(b['public_token'], tok, how): return {'result': 'no_valido', 'message': SCAN_TEXT['no_valido']}
    if not can_manage_booking(user, b):
        audit(db, user['id'], 'scan_other_tenant', 'booking', None, {'how': how})
        return {'result': 'otro_centro', 'message': SCAN_TEXT['otro_centro']}
    u = db.execute('SELECT fullname FROM users WHERE id=?', (b['user_id'],)).fetchone()
    svc = db.execute('SELECT title FROM provider_services WHERE id=?', (b['service_id'],)).fetchone() if b['service_id'] else None
    paid_, refunded_, _o = booking_paid_online(db, b['id'])
    card = {'booking_id': b['id'], 'code': wpro.booking_code(b['id'], b['public_token']), 'name': b['contact_name'] or (u['fullname'] if u else ''),
            'participants': int(b['participants'] or 1), 'service': svc['title'] if svc else None, 'date': b['booking_date'], 'date_to': b['date_to'],
            'time': b['booking_time'], 'status': b['status'], 'payment_status': b['payment_status'], 'slot_id': b['slot_id'],
            'paid': round(paid_ - refunded_, 2), 'amount_due': b['amount_due'], 'currency': b['currency'] or 'EUR', 'seats': [], 'unsigned': 0}
    def res(kind, **extra): return {'result': kind, 'message': SCAN_TEXT[kind], 'booking': card, **extra}
    if b['status'] in ('cancelled', 'rejected', 'expired'): return res('anulada')
    if b['status'] in ('requested', 'pending'): return res('sin_aceptar')
    today = place_now(place_tz(db, b['service_id'], b['center_id'])).date().isoformat()   # the day where the dive is
    if not (b['booking_date'] <= today <= (b['date_to'] or b['booking_date'])): return res('otro_dia')
    want = int(data.get('slot_id') or 0)
    if want and b['slot_id'] and want != int(b['slot_id']): return res('otra_salida')
    if not b['slot_id']: return res('sin_lista' if b['status'] != 'accepted_pending_payment' else 'pendiente_pago')
    d = manifest_data(db, user, int(b['slot_id']), for_reading=False)
    seats = [x for x in d['divers'] if x['booking_id'] == b['id']]
    card['seats'] = [{'seat': x['seat'], 'name': x['name'], 'present': bool(x['checked_in_at']), 'signed': bool(x['signed'])} for x in seats]
    card['unsigned'] = sum(1 for x in seats if not x['signed']) if d['waiver'] else 0
    if seats and all(x['checked_in_at'] for x in seats): return res('usado')
    if b['status'] == 'accepted_pending_payment' and not data.get('force'): return res('pendiente_pago')
    if data.get('mark') is False: return res('ok', marked=False)
    changes = [{'slot_id': b['slot_id'], 'booking_id': b['id'], 'seat': x['seat'], 'field': 'status', 'base': '', 'value': 'present', 'force': True}
               for x in seats if not x['checked_in_at']]
    manifest_sync(db, user, changes)
    slot_event(db, b['slot_id'], 'qr_checkin', user['id'], booking_id=b['id'], seats=len(changes), how=how)
    for x in card['seats']: x['present'] = True
    return res('ok', marked=True)


def pro_headcount(db, user, slot_id, count):
    """«Contar a bordo»: the number counted on the boat against the people marked as arrived. It is kept in the
    history of the departure."""
    slot = manifest_slot(db, user, slot_id)
    st = ','.join('?' * len(MANIFEST_STATES))
    present = db.execute(f"""SELECT COUNT(*) FROM manifest_entries m JOIN bookings b ON b.id=m.booking_id WHERE m.slot_id=? AND m.checked_in_at IS NOT NULL
                             AND b.provider_id=? AND b.status IN ({st})""", (slot['id'], winq.tenant_key(*slot_owner(slot)), *MANIFEST_STATES)).fetchone()[0]
    count = max(0, min(999, int(count or 0)))
    slot_event(db, slot['id'], 'headcount', user['id'], counted=count, present=present)
    return {'counted': count, 'present': present, 'match': count == present, 'diff': count - present, 'at': now()}


def booking_whatsapp(db, user, bid, kind, base):
    """A wa.me link with the text in the client's language, opened from the professional's own phone (no message
    leaves WORLDIVES). Only for the centre of the booking and when the client's phone is visible to it."""
    b = db.execute('SELECT * FROM bookings WHERE id=?', (bid,)).fetchone()
    if not b or not can_manage_booking(user, b): raise NotFound('Reserva no encontrada.')
    visible = provider_can_see_user(db, b) or is_guest_user(db, b['user_id'], b['center_id'] or -1)
    prof = db.execute('SELECT phone FROM user_profiles WHERE user_id=?', (b['user_id'],)).fetchone()
    phone = (b['contact_phone'] or (prof['phone'] if prof else None)) if visible else None
    e164 = wcif.normalize_phone(phone) if phone else None
    lang = user_lang(db, b['user_id'])
    u = db.execute('SELECT fullname FROM users WHERE id=?', (b['user_id'],)).fetchone()
    name = str(b['contact_name'] or (u['fullname'] if u else '') or '').split(' ')[0]
    svc = db.execute('SELECT title FROM provider_services WHERE id=?', (b['service_id'],)).fetchone() if b['service_id'] else None
    owner = ('center', b['center_id']) if b['center_id'] else ('freelance', b['provider_user_id'])
    text = wpro.wa_text('pago' if kind == 'pago' else 'reserva', lang, name=name, center=provider_label(db, *owner), service=svc['title'] if svc else '',
                        date=mail_date(b['booking_date'], lang), time=b['booking_time'], link=f"{base}/#/reserva?id={b['id']}")
    if e164: log_phone_access(db, user, 'whatsapp_link', 1, bid)
    return {'lang': lang, 'text': text, 'phone_ok': bool(e164), 'url': wpro.wa_url(e164, text) if e164 else None, 'tel': f'tel:{e164}' if e164 else None,
            'reason': None if e164 else ('El cliente no ha compartido su teléfono con tu centro.' if not visible else 'Esta reserva no tiene un teléfono válido.')}


def manifest_pdf(db, user, slot_id, lang='es'):
    """«Resumen para el barco»: the list of a departure, with a SHA-256 fingerprint of its content and who generated it,
    so a printed copy can be checked against the server."""
    d = manifest_data(db, user, slot_id); s = d['slot']
    kind, oid = slot_owner(manifest_slot(db, user, slot_id))
    T = lambda x: mail_t(lang, x)
    gname = {g['id']: (g['label'] + (f" · {g['guide']}" if g.get('guide') else '')) for g in d['groups']}
    rows = [(gname.get(x['group_id'], T('Sin grupo')), x['name'] or '—', x.get('level_name') or '', 'Nx' if x.get('nitrox') else '',
             ', '.join(x.get('rental') or []), (T('Sí') if x.get('signed') else T('No')) if d['waiver'] else '',
             T('Sí') if x.get('checked_in_at') else (T('No vino') if x.get('no_show') else ''))
            for x in d['divers']]
    import hashlib as _h
    payload = json.dumps({'slot': s['id'], 'date': s['slot_date'], 'time': s['slot_time'], 'rows': rows}, ensure_ascii=False, sort_keys=True)
    digest = _h.sha256(payload.encode('utf-8')).hexdigest()
    doc = wpdf.Document(T('Resumen para el barco'), lang)
    ink, muted = (0.04, 0.17, 0.24), (0.38, 0.43, 0.46)
    doc.box(24, 748, 547, 70, BRAND_PDF['abismo'], None, 16); pdf_brand_icon(doc, 40, 756, 54)
    doc.text(104, 790, 'WORLDIVES DISCOVERY', 21, (1, 1, 1)); doc.text(104, 773, T('Resumen para el barco').upper(), 8, BRAND_PDF['agua'])
    meta = [(T('Centro'), provider_label(db, kind, oid)), (T('Actividad'), s['service_title'] or '—'), (T('Fecha'), when_text(s['slot_date'], s['slot_time'], lang)),
            (T('Buceadores'), str(len(d['divers']))), (T('Llegados'), str(sum(1 for x in d['divers'] if x.get('checked_in_at')))),
            (T('Puntos'), ', '.join(p['name'] for p in d['points']) or '—')]
    for i, (lab, val) in enumerate(meta):
        x = 46 + (i % 3) * 170; y = 722 - (i // 3) * 30
        doc.text(x, y, lab.upper(), 7, muted); doc.text(x, y - 13, doc.fit(str(val), 9, 160), 9, ink)
    cols = [(46, T('Grupo'), 110), (160, T('Buceador'), 130), (294, T('Nivel'), 80), (378, 'Nx', 18), (400, T('Alquiler'), 96), (500, T('Firma'), 30), (532, T('Llegó'), 40)]
    y = [650]
    def head():
        for x, lab, _w in cols: doc.text(x, y[0], lab.upper(), 7, muted)
        y[0] -= 16
    head()
    for r in rows:
        if y[0] < 90:
            doc.new_page(); y[0] = 790; head()
        for (x, _lab, wdt), val in zip(cols, r): doc.text(x, y[0], doc.fit(str(val), 8.5, wdt), 8.5, ink)
        y[0] -= 14
    by = db.execute('SELECT fullname FROM users WHERE id=?', (user['id'],)).fetchone()
    doc.text(46, 60, doc.fit(T('Generado el {at} por {who}').replace('{at}', now()[:16].replace('T', ' ') + ' UTC').replace('{who}', by['fullname'] if by else ''), 7, 500), 7, muted)
    doc.text(46, 48, f'SHA-256 {digest}', 6.5, muted)
    slot_event(db, s['id'], 'boat_summary', user['id'], sha256=digest)
    return doc.pdf(), digest


BOAT_PDF_LINK_SECONDS = 600


def boat_pdf_token(slot_id, user_id, at=None):
    """A link to the boat summary that works for 10 minutes without the session (the app opens PDFs in the phone's
    browser, which does not share the app's cookie). It names the person: the server checks again that they still
    work for that centre."""
    exp = int((at or time.time()) + BOAT_PDF_LINK_SECONDS)
    payload = f'{int(slot_id)}.{int(user_id)}.{exp}'
    sig = hmac.new(wsec.secret_key(), ('boat-pdf:' + payload).encode(), hashlib.sha256).hexdigest()[:32]
    return f'{payload}.{sig}'


def boat_pdf_user(db, slot_id, token):
    try: sid, uid, exp, sig = str(token or '').split('.')
    except ValueError: return None
    good = hmac.new(wsec.secret_key(), f'boat-pdf:{sid}.{uid}.{exp}'.encode(), hashlib.sha256).hexdigest()[:32]
    if not hmac.compare_digest(good, sig) or int(sid) != int(slot_id) or int(exp) < time.time(): return None
    u = db.execute('SELECT * FROM users WHERE id=?', (int(uid),)).fetchone()
    return dict(u) if u and u['role'] in ('center', 'freelance') else None


from wod import ops as wops

CSP_HEADER = wsec.content_security_policy()
ACCESS_LOG = wops.access_logger(LOG_DIR)


def _alert_errors(events):
    """Repeated 500 errors: one email to the administrators (at most once an hour)."""
    db = connect()
    try:
        notify_admins(db, 'admin_error_alert', {'count': len(events), 'errors': '\n'.join(e[1] for e in events[-10:]), 'site': public_site_url()}, ('system', 0))
        db.commit()
    finally:
        db.close()


ERROR_MONITOR = wops.ErrorMonitor(_alert_errors)


class Handler(BaseHTTPRequestHandler):
    server_version = 'WORLDIVES'
    sys_version = ''

    def version_string(self):
        return self.server_version
    # A connection that stops sending data is dropped after 30 s instead of holding a worker forever.
    timeout = int(os.environ.get('WOD_SOCKET_TIMEOUT', '30'))

    def log_message(self, fmt, *args):
        # The query string never reaches the logs (it may carry coordinates or searches); the IP is truncated
        # unless WOD_LOG_IP=full, and the access log rotates daily (wod.ops.access_logger, WOD_LOG_RETENTION_DAYS).
        try:
            line = fmt % args
            if '?' in line: line = re.sub(r'\?[^\s"]*', '', line)
            line = re.sub(r'(/ical/)[^/\s"]+(\.ics)', r'\1***\2', line)
            line = re.sub(r'(/(?:api/)?r/)[^/\s"]+', r'\1***', line)
            ACCESS_LOG.info('%s - %s', wsec.log_ip(self.client_ip()), log_safe(line))
        except Exception:
            pass

    def client_ip(self):
        """The visitor's IP. Behind nginx/Caddy it comes from X-Forwarded-For, but only when the TCP peer is one of
        WOD_TRUSTED_PROXIES; otherwise anybody could forge it."""
        ip = getattr(self, '_client_ip', None)
        if ip is None:
            ip = self._client_ip = wsec.client_ip(self.client_address[0], self.headers)
        return ip

    def base_url(self):
        """Absolute base URL for links in QR codes and PDFs: WOD_PUBLIC_URL; Host header only in development."""
        if wcfg.public_url(): return wcfg.public_url()
        host = re.sub(r'[^A-Za-z0-9.:\[\]-]', '', self.headers.get('Host') or f'localhost:{PORT}')
        return f"{wsec.request_scheme(self.client_address[0], self.headers)}://{host}"

    def send_response(self, code, message=None):
        super().send_response(code, message)
        self._sec_sent = False

    def serve_widget(self, db, path, query):
        """Booking widget (Fase 6.5): a small page any website can embed in an iframe. It lists the provider's activities
        and next departures; every button opens the booking on WORLDIVES in a new tab (no payment inside the iframe)."""
        parts = path.strip('/').split('/')
        if len(parts) != 3 or parts[1] not in ('center', 'pro') or not parts[2].isdigit(): self.send_error(404); return
        ptype = 'center' if parts[1] == 'center' else 'freelance'; pid = int(parts[2])
        lang = normalize_lang(query.get('lang', ['es'])[0]); t = lambda x: mail_t(lang, x)
        if ptype == 'center':
            p = db.execute(f'SELECT id,name,city,country FROM centers c WHERE c.id=? AND {public_center_sql()}', (pid,)).fetchone()
            name = p['name'] if p else ''; sq = 's.center_id=?'; book = lambda sid: f'{public_site_url()}/#/reservar?center={pid}&service={sid}'
        else:
            p = db.execute("SELECT id,fullname FROM users WHERE id=? AND role='freelance'", (pid,)).fetchone()
            name = p['fullname'] if p else ''; sq = 's.provider_user_id=? AND s.center_id IS NULL'; book = lambda sid: f'{public_site_url()}/#/reservar?provider={pid}&service={sid}'
        if not p: self.send_error(404); return
        e = html.escape
        if provider_has(db, ptype, pid, 'widget') and provider_has(db, ptype, pid, 'online_bookings'):
            items = []
            for sv in db.execute(f'SELECT s.id,s.title,s.price,s.currency,s.duration_minutes FROM provider_services s WHERE {sq} AND s.active=1 ORDER BY s.title LIMIT 30', (pid,)).fetchall():
                slots = db.execute("SELECT slot_date,slot_time,spots_available FROM service_slots WHERE service_id=? AND status IN ('open','full') AND slot_date>=date('now') ORDER BY slot_date,slot_time LIMIT 3", (sv['id'],)).fetchall()
                sl = ''.join(f'<li>{e(x["slot_date"])} {e(x["slot_time"] or "")} · ' + (e(t('Completa')) if int(x['spots_available'] or 0) <= 0 else f'{int(x["spots_available"])} ' + e(t('plazas'))) + '</li>' for x in slots)
                items.append(f'<article><div><h2>{e(sv["title"])}</h2><p>{e(plan_money(sv["price"], sv["currency"] or "EUR"))}</p>{f"<ul>{sl}</ul>" if sl else ""}</div>'
                             f'<a href="{e(book(sv["id"]))}" target="_blank" rel="noopener">{e(t("Reservar"))}</a></article>')
            body = ''.join(items) or f'<p>{e(t("Todavía no hay actividades publicadas."))}</p>'
        else:
            link = f'{public_site_url()}/#/centro?id={pid}' if ptype == 'center' else f'{public_site_url()}/#/profesional?id={pid}'
            body = f'<p>{e(t("Este centro todavía no tiene reserva online."))}</p><a href="{e(link)}" target="_blank" rel="noopener">{e(t("Solicitar información"))}</a>'
        doc = f'''<!doctype html><html lang="{e(lang)}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(name)}</title>
<style>body{{margin:0;font:14px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#011C3C;background:#fff}}header{{padding:12px 14px;background:#011C3C;color:#fff}}header b{{font-size:15px}}
main{{padding:10px 14px;display:grid;gap:10px}}article{{display:flex;gap:10px;justify-content:space-between;align-items:center;border:1px solid #dfe6e7;border-radius:10px;padding:10px 12px}}
h2{{font-size:15px;margin:0}}p{{margin:2px 0;color:#5f717b}}ul{{margin:4px 0 0;padding-left:16px;color:#5f717b;font-size:12px}}a{{background:#076898;color:#fff;text-decoration:none;font-weight:700;padding:9px 14px;border-radius:999px;white-space:nowrap}}
footer{{padding:8px 14px;font-size:11px;color:#5f717b}}footer a{{background:none;color:#076898;padding:0}}</style></head>
<body><header><b>{e(name)}</b></header><main>{body}</main><footer>{e(t("Reservas con"))} <a href="{e(public_site_url())}" target="_blank" rel="noopener">WORLDIVES DISCOVERY</a></footer></body></html>'''
        raw = doc.encode('utf-8')
        self.send_response(200); self.send_header('Content-Type', 'text/html; charset=utf-8'); self.send_header('Content-Length', str(len(raw)))
        self.send_header('Cache-Control', 'public, max-age=300'); self.send_header('X-Content-Type-Options', 'nosniff'); self.send_header('Referrer-Policy', 'strict-origin-when-cross-origin')
        # Embeddable anywhere, but nothing runs inside: no scripts, no forms.
        self.send_header('Content-Security-Policy', "default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:; frame-ancestors *; base-uri 'none'; form-action 'none'")
        if os.environ.get('WOD_PUBLIC_URL', '').strip().lower().startswith('https://'): self.send_header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains')   # ASVS V3.4.1
        self._sec_sent = True; self.end_headers(); self.wfile.write(raw)

    def security_headers(self, csp=True):
        self._sec_sent = True
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.send_header('Referrer-Policy', 'strict-origin-when-cross-origin')
        self.send_header('Permissions-Policy', 'camera=(), microphone=(), geolocation=(self), payment=()')
        self.send_header('Cross-Origin-Opener-Policy', 'same-origin')
        if csp: self.send_header('Content-Security-Policy', CSP_HEADER)
        if wcfg.demo_mode(): self.send_header('X-Robots-Tag', 'noindex, nofollow')
        public_url = os.environ.get('WOD_PUBLIC_URL', '').strip().lower()
        if public_url.startswith('https://'):
            self.send_header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains')

    # Endpoints called by other servers (no browser, no cookie): they authenticate with their own signature or key.
    CSRF_EXEMPT = ('/api/payments/webhook', '/api/payments/webhook/connect', '/api/integrations/bookings', '/api/marketing/unsubscribe', '/api/whatsapp/webhook')

    def enforce_same_origin(self):
        """G10: every state-changing request from a browser must carry Origin (or Referer) and it must be our origin.
        Requests without both headers are rejected, except the server-to-server endpoints in CSRF_EXEMPT.
        The allowed origin is WOD_PUBLIC_URL (mandatory in production); in development it is the Host header."""
        path = urlparse(self.path).path
        if path in self.CSRF_EXEMPT:
            return
        origin = self.headers.get('Origin') or self.headers.get('Referer')
        if not origin or origin == 'null':
            raise PermissionError('Solicitud bloqueada: falta el origen de la petición.')
        try:
            source = urlparse(origin)
            allowed = os.environ.get('WOD_PUBLIC_URL', '').strip()
            allowed_origins = set()
            if allowed:
                target = urlparse(allowed)
                allowed_origins.add(f'{target.scheme}://{target.netloc}'.lower())
            else:
                host = self.headers.get('Host', '')
                allowed_origins.add(f"{wsec.request_scheme(self.client_address[0], self.headers)}://{host}".lower())
            for extra in wcfg.env('WOD_ALLOWED_ORIGINS').split(','):
                if extra.strip(): allowed_origins.add(extra.strip().rstrip('/').lower())
            source_origin = f'{source.scheme}://{source.netloc}'.lower()
            if source_origin.rstrip('/') not in {a.rstrip('/') for a in allowed_origins}:
                raise PermissionError('Solicitud bloqueada por origen no autorizado.')
        except PermissionError:
            raise
        except Exception:
            raise PermissionError('Solicitud bloqueada por origen no autorizado.')

    def accepts_gzip(self):
        return 'gzip' in (self.headers.get('Accept-Encoding') or '').lower()

    def send_prebuilt_json(self, raw, gz):
        use_gz=self.accepts_gzip(); body=gz if use_gz else raw
        self.send_response(200)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        if use_gz: self.send_header('Content-Encoding', 'gzip')
        self.send_header('Vary', 'Accept-Encoding')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.security_headers()
        self.end_headers()
        self.wfile.write(body)

    def send_json(self, payload, status=200):
        raw = json.dumps(with_instants(payload), ensure_ascii=False, separators=(',',':')).encode('utf-8')
        gz = len(raw) > 1400 and self.accepts_gzip()
        if gz: raw = gzip_bytes(raw)
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        if gz: self.send_header('Content-Encoding', 'gzip')
        self.send_header('Vary', 'Accept-Encoding')
        self.send_header('Content-Length', str(len(raw)))
        self.send_header('Cache-Control', 'no-store')
        self.security_headers()
        self.end_headers()
        self.wfile.write(raw)

    def send_range_file(self, path: Path, content_type):
        """Large static file with HTTP Range (PMTiles clients read small byte ranges of a file of several GB)."""
        if not path.exists() or not path.is_file(): self.send_error(404); return
        size = path.stat().st_size; etag = f'"{int(path.stat().st_mtime_ns):x}-{size:x}"'
        rng = self.headers.get('Range', ''); start, end = 0, size - 1; partial = False
        m = re.fullmatch(r'bytes=(\d*)-(\d*)', rng.strip()) if rng else None
        if rng and not m:
            self.send_response(416); self.send_header('Content-Range', f'bytes */{size}'); self.security_headers(); self.end_headers(); return
        if m:
            a, b = m.group(1), m.group(2)
            if a == '' and b == '': self.send_response(416); self.send_header('Content-Range', f'bytes */{size}'); self.security_headers(); self.end_headers(); return
            if a == '': start = max(0, size - int(b))
            else: start = int(a); end = min(size - 1, int(b)) if b else size - 1
            if start >= size or start > end:
                self.send_response(416); self.send_header('Content-Range', f'bytes */{size}'); self.security_headers(); self.end_headers(); return
            partial = True
        length = end - start + 1
        if length > 64 * 1024 * 1024: end = start + 64 * 1024 * 1024 - 1; length = end - start + 1
        self.send_response(206 if partial else 200)
        self.send_header('Content-Type', content_type); self.send_header('Accept-Ranges', 'bytes'); self.send_header('ETag', etag)
        self.send_header('Content-Length', str(length)); self.send_header('Cache-Control', 'public, max-age=86400')
        if partial: self.send_header('Content-Range', f'bytes {start}-{end}/{size}')
        self.security_headers(); self.end_headers()
        if self.command == 'HEAD': return
        with path.open('rb') as fh:
            fh.seek(start); left = length
            while left > 0:
                chunk = fh.read(min(262144, left))
                if not chunk: break
                self.wfile.write(chunk); left -= len(chunk)

    def send_file(self, path: Path, content_type=None):
        if not path.exists() or not path.is_file():
            self.send_error(404)
            return
        ct = content_type or mimetypes.guess_type(path.name)[0] or 'application/octet-stream'
        if (ct.startswith('text/') or ct.endswith(('+xml', '/xml', '/javascript', '/json', '+json'))) and 'charset' not in ct: ct += '; charset=utf-8'   # ASVS V4.1.1
        st = path.stat()
        etag = f'"{int(st.st_mtime_ns):x}-{st.st_size:x}"'
        # Images and uploads change name when they change, so browsers may keep them a week;
        # code, styles and the page are revalidated on every visit (cheap 304 thanks to the ETag).
        cache = 'public, max-age=604800' if ct.startswith(('image/','font/')) else 'no-cache'
        uploaded = str(path).startswith(str(PHOTOS)) or str(path).startswith(str(UPLOADS))
        if self.headers.get('If-None-Match') == etag:
            self.send_response(304)
            self.send_header('ETag', etag)
            self.send_header('Cache-Control', cache)
            self.security_headers()
            self.end_headers()
            return
        raw = path.read_bytes()
        gz = (ct.startswith(('text/','application/javascript','application/json','application/manifest','image/svg')) and len(raw) > 1400 and self.accepts_gzip())
        if gz:
            key=(str(path),etag)
            cached=_GZIP_CACHE.get(key)
            if cached is None:
                cached=gzip_bytes(raw, 6)
                if len(_GZIP_CACHE) > 64: _GZIP_CACHE.clear()
                _GZIP_CACHE[key]=cached
            raw=cached
        self.send_response(200)
        self.send_header('Content-Type', ct)
        if gz: self.send_header('Content-Encoding', 'gzip')
        self.send_header('Vary', 'Accept-Encoding')
        self.send_header('Content-Length', str(len(raw)))
        self.send_header('ETag', etag)
        self.send_header('Cache-Control', cache)
        self.security_headers(csp=not uploaded)
        if uploaded: self.send_header('Content-Security-Policy', UPLOAD_CSP)   # ASVS V3.2.1
        self.end_headers()
        self.wfile.write(raw)

    def send_private_file(self, path: Path, download_name: str, inline: bool = True):
        """Private documents (G8): never cached by browsers or proxies, always with Content-Disposition."""
        raw = path.read_bytes()
        ct = wsec.DOCUMENT_TYPES.get(path.suffix.lower(), 'application/octet-stream')
        # The name offered keeps the real extension of the file, never the one it was uploaded with (ASVS V5.4.1).
        download_name = (Path(download_name or path.name).stem[:100] or 'documento') + path.suffix.lower()
        safe = re.sub(r'[^A-Za-z0-9._-]+', '_', download_name)[:120] or path.name
        self.send_response(200)
        self.send_header('Content-Type', ct)
        self.send_header('Content-Length', str(len(raw)))
        self.send_header('Cache-Control', 'private, no-store, max-age=0')
        self.send_header('Pragma', 'no-cache')
        self.send_header('Content-Disposition', f"{'inline' if inline else 'attachment'}; filename=\"{safe}\"; filename*=UTF-8''{quote(download_name)}")
        self.send_header('X-Robots-Tag', 'noindex')
        # An image uploaded by somebody runs nothing on our address, even opened on its own (ASVS V3.2.1).
        self.security_headers(csp=not ct.startswith('image/'))
        if ct.startswith('image/'): self.send_header('Content-Security-Policy', UPLOAD_CSP)
        self.end_headers()
        self.wfile.write(raw)

    def send_bytes(self, raw: bytes, content_type: str, filename: str | None = None, cache: str = 'no-store', inline: bool = False):
        """Generated files (PDF, SVG, CSV, ICS…) with the same security headers as every other answer."""
        self.send_response(200)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(raw)))
        self.send_header('Cache-Control', cache)
        if filename:
            safe = re.sub(r'[^A-Za-z0-9._-]+', '_', filename)[:120]
            self.send_header('Content-Disposition', f"{'inline' if inline else 'attachment'}; filename=\"{safe}\"")
        self.security_headers()
        self.end_headers()
        self.wfile.write(raw)

    def redirect(self, location):
        self.send_response(302)
        self.send_header('Location', location)
        self.security_headers()
        self.end_headers()

    def end_headers(self):
        # Any answer that did not add them explicitly (error pages, 30x…) still carries the security headers.
        if not getattr(self, '_sec_sent', True): self.security_headers()
        super().end_headers()
        if self.command == 'HEAD':
            # HEAD (uptime monitors, link checkers): same headers as GET, body discarded.
            self.wfile.flush(); self.wfile = _NullWriter()

    def do_HEAD(self):
        self.do_GET()

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        query = parse_qs(parsed.query)
        # Static files are served without touching the database.
        if path.startswith('/tiles/') and path.endswith('.pmtiles'):
            p = pmtiles_path()
            if not p or Path(unquote(path)).name != p.name: self.send_error(404); return
            self.send_range_file(p, 'application/vnd.pmtiles'); return
        if path.startswith('/assets/uploads/'):
            candidate=(PHOTOS/unquote(path)[len('/assets/uploads/'):]).resolve()
            if not candidate.is_relative_to(PHOTOS.resolve()): self.send_error(403); return
            self.send_file(candidate); return
        if path.startswith('/assets/'):
            target=legacy_asset_url(path)
            if not target: self.send_error(404); return
            self.send_response(301); self.send_header('Location',target+(('?'+parsed.query) if parsed.query else '')); self.send_header('Cache-Control','public, max-age=86400')
            self.send_header('Content-Length','0'); self.security_headers(); self.end_headers(); return
        if path.startswith(STATIC_PREFIXES) or path in PUBLIC_ROOT_FILES:
            candidate=(PUBLIC/unquote(path).lstrip('/')).resolve()
            if not candidate.is_relative_to(PUBLIC.resolve()): self.send_error(403); return
            self.send_file(candidate, PUBLIC_ROOT_FILES.get(path)); return
        if path == '/app/vuelta':
            # v50.48: after paying in the browser tab (Stripe), back into the app with its own scheme.
            q = {k: v[0] for k, v in query.items()}
            scheme = wmovil.app_scheme(q.get('esquema'))
            if not scheme: self.send_error(404); return
            body = wmovil.return_page(scheme, q).encode('utf-8')
            self.send_response(200); self.send_header('Content-Type', 'text/html; charset=utf-8'); self.send_header('Cache-Control', 'no-store')
