                        uid=db.execute('INSERT INTO users(fullname,email,username,password_hash,role,created_at,email_verified_at) VALUES(?,?,?,?,?,?,?)',(name,inv['email'],username,hash_password(pw),'recreational',now(),now())).lastrowid
