                        db.execute("UPDATE bookings SET status='confirmed',confirmed_at=?,accepted_at=COALESCE(accepted_at,?),updated_at=? WHERE id=?",(now(),now(),now(),bid))
                        notify_booking(db,bid,'confirmed')
