def check_production_settings():
    """WOD_ENV=production refuses to start with unsafe settings."""
    problems = []
    if not wcfg.public_url(): problems.append('WOD_PUBLIC_URL es obligatorio en producción (por ejemplo https://worldivesdiscovery.com).')
    elif not wcfg.public_url().startswith('https://'): problems.append('WOD_PUBLIC_URL debe empezar por https:// en producción.')
    if wcfg.env_flag('WOD_ALLOW_SETUP'): problems.append('WOD_ALLOW_SETUP=1 no se permite en producción: crea el administrador con --create-admin.')
    if len(wcfg.env('WOD_SECRET_KEY')) < 32: problems.append('Define WOD_SECRET_KEY con al menos 32 caracteres aleatorios.')
    if wcfg.env_flag('WOD_DEBUG'): problems.append('WOD_DEBUG no puede estar activo en producción.')
    if not admin_totp_required(): problems.append('WOD_ADMIN_TOTP_REQUIRED=0 no se permite en producción: los administradores usan verificación en dos pasos.')
    if not payments_totp_required(): problems.append('WOD_PAYMENTS_TOTP_REQUIRED=0 no se permite en producción: quien cobra online usa verificación en dos pasos.')
    # v50.47: phones and WhatsApp credentials are encrypted with this key (never derived in production).
    if wcfg.env('WOD_DATA_KEY') == wcif.DEMO_DATA_KEY: problems.append('WOD_DATA_KEY es la clave de los datos ficticios de pruebas: genera una propia.')
    if len(wcfg.env('WOD_DATA_KEY')) < 32: problems.append('Define WOD_DATA_KEY (clave de cifrado de teléfonos y credenciales) con al menos 32 caracteres aleatorios: python3 -c "import secrets;print(secrets.token_urlsafe(32))".')
    # v50.51 (ASVS 5.0): mail always encrypted, a real key for the copies, no test hooks pointing at local simulators.
    if wcfg.env('WOD_SMTP_HOST') and (wcfg.env('WOD_SMTP_SECURITY') or 'starttls').lower() not in ('starttls', 'ssl'):
        problems.append('WOD_SMTP_SECURITY debe ser starttls o ssl en producción (el correo nunca viaja sin cifrar).')
    if wcfg.env('WOD_BACKUP_KEY') and len(wcfg.env('WOD_BACKUP_KEY')) < 32:
        problems.append('WOD_BACKUP_KEY debe tener al menos 32 caracteres aleatorios: python3 -c "import secrets;print(secrets.token_urlsafe(32))".')
    for k in sorted(k for k in os.environ if k.endswith('_API_BASE') and k.startswith(('WOD_', 'STRIPE_', 'WHATSAPP_'))):
        if wcfg.env(k): problems.append(f'{k} es solo para pruebas (apunta a un simulador): quítala del .env de producción.')
    for k in ('WHATSAPP_GRAPH_BASE', 'WOD_ARCGIS_TILE_URL', 'WOD_MEDIA_FETCH_BASE'):   # ASVS V15.2.3: hooks of the tests
        if wcfg.env(k): problems.append(f'{k} es solo para pruebas (apunta a un simulador): quítala del .env de producción.')
    if wcfg.env('WOD_GEOCODER_URL') and not wcfg.env('WOD_GEOCODER_URL').startswith('https://'):
        problems.append('WOD_GEOCODER_URL tiene que empezar por https:// en producción.')
    if wcfg.env_flag('WHATSAPP_ENABLED'):
        for k in ('WHATSAPP_APP_ID', 'WHATSAPP_APP_SECRET', 'WHATSAPP_VERIFY_TOKEN', 'WHATSAPP_CONFIG_ID'):
            if not wcfg.env(k): problems.append(f'WHATSAPP_ENABLED=1 necesita {k} en el .env (ver docs/notas-de-version/v50.47.md).')
    return problems


def production_warnings():
    """Settings that do not stop the server but should be fixed before real users arrive."""
    out = []
    if not os.environ.get('WOD_SMTP_HOST', '').strip(): out.append('Sin WOD_SMTP_HOST: los correos esperan en la cola (72 h) hasta configurar el proveedor (docs/despliegue/README.md).')
    if not os.environ.get('STRIPE_SECRET_KEY', '').strip(): out.append('Sin STRIPE_SECRET_KEY: los cobros online están desactivados.')
    p = pmtiles_path()
    if p and not p.exists(): out.append(f'Falta el mapa base {p} (Protomaps PMTiles): sin él los mapas no muestran fondo. Ver docs/mapas.md.')
    if not arcgis_key(): out.append('Sin ARCGIS_API_KEY: la vista satélite no aparece.')
    if not os.environ.get('STRIPE_CONNECT_WEBHOOK_SECRET', '').strip(): out.append('Sin STRIPE_CONNECT_WEBHOOK_SECRET: los pagos se confirman solo al volver de Stripe y por la revisión periódica.')
    return out


def create_admin_cli(argv):
    """python app/server.py --create-admin [--email E] [--username U] [--name N]
    The password is asked on the terminal (or read from WOD_ADMIN_PASSWORD for automated installs)."""
    import getpass
    def arg(flag):
        if flag in argv:
            i = argv.index(flag)
            if i + 1 < len(argv): return argv[i + 1]
        return None
    bootstrap()
    email = (arg('--email') or input('Email del administrador: ')).strip().lower()
    username = (arg('--username') or input('Usuario: ')).strip()
    name = (arg('--name') or input('Nombre y apellidos: ')).strip()
    password = os.environ.get('WOD_ADMIN_PASSWORD') or getpass.getpass('Contraseña (mínimo 10 caracteres): ')
    if not os.environ.get('WOD_ADMIN_PASSWORD') and getpass.getpass('Repite la contraseña: ') != password:
        print('Las contraseñas no coinciden.'); return 1
    problem = wsec.password_problem(password)
    if problem: print(problem); return 1
    if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email) or not username or not name:
        print('Email, usuario y nombre son obligatorios.'); return 1
    db = connect()
    try:
        if db.execute('SELECT 1 FROM users WHERE lower(email)=? OR lower(username)=lower(?)', (email, username)).fetchone():
            print('Ya existe una cuenta con ese email o usuario.'); return 1
        uid = db.execute("INSERT INTO users(fullname,email,username,password_hash,role,requested_role,created_at,email_verified_at) VALUES(?,?,?,?,'admin','admin',?,?)",
                         (name, email, username, hash_password(password), now(), now())).lastrowid
        db.execute('INSERT OR IGNORE INTO user_profiles(user_id,updated_at) VALUES(?,?)', (uid, now()))
        record_acceptances(db, uid, ['terminos', 'privacidad', 'centros'])
        audit(db, uid, 'admin_created_cli', 'user', uid); db.commit()
    finally:
        db.close()
    print(f'Administrador creado: {username} <{email}>. Entra en la web y activa la verificación en dos pasos.')
    return 0


def report_center_accounts():
    """python app/server.py --report-center-accounts: how every centre/freelance account got its role (G2 review)."""
    bootstrap()
    db = connect()
    try:
        rows = db.execute("SELECT u.id,u.fullname,u.email,u.role,u.center_id,u.created_at,c.name AS center FROM users u LEFT JOIN centers c ON c.id=u.center_id WHERE u.role IN ('center','freelance') ORDER BY u.id").fetchall()
        print(f'Cuentas profesionales: {len(rows)}')
        for u in rows:
            reg = db.execute("SELECT details,created_at FROM audit_log WHERE action='register' AND entity_id=? ORDER BY id LIMIT 1", (u['id'],)).fetchone()
            claim = db.execute('SELECT status,verification_method,reviewed_by_user_id FROM center_claims WHERE user_id=? ORDER BY id DESC LIMIT 1', (u['id'],)).fetchone()
            how = 'aprobada por el administrador (' + (claim['verification_method'] or 'sin método registrado') + ')' if claim and claim['status'] == 'approved' else 'SIN aprobación registrada: revisar'
            print(f"- #{u['id']} {u['fullname']} <{u['email']}> rol={u['role']} centro={u['center'] or '-'} alta={u['created_at']} · {how} · registro: {reg['details'] if reg else 'sin registro'}")
        orphan = db.execute("SELECT id,center_id,requested_center_name,status FROM center_claims WHERE user_id NOT IN (SELECT id FROM users)").fetchall()
        for c in orphan: print(f"- Solicitud #{c['id']} «{c['requested_center_name']}» sin cuenta asociada (estado {c['status']}).")
        legacy = db.execute("SELECT entity_id,details,created_at FROM audit_log WHERE action='register' AND details LIKE '%\"requested_role\": \"center\"%'").fetchall()
        for a in legacy: print(f"- Registro histórico como centro (usuario #{a['entity_id'] or '?'}, {a['created_at']}): {a['details']}")
    finally:
        db.close()
    return 0


def main():
    if '--create-admin' in sys.argv: raise SystemExit(create_admin_cli(sys.argv))
    if '--report-center-accounts' in sys.argv: raise SystemExit(report_center_accounts())
    if '--backup-now' in sys.argv:
        out = wbackup.backup_db(DB_PATH); print(f'Copia creada: {out} ({wbackup.verify(out)})'); err = wbackup.ship(out)
        if err: print('Copia externa fallida: ' + err)
        raise SystemExit(1 if err else 0)
    if '--verify-backup' in sys.argv:
        p = Path(sys.argv[sys.argv.index('--verify-backup') + 1]); print(f'{p.name}: {wbackup.verify(p)}'); raise SystemExit(0)
    if '--restore' in sys.argv:
        p = Path(sys.argv[sys.argv.index('--restore') + 1])
        print('Comprobando la copia: ' + wbackup.verify(p))
        if '--yes' not in sys.argv: print('Para el servidor y repite con --yes para restaurar.'); raise SystemExit(1)
        aside = wbackup.restore(p, DB_PATH); print(f'Base restaurada en {DB_PATH}.' + (f' La anterior se ha guardado en {aside}.' if aside else '')); raise SystemExit(0)
    if wcfg.is_production():
        problems = check_production_settings()
        if problems:
            print('No se puede arrancar en producción:'); [print(' - ' + p) for p in problems]; raise SystemExit(2)
        for w in production_warnings(): print('Aviso: ' + w)
    demo_problem = demo_guard()
    if demo_problem: print('No se puede arrancar: ' + demo_problem); raise SystemExit(2)
    new_install = False
    if not DB_PATH.exists() and not os.environ.get('WOD_EMPTY_DB'):
        # v50.45 (encargo 2b · bloque 1): the base is created on the first start. The production zip carries the
        # catalogue of dive points (without centres, users or bookings) in data/seed/; development uses the demo.
        seed = ROOT / 'data' / 'seed' / 'catalogo.sqlite3'
        demo = ROOT / 'data' / 'demo' / 'catalogo-demo.sqlite3'
        src = seed if seed.exists() else (demo if demo.exists() and not wcfg.is_production() else None)
        if src:
            import shutil
            DB_PATH.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(src, DB_PATH)
            print(f'Base nueva {DB_PATH} creada a partir de {src.relative_to(ROOT)}.')
            new_install = True
    bootstrap()
    if new_install:
        # v50.51: a new installation starts with the catalogue of species (own illustrations, licence «Ilustración propia»).
        with connect() as _db:
            if not _db.execute('SELECT 1 FROM species LIMIT 1').fetchone():
                print(f'Catálogo de especies: {load_example_species(_db)} especies de ejemplo.'); _db.commit()
    print(f'WORLDIVES DISCOVERY v{APP_VERSION} -> http://127.0.0.1:{PORT}')
    # Optional multi-process mode (Linux/macOS): WOD_WORKERS=4 starts 4 processes sharing the port.
    # Sessions live in the database, so any process can serve any user.
    workers=max(1,int(os.environ.get('WOD_WORKERS','1') or 1))
    reuse=workers>1 and hasattr(os,'fork') and hasattr(socket,'SO_REUSEPORT')
    if workers>1 and not reuse: print('WOD_WORKERS solo está disponible en Linux/macOS; se usa un único proceso.')
    pool_drain()   # no connection opened before fork() passes to the child processes
    if reuse:
        WodHTTPServer.allow_reuse_port=True
        for _ in range(workers-1):
            if os.fork()==0: break
    try:
        s=WodHTTPServer((HOST,PORT),Handler)
    except OSError as e:
        print(f'No se puede abrir el puerto {PORT}: {e}')
        raise
    threading.Thread(target=warm_snapshots, name='warm-up', daemon=True).start()
    threading.Thread(target=sweep_payment_orders, name='payments-sweeper', daemon=True).start()
    # Only one process (WOD_WORKERS may start several) sends emails and runs the periodic jobs.
    is_worker = email_worker_lock()
    if is_worker: threading.Thread(target=maintenance_loop, name='maintenance', daemon=True).start()
    if is_worker: threading.Thread(target=email_scheduler, name='email-sender', daemon=True).start()
    if is_worker: threading.Thread(target=notice_loop, name='notices', daemon=True).start()
    s.serve_forever()


_MAIL_LOCK = None
def email_worker_lock():
    """Only one process sends emails and runs the hourly jobs (WOD_WORKERS may start several)."""
    global _MAIL_LOCK
    try:
        import fcntl
        _MAIL_LOCK = open(DATA / '.email-worker.lock', 'w')
        fcntl.flock(_MAIL_LOCK, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return True
    except ImportError:
        return True
    except OSError:
        return False


def warm_snapshots():
    """Build the public catalogue snapshots as soon as the process starts, so the first visitors do not wait."""
    db=None
    try:
        db=connect()
        for snap in (POINTS, DIRECTORY, DIVE_TYPES, TRAVEL, SITE_MEDIA, PROMOS): snap.get(db)
    except Exception as e:
        sys.stderr.write(f'[warm-up] {type(e).__name__}: {e}\n')
    finally:
        if db is not None: db.close()

if __name__=='__main__':
    main()
